/* لمّة — a bright family game show: warm daylight, confetti-coloured pieces, white cards that pop.
   Every game and team owns one cheerful colour. Light is the default; night mode is opt-in. */
:root{
  color-scheme:light;
  --bg:#fff8ee; --bg-2:#fff0dc; --surface:#ffffff; --surface-2:#f7f3ff; --surface-3:#ece4ff;
  --line:rgba(52,30,120,.10); --line-2:rgba(52,30,120,.17); --ink:#c9bff0; --fg:#1d1446; --fg-2:#524a7a; --fg-3:#8a83aa;
  --glow-a:rgba(255,190,40,.34); --glow-b:rgba(255,92,150,.24); --glow-c:rgba(40,170,245,.24); --dots:rgba(52,30,120,.055);
  --spot:radial-gradient(closest-side,rgba(255,255,255,.98),rgba(255,255,255,.55) 70%,transparent);
  --saffron:#ffb703; --on-saffron:#3a2500;
  --pome:#ff4d6d;    --on-pome:#ffffff;
  --mint:#10c49a;    --on-mint:#03382b;
  --sky:#1f9ff0;     --on-sky:#ffffff;
  --grape:#7c4dff;   --on-grape:#ffffff;
  --rose:#ff4fa7;    --on-rose:#ffffff;
  --orange:#ff7b1c;  --on-orange:#ffffff;
  --lime:#82c91e;    --on-lime:#1c3000;
  --good:#12b76a;    --on-good:#ffffff;
  --bad:#f0384f;     --on-bad:#ffffff;
  --f-display:"Baloo Bhaijaan 2","Rubik","Segoe UI",Tahoma,sans-serif;
  --f-body:"Rubik","Segoe UI",Tahoma,"Noto Sans Arabic",Arial,sans-serif;
  --r-xl:28px; --r-lg:22px; --r:16px; --r-sm:12px;
  --fs-xs:.8rem; --fs-sm:.92rem; --fs-md:1rem; --fs-lg:1.2rem; --fs-xl:1.5rem;
  --fs-2xl:clamp(1.8rem,4vw,2.6rem); --fs-hero:clamp(2.6rem,7vw,4.6rem); --fs-q:clamp(1.4rem,3.2vw,2.4rem);
  --shadow:0 14px 34px -16px rgba(80,50,170,.28),0 2px 6px -2px rgba(80,50,170,.08);
  --lip:rgba(40,20,90,.22);
}
:root[data-theme="dark"]{
  color-scheme:dark;
  --bg:#130d33; --bg-2:#1a1342; --surface:#231a56; --surface-2:#2d2269; --surface-3:#3a2d82;
  --line:rgba(255,255,255,.1); --line-2:rgba(255,255,255,.18); --ink:#0a0622; --fg:#fcfaff; --fg-2:#cdc4f4; --fg-3:#9a8fd0;
  --glow-a:rgba(255,197,49,.20); --glow-b:rgba(255,79,123,.20); --glow-c:rgba(51,200,255,.18); --dots:rgba(255,255,255,.035);
  --spot:radial-gradient(closest-side,rgba(255,255,255,.16),rgba(255,255,255,.04) 70%,transparent);
  --saffron:#ffc531; --on-saffron:#2b1a00; --pome:#ff4f7b; --on-pome:#2e0412; --mint:#2fe0a8; --on-mint:#022a1d;
  --sky:#3bc3ff; --on-sky:#021a2c; --grape:#a685ff; --on-grape:#170b3d; --rose:#ff7ad1; --on-rose:#33062a;
  --orange:#ff8a3d; --on-orange:#2e1000; --lime:#b6ec4a; --on-lime:#1a2600; --good:#3ddc84; --on-good:#032213; --bad:#ff5a64; --on-bad:#2b0507;
  --shadow:0 18px 40px -18px rgba(0,0,0,.6); --lip:rgba(0,0,0,.45);
}

*,*::before,*::after{box-sizing:border-box}
html{-webkit-text-size-adjust:100%;height:100%}
body{background:var(--bg);color:var(--fg);font-family:var(--f-body);font-size:var(--fs-md);line-height:1.6;min-height:100%;overflow-x:hidden}
body.no-scroll{overflow:hidden}
body::before{content:"";position:fixed;inset:0 0 auto;height:env(safe-area-inset-top,0px);z-index:30;background:var(--bg)}
button,input,select,textarea{font:inherit;color:inherit}
a{color:var(--sky)}
:focus-visible{outline:3px solid var(--sky);outline-offset:2px}
h1,h2,h3,h4{font-family:var(--f-display);font-weight:800;line-height:1.25;margin:0;text-wrap:balance}
p{margin:0}
ul,ol{margin:0;padding:0;list-style:none}
.gut{padding-left:max(16px,env(safe-area-inset-left,0px));padding-right:max(16px,env(safe-area-inset-right,0px))}
.muted{color:var(--fg-2)}
.faint{color:var(--fg-3)}
.ic{width:1.15em;height:1.15em;flex:none;stroke:currentColor;fill:none;stroke-width:2.2;stroke-linecap:round;stroke-linejoin:round;vertical-align:-.2em}
.spin{animation:spin 1s linear infinite}
@keyframes spin{to{transform:rotate(360deg)}}

/* 3D illustrations */
.em{display:inline-block;width:var(--s,1.25em);height:var(--s,1.25em);background:center/contain no-repeat;flex:none;vertical-align:middle;font-style:normal}
.em-txt{width:auto;height:auto;font-size:var(--s,1.25em);line-height:1}
.fl{display:inline-block;width:var(--s,48px);aspect-ratio:4/3;height:auto;background:center/cover no-repeat;border-radius:10%;box-shadow:0 0 0 1px var(--line-2),0 8px 18px -8px rgba(0,0,0,.5);flex:none;max-width:100%}
.float{animation:float var(--t,5.5s) ease-in-out var(--d,0s) infinite alternate}
@keyframes float{from{transform:translateY(0) rotate(-3deg)}to{transform:translateY(-9px) rotate(3deg)}}
.pop-in{animation:popin .45s cubic-bezier(.2,1.4,.4,1) both;animation-delay:var(--d,0s)}
@keyframes popin{from{transform:scale(.4) translateY(14px);opacity:0}to{transform:none;opacity:1}}

/* daylight set: soft colour washes and a sprinkle of confetti */
.lights{position:fixed;inset:0;z-index:0;pointer-events:none;overflow:hidden;
  background:radial-gradient(circle at center,var(--dots) 1.3px,transparent 1.7px) 0 0/26px 26px,linear-gradient(180deg,var(--bg),var(--bg-2))}
.lights i{position:absolute;border-radius:50%;filter:blur(60px)}
.lights i:nth-child(1){width:44vmax;height:44vmax;top:-20vmax;inset-inline-end:-14vmax;background:var(--glow-a)}
.lights i:nth-child(2){width:38vmax;height:38vmax;top:34vh;inset-inline-start:-20vmax;background:var(--glow-b)}
.lights i:nth-child(3){width:40vmax;height:40vmax;bottom:-24vmax;inset-inline-end:8vmax;background:var(--glow-c)}
.app{position:relative;z-index:1;min-height:100%;display:flex;flex-direction:column}

/* header */
.hdr{position:sticky;top:env(safe-area-inset-top,0px);z-index:20;background:var(--surface);background:color-mix(in srgb,var(--surface) 78%,transparent);box-shadow:0 6px 20px -16px rgba(80,50,170,.4);backdrop-filter:blur(14px) saturate(1.3);-webkit-backdrop-filter:blur(14px) saturate(1.3);border-bottom:1px solid var(--line)}
.hdr-in{max-width:1220px;margin:0 auto;display:flex;align-items:center;gap:8px;padding-block:10px}
.brand{display:flex;align-items:center;gap:8px;color:var(--fg);background:none;border:0;padding:2px 4px;cursor:pointer;border-radius:14px}
.brand svg{width:40px;height:40px;flex:none;filter:drop-shadow(0 4px 8px rgba(255,77,109,.3))}
.brand b{font-family:var(--f-display);font-weight:800;font-size:1.8rem;line-height:1;color:var(--fg);letter-spacing:-.01em}
.brand b span{color:var(--pome)}
.hdr-nav{margin-inline-start:auto;display:flex;gap:6px;align-items:center}
.icon-btn{display:inline-grid;place-items:center;width:42px;height:42px;border-radius:14px;border:1px solid var(--line-2);background:var(--surface);color:var(--fg);cursor:pointer;flex:none;-webkit-tap-highlight-color:transparent;transition:transform .12s,background .15s}
.icon-btn:hover{background:var(--surface-2)}
.icon-btn:active{transform:scale(.94)}
.icon-btn[aria-current="page"],.icon-btn[aria-pressed="true"]{background:var(--saffron);color:var(--on-saffron);border-color:transparent}
.icon-btn:disabled{opacity:.35;cursor:not-allowed}
.icon-btn .ic{width:20px;height:20px}
@media (max-width:520px){
  .hdr-nav [data-nav="home"],.hdr-nav [data-nav="records"]{display:none}
  .hdr-nav{gap:5px}
  .brand b{font-size:1.5rem}
}
main{flex:1}
.wrap{max-width:1220px;margin:0 auto;padding-block:22px 110px;display:flex;flex-direction:column;gap:24px}
.narrow{max-width:780px}

/* buttons */
.btn{--b:var(--surface-3);--bf:var(--fg);display:inline-flex;align-items:center;justify-content:center;gap:.5em;font:700 var(--fs-md)/1.2 var(--f-display);color:var(--bf);
  background:linear-gradient(180deg,color-mix(in srgb,var(--b) 84%,#fff 16%),var(--b));border:0;border-radius:16px;padding:.72em 1.2em;min-height:48px;
  box-shadow:0 4px 0 color-mix(in srgb,var(--b) 70%,#2a1260),0 10px 22px -10px color-mix(in srgb,var(--b) 70%,transparent);cursor:pointer;text-decoration:none;text-align:center;
  transition:transform .09s ease,box-shadow .09s ease,filter .15s;-webkit-tap-highlight-color:transparent;user-select:none;position:relative}
.btn:hover{filter:brightness(1.06) saturate(1.05)}
.btn:active{transform:translateY(3px);box-shadow:0 1px 0 color-mix(in srgb,var(--b) 70%,#2a1260)}
.btn:disabled{opacity:.45;cursor:not-allowed;transform:none;filter:grayscale(.3)}
.btn.primary{--b:var(--saffron);--bf:var(--on-saffron)}
.btn.c{--b:var(--c);--bf:var(--on-c)}
.btn.good{--b:var(--good);--bf:var(--on-good)}
.btn.bad{--b:var(--bad);--bf:var(--on-bad)}
.btn.wa{--b:#25d366;--bf:#073b22}
.btn.ghost{background:var(--surface);box-shadow:inset 0 0 0 1.5px var(--line-2);color:var(--fg)}
.btn.ghost:active{transform:translateY(1px)}
.btn.sm{min-height:38px;padding:.42em .9em;font-size:var(--fs-sm);border-radius:12px;box-shadow:0 3px 0 color-mix(in srgb,var(--b) 70%,#2a1260)}
.btn.sm.ghost{box-shadow:inset 0 0 0 1.5px var(--line-2);background:var(--surface)}
.btn.xl{min-height:62px;font-size:1.25rem;padding:.7em 1.6em;border-radius:20px}
.btn.block{width:100%}
.btn .ic{width:1.15em;height:1.15em}
.btn .em{--s:1.5em}
.row{display:flex;flex-wrap:wrap;gap:10px;align-items:center}
.row.end{justify-content:flex-end}
.row.center{justify-content:center}
.row.nowrap{flex-wrap:nowrap}
.grow{flex:1;min-width:0}
.stack{display:flex;flex-direction:column;gap:12px}
.chip{display:inline-flex;align-items:center;gap:.4em;font-size:var(--fs-xs);font-weight:600;line-height:1.3;padding:.36em .8em;border-radius:999px;background:var(--surface-2);color:var(--fg-2);white-space:nowrap}
.chip.c{background:var(--c);color:var(--on-c)}
.chip .ic{width:1.1em;height:1.1em}
.chip .em{--s:1.35em}
.chips{display:flex;flex-wrap:wrap;gap:8px}
.badge{font-style:normal;font-size:.7rem;font-weight:700;padding:.12em .55em;border-radius:7px;background:var(--saffron);color:var(--on-saffron)}
.dot{width:10px;height:10px;border-radius:50%;background:var(--c,var(--fg-3));flex:none;display:inline-block}
.panel{background:var(--surface);border:1px solid var(--line);border-radius:var(--r-lg);padding:20px;display:flex;flex-direction:column;gap:14px;min-width:0;box-shadow:var(--shadow)}
.panel-h{display:flex;align-items:center;gap:10px;flex-wrap:wrap}
.panel-h h2,.panel-h h3{font-size:var(--fs-xl)}
.sec-title{display:flex;align-items:baseline;gap:12px;flex-wrap:wrap}
.sec-title h2{font-size:var(--fs-2xl)}
.inp{width:100%;min-width:0;background:var(--surface);border:2px solid var(--line-2);border-radius:14px;padding:.6em .9em;min-height:50px;color:var(--fg);font-weight:500}
.inp:focus{outline:none;border-color:var(--sky);background:var(--surface)}
.inp::placeholder{color:var(--fg-3)}
textarea.inp{min-height:90px;resize:vertical;line-height:1.5}
.seg{display:flex;flex-wrap:wrap;gap:6px}
.seg button{font:600 var(--fs-sm)/1.2 var(--f-body);padding:.55em 1em;min-height:42px;border-radius:12px;border:1.5px solid var(--line-2);background:var(--surface-2);color:var(--fg);cursor:pointer}
.seg button[aria-pressed="true"]{background:var(--c,var(--saffron));color:var(--on-c,var(--on-saffron));border-color:transparent;box-shadow:0 3px 0 color-mix(in srgb,var(--c,var(--saffron)) 68%,#2a1260)}
.field{display:flex;flex-direction:column;gap:8px}
.field-l{font-weight:600;font-size:var(--fs-sm);color:var(--fg-2)}
.toggle{display:flex;align-items:center;gap:12px;cursor:pointer;padding:6px 0}
.toggle input{appearance:none;-webkit-appearance:none;width:50px;height:30px;border-radius:99px;background:var(--surface-3);border:0;position:relative;cursor:pointer;flex:none;transition:background .15s}
.toggle input::after{content:"";position:absolute;top:3px;inset-inline-start:3px;width:24px;height:24px;border-radius:50%;background:#fff;box-shadow:0 2px 6px rgba(0,0,0,.3);transition:transform .18s cubic-bezier(.3,1.4,.5,1)}
.toggle input:checked{background:var(--mint)}
.toggle input:checked::after{transform:translateX(-20px)}
.notice{display:flex;gap:10px;align-items:flex-start;background:var(--surface-2);border-radius:14px;padding:12px 14px;font-size:var(--fs-sm);color:var(--fg-2)}
.notice .ic{color:var(--saffron);margin-top:2px}

/* ---------- home ---------- */
.hero{display:grid;gap:10px;align-items:center;grid-template-columns:minmax(0,1fr)}
@media (min-width:900px){.hero{grid-template-columns:minmax(0,1.05fr) minmax(0,.95fr);gap:30px}}
.hero-copy{display:flex;flex-direction:column;gap:18px;min-width:0}
.hero h1{font-size:var(--fs-hero);line-height:1.12}
.hero h1 mark{background:linear-gradient(90deg,var(--saffron),var(--rose));-webkit-background-clip:text;background-clip:text;color:transparent}
.hero-sub{font-size:var(--fs-lg);color:var(--fg-2);max-width:32em}
.eyebrow{font-size:var(--fs-sm);font-weight:600;color:var(--fg-2);display:inline-flex;align-items:center;gap:8px}
.stage{position:relative;width:min(100%,520px);aspect-ratio:1/.82;margin-inline:auto;order:-1}
@media (min-width:900px){.stage{order:0}}
.stage::before{content:"";position:absolute;inset:6% 10%;border-radius:50%;background:var(--spot)}
.stage .em{position:absolute;--s:clamp(54px,13vw,96px)}
.stage .hero-em{--s:clamp(130px,30vw,220px);left:50%;top:50%;margin:calc(var(--s) / -2) 0 0 calc(var(--s) / -2)}
.teaser{background:var(--surface);border:1px solid var(--line);border-radius:var(--r-xl);box-shadow:var(--shadow);padding:18px;display:grid;gap:16px;grid-template-columns:minmax(0,1fr);align-items:center}
@media (min-width:760px){.teaser{grid-template-columns:auto minmax(0,1fr) auto}}
.teaser-media{display:grid;place-items:center;min-width:120px}
.teaser-q{font-size:clamp(1.1rem,2.2vw,1.4rem);font-weight:600;line-height:1.5}
.teaser-a{display:inline-flex;align-items:center;gap:8px;background:var(--good);color:var(--on-good);border-radius:14px;padding:.45em .9em;font-family:var(--f-display);font-weight:800;font-size:1.2rem;animation:popin .4s cubic-bezier(.2,1.4,.4,1)}
.resume{display:flex;align-items:center;gap:14px;flex-wrap:wrap;background:var(--surface);border:2px dashed var(--saffron);border-radius:var(--r-lg);padding:14px 16px}
.resume .grow p{font-weight:700;font-family:var(--f-display);font-size:1.1rem}
.resume>.grow{flex:1 1 210px}
.resume>.row{flex:none;flex-wrap:nowrap}
.pulse{position:relative;overflow:hidden;isolation:isolate;display:grid;gap:12px 18px;grid-template-columns:minmax(0,1fr) minmax(0,1fr);align-items:stretch;padding:18px 20px;border-radius:var(--r-xl);color:#fff;background:radial-gradient(120% 140% at 0% 0%,rgba(255,255,255,.16),rgba(255,255,255,0) 52%),linear-gradient(135deg,#5b34f0,#25107a);box-shadow:0 16px 36px -20px rgba(37,16,122,.75)}
