@keyframes pulse-dot{0%{box-shadow:0 0 0 0 rgba(61,220,151,.7)}70%{box-shadow:0 0 0 9px rgba(61,220,151,0)}100%{box-shadow:0 0 0 0 rgba(61,220,151,0)}}
.pulse-st{display:flex;align-items:center;gap:14px;min-width:0;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.14);border-radius:var(--r-lg);padding:14px 16px}
