@media (min-width:900px){.pulse{grid-template-columns:minmax(170px,auto) minmax(0,1fr) minmax(0,1fr);align-items:center;padding:20px 24px}.pulse-h{grid-column:auto;flex-direction:column;align-items:flex-start}.pulse-st{justify-content:center;padding:16px 20px}}
@media (max-width:520px){.pulse{padding:14px;gap:10px}.pulse-st{flex-direction:column;align-items:flex-start;gap:8px;padding:12px}.pulse-ic{width:40px;height:40px;border-radius:12px}.pulse-ic svg{width:21px;height:21px}.pulse-st div>span{font-size:var(--fs-xs)}}
@media (prefers-reduced-motion:reduce){.pulse-live i{animation:none}}
.shelf{display:grid;gap:22px 18px;grid-template-columns:minmax(0,1fr);padding-top:16px}
@media (min-width:620px){.shelf{grid-template-columns:repeat(2,minmax(0,1fr))}.gcard.main,.gcard.wide{grid-column:span 2}}
/* 8 games: on a wide screen the big card and 7 others fill three rows of three */
@media (min-width:1040px){.shelf{grid-template-columns:repeat(3,minmax(0,1fr))}.gcard.wide{grid-column:auto}}
.gcard{position:relative;border-radius:var(--r-xl);padding:20px 18px 18px;display:flex;flex-direction:column;gap:10px;min-width:0;color:var(--on-c);isolation:isolate;
  background:radial-gradient(120% 80% at 85% 0%,color-mix(in srgb,var(--c) 70%,#fff 30%),var(--c) 55%,color-mix(in srgb,var(--c) 82%,#2a1260) 100%);
  box-shadow:0 6px 0 color-mix(in srgb,var(--c) 68%,#2a1260),0 22px 40px -22px color-mix(in srgb,var(--c) 80%,transparent);transition:transform .2s cubic-bezier(.2,1.2,.4,1)}
.gcard:hover{transform:translateY(-4px) rotate(-.4deg)}
.gcard .gc-em{--s:96px;position:absolute;top:-30px;inset-inline-end:10px;filter:drop-shadow(0 12px 14px rgba(0,0,0,.3))}
.gcard.main .gc-em{--s:150px;top:-44px}
.gcard-tag{align-self:flex-start;font-size:var(--fs-xs);font-weight:700;padding:.3em .8em;border-radius:99px;background:color-mix(in srgb,var(--on-c) 14%,transparent)}
.gcard-name{font-size:clamp(1.6rem,3vw,2rem);margin-top:22px;max-width:70%}
.gcard.main .gcard-name{font-size:clamp(2.1rem,4.6vw,3rem);margin-top:40px}
.gcard p{font-size:var(--fs-sm);opacity:.88;max-width:34em}
.gcard-meta{display:flex;flex-wrap:wrap;gap:6px}
.gcard-meta span{display:inline-flex;align-items:center;gap:5px;font-size:var(--fs-xs);font-weight:600;padding:.28em .7em;border-radius:99px;background:color-mix(in srgb,var(--on-c) 12%,transparent)}
.gcard-act{display:flex;gap:8px;margin-top:auto;padding-top:6px;flex-wrap:wrap}
