.stat span{font-size:var(--fs-xs);color:var(--fg-2)}
.foot{color:var(--fg-3);font-size:var(--fs-xs);text-align:center;padding-block:10px 0}
.foot-games{display:flex;flex-wrap:wrap;justify-content:center;gap:4px 14px;margin-top:18px;font-size:var(--fs-sm)}
.foot-games a{color:var(--fg-2);text-decoration:none}.foot-games a:hover{color:var(--fg);text-decoration:underline}
.foot-games a:first-child{font-weight:700}

/* ---------- setup wizard ---------- */
.setup-head{display:flex;gap:14px;align-items:center;flex-wrap:wrap}
.setup-head .grow{display:flex;align-items:center;gap:12px;min-width:min(100%,14em)}
.setup-head h1{font-size:var(--fs-2xl)}
.setup-head .em{--s:56px}
.steps-bar{display:flex;gap:8px;align-items:center}
.steps-bar button{flex:1;display:flex;align-items:center;gap:8px;justify-content:center;padding:10px 8px;border-radius:16px;border:1.5px solid var(--line-2);background:var(--surface);color:var(--fg-2);font:700 var(--fs-sm)/1.2 var(--f-display);cursor:pointer;min-width:0}
.steps-bar button span.n{display:grid;place-items:center;width:26px;height:26px;border-radius:50%;background:var(--surface-3);color:var(--fg);flex:none;font-size:.85rem}
.steps-bar button[aria-current="step"]{background:var(--c,var(--saffron));color:var(--on-c,var(--on-saffron));border-color:transparent;box-shadow:0 4px 0 color-mix(in srgb,var(--c,var(--saffron)) 68%,#2a1260)}
.steps-bar button[aria-current="step"] span.n{background:rgba(0,0,0,.18);color:inherit}
.steps-bar button.done span.n{background:var(--good);color:var(--on-good)}
.steps-bar button b{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.teams{display:grid;gap:12px;grid-template-columns:repeat(auto-fill,minmax(min(46%,230px),1fr))}
.team-card{position:relative;background:var(--surface);border:1px solid var(--line);border-radius:22px;padding:18px 16px 16px;display:flex;flex-direction:column;align-items:center;gap:10px;box-shadow:var(--shadow)}
.team-card .x{position:absolute;top:8px;inset-inline-start:8px}
.avatar{--s:62px;position:relative;display:grid;place-items:center;width:calc(var(--s) * 1.45);height:calc(var(--s) * 1.45);border-radius:50%;border:0;cursor:pointer;flex:none;
  background:radial-gradient(circle at 35% 30%,color-mix(in srgb,var(--c) 60%,#fff),var(--c) 60%,color-mix(in srgb,var(--c) 82%,#2a1260));box-shadow:0 5px 0 color-mix(in srgb,var(--c) 68%,#2a1260),inset 0 -6px 12px rgba(0,0,0,.15)}
.avatar .em{--s:inherit;width:var(--s);height:var(--s);filter:drop-shadow(0 4px 4px rgba(0,0,0,.25))}
.avatar.sm{--s:30px}
.avatar.md{--s:40px}
.avatar-hint{font-size:var(--fs-xs);color:var(--fg-3)}
.team-card .inp{text-align:center;font-family:var(--f-display);font-weight:700;font-size:1.15rem}
.add-card{border:2px dashed var(--line-2);background:transparent;box-shadow:none;justify-content:center;min-height:200px;color:var(--fg-2);cursor:pointer;font:700 1rem var(--f-display)}
.add-card .ic{width:34px;height:34px}
.tabs{display:flex;gap:8px;overflow-x:auto;padding-bottom:6px;scrollbar-width:thin;-webkit-overflow-scrolling:touch}
.tab{display:inline-flex;align-items:center;gap:8px;white-space:nowrap;padding:.55em 1em;border-radius:99px;border:1.5px solid var(--line-2);background:var(--surface);color:var(--fg);font:700 var(--fs-sm)/1.2 var(--f-display);cursor:pointer;flex:none}
.tab .em{--s:1.5em}
.tab[aria-selected="true"]{background:var(--c);color:var(--on-c);border-color:transparent;box-shadow:0 3px 0 color-mix(in srgb,var(--c) 68%,#2a1260)}
.tab .cnt{min-width:20px;height:20px;border-radius:10px;background:rgba(0,0,0,.2);display:inline-grid;place-items:center;font-size:.72rem;padding:0 5px}
.tile-grid{display:grid;gap:12px;grid-template-columns:repeat(auto-fill,minmax(min(46%,148px),1fr))}
.tile{position:relative;display:flex;flex-direction:column;align-items:center;justify-content:flex-start;gap:6px;text-align:center;padding:16px 10px 12px;border-radius:20px;cursor:pointer;min-width:0;color:var(--fg);
  background:linear-gradient(180deg,color-mix(in srgb,var(--c) 16%,var(--surface)),var(--surface));border:2px solid color-mix(in srgb,var(--c) 22%,transparent);transition:transform .15s cubic-bezier(.2,1.3,.4,1),border-color .15s,box-shadow .15s}
.tile:hover{transform:translateY(-3px)}
.tile .em,.tile .fl{--s:64px;transition:transform .25s cubic-bezier(.2,1.5,.4,1)}
.tile .fl{--s:70px;margin-block:6px}
.tile:hover .em{transform:scale(1.08) rotate(-4deg)}
.tile b{font-family:var(--f-display);font-weight:800;font-size:1.02rem;line-height:1.25;overflow-wrap:anywhere}
.tile small{font-size:.74rem;color:var(--fg-3);display:inline-flex;align-items:center;gap:4px}
