.tile .media-badge .ic{width:16px;height:16px}
.tile .check{position:absolute;top:8px;inset-inline-start:8px;width:28px;height:28px;border-radius:50%;display:grid;place-items:center;background:var(--surface-3);color:transparent;transition:.15s}
.tile[aria-pressed="true"]{border-color:var(--c);box-shadow:0 0 0 3px color-mix(in srgb,var(--c) 30%,transparent),0 10px 24px -12px var(--c)}
.tile[aria-pressed="true"] .check{background:var(--c);color:var(--on-c);animation:popin .35s cubic-bezier(.2,1.5,.4,1)}
.tile[aria-pressed="true"] .check .ic{width:16px;height:16px}
.tile.action{border-style:dashed;background:transparent}
.tray{display:flex;gap:8px;align-items:center;min-width:0;overflow-x:auto;scrollbar-width:none}
.tray .slot{flex:none;width:52px;height:52px;border-radius:14px;display:grid;place-items:center;border:2px dashed var(--line-2);position:relative;background:transparent;color:var(--fg)}
.tray .slot.full{border:0;background:color-mix(in srgb,var(--c) 30%,var(--surface-2));cursor:pointer}
.tray .slot .em,.tray .slot .fl{--s:36px}
.tray .slot .fl{--s:38px}
.tray .slot .x{position:absolute;top:-6px;inset-inline-start:-6px;width:20px;height:20px;border-radius:50%;background:var(--bad);color:var(--on-bad);display:grid;place-items:center}
.tray .slot .x .ic{width:12px;height:12px}
.opts{display:grid;gap:12px;grid-template-columns:repeat(auto-fit,minmax(min(100%,220px),1fr))}
.opt{display:flex;gap:12px;align-items:center;text-align:start;padding:16px;border-radius:20px;border:2px solid var(--line);background:var(--surface);color:var(--fg);cursor:pointer;min-width:0;transition:transform .15s}
