.ll-grid{display:grid;gap:8px;grid-template-columns:repeat(auto-fill,minmax(min(100%,190px),1fr))}
.ll{display:flex;gap:10px;align-items:center;text-align:start;padding:10px 12px;border-radius:16px;border:1.5px solid var(--line-2);background:var(--surface-2);color:var(--fg);cursor:pointer;min-width:0}
