.ll[aria-pressed="true"] .ic,.ll[aria-pressed="true"] span{color:inherit;opacity:.9}
.ll:disabled{opacity:.38;cursor:not-allowed}
.ai-status{font-size:var(--fs-sm);color:var(--fg-2);min-height:1.4em;display:flex;gap:8px;align-items:center}
html:not([data-ai="on"]) .ai-only{display:none!important}
html:not([data-cloud="on"]) .cloud-only{display:none!important}
.cta-bar{position:sticky;bottom:0;z-index:15;padding-block:16px calc(12px + env(safe-area-inset-bottom,0px));margin-top:-8px;background:linear-gradient(to bottom,transparent,var(--bg) 38%)}
