.tchip{position:relative;background:var(--surface);border:1.5px solid var(--line);border-radius:20px;padding:10px 12px;display:flex;align-items:center;gap:10px;text-align:start;color:var(--fg);cursor:pointer;min-width:0;box-shadow:var(--shadow);transition:transform .2s,border-color .2s}
