.turn-tag{position:absolute;top:-11px;inset-inline-end:12px;background:var(--c);color:var(--on-c);font:700 .7rem/1 var(--f-display);padding:.35em .7em;border-radius:99px;animation:bob 1.6s ease-in-out infinite}
