@media (min-width:640px){.board{grid-template-columns:repeat(var(--nt),minmax(0,1fr))}}
@media (min-width:1000px){.board{grid-template-columns:repeat(var(--n),minmax(0,1fr))}}
.bcat{position:relative;background:linear-gradient(180deg,color-mix(in srgb,var(--c) 22%,var(--surface)),var(--surface) 46%);border:1.5px solid color-mix(in srgb,var(--c) 30%,transparent);border-radius:22px;display:flex;flex-direction:column;min-width:0;box-shadow:var(--shadow)}
.bcat-h{display:flex;flex-direction:column;align-items:center;gap:4px;padding:12px 8px 6px;text-align:center;min-height:6.6em}
.bcat-h .em,.bcat-h .fl{--s:46px}
.bcat-h .fl{--s:48px;margin-block:4px}
.bcat-h b{font-family:var(--f-display);font-weight:800;font-size:.98rem;line-height:1.2}
.bcells{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;padding:8px 10px 12px}
.cell{aspect-ratio:1.55;max-width:100%;border-radius:14px;border:0;color:var(--on-c);font:800 clamp(1.05rem,2vw,1.5rem)/1 var(--f-display);display:grid;place-items:center;cursor:pointer;padding:0;font-variant-numeric:tabular-nums;
  background:linear-gradient(180deg,color-mix(in srgb,var(--c) 75%,#fff 25%),var(--c));box-shadow:0 4px 0 color-mix(in srgb,var(--c) 66%,#2a1260),inset 0 1px 0 rgba(255,255,255,.35);transition:transform .1s}
button.cell:hover{transform:translateY(-2px) scale(1.03)}
button.cell:active{transform:translateY(3px);box-shadow:0 1px 0 color-mix(in srgb,var(--c) 66%,#2a1260)}
.cell.won{background:var(--tc);color:var(--on-tc);box-shadow:inset 0 0 0 3px rgba(255,255,255,.35);cursor:default;position:relative}
.cell.miss{background:transparent;border:2px dashed var(--line-2);color:var(--fg-3);text-decoration:line-through;box-shadow:none;cursor:default}
.cell.fresh{animation:flipin .6s cubic-bezier(.2,1.2,.4,1)}
@keyframes flipin{from{transform:rotateY(90deg) scale(.8)}to{transform:none}}
.cell.none{visibility:hidden}
.board-foot{display:flex;align-items:center;gap:10px;flex-wrap:wrap;justify-content:space-between}

.qwrap{max-width:1000px;width:100%;margin:0 auto;display:flex;flex-direction:column;gap:16px}
.q-head{display:flex;flex-wrap:wrap;align-items:center;gap:8px}
.q-head .grow{display:flex;gap:8px;flex-wrap:wrap;align-items:center}
.qcard{position:relative;background:var(--surface);border:1px solid var(--line);border-radius:var(--r-xl);box-shadow:var(--shadow);padding:clamp(18px,3.6vw,34px);display:flex;flex-direction:column;gap:18px;min-width:0}
.qcard::before{content:"";position:absolute;inset:0 18% auto;height:5px;border-radius:0 0 8px 8px;background:var(--c)}
.qcard-top{display:flex;align-items:center;gap:10px;justify-content:space-between;flex-wrap:wrap}
.q-text{font-family:var(--f-display);font-weight:700;font-size:var(--fs-q);line-height:1.45;text-align:center;text-wrap:balance;overflow-wrap:anywhere}
.qcard.small .q-text{font-size:clamp(1.1rem,2.3vw,1.5rem)}
.q-notes{display:flex;flex-wrap:wrap;gap:8px;justify-content:center}
.steal-line{text-align:center;color:var(--fg-2);font-size:var(--fs-sm)}
.q-actions{display:flex;flex-wrap:wrap;gap:10px;justify-content:center;align-items:center}

/* media questions: stacked on phones, side by side on a TV */
.mq{display:flex;flex-direction:column;gap:16px;align-items:center;min-width:0}
.mq-side{display:contents}
.mq-side > *{align-self:stretch}
.mq-side > .qcard-top{order:-1}
