/* media stage */
.mstage{position:relative;align-self:center;width:min(100%,440px);aspect-ratio:1.25;border-radius:26px;display:grid;place-items:center;overflow:hidden;
  background:radial-gradient(circle at 50% 40%,color-mix(in srgb,var(--c) 22%,#fff),color-mix(in srgb,var(--c) 8%,var(--surface-2)) 70%);box-shadow:inset 0 0 0 1px var(--line)}
.mstage.compact{width:min(100%,240px)}
/* clips that stay on YouTube: a 16:9 stage, a play button, and one dock that YouTube's player lives in */
.yt-wrap{display:grid;gap:10px;justify-items:center;width:100%;min-width:0}
.mstage.yt{aspect-ratio:16/9;min-height:200px;background:radial-gradient(120% 120% at 50% 0%,#2a2340,#0b0912 70%);box-shadow:inset 0 0 0 1px rgba(255,255,255,.08)}
.qs-media .yt-wrap .mstage.yt{width:100%;height:auto;max-width:min(100%,calc(var(--u)*96))}
