.yt-slot{position:absolute;inset:0;display:grid;place-items:center}
.yt-go{display:grid;justify-items:center;gap:6px;padding:18px 28px;border:0;border-radius:22px;background:rgba(255,255,255,.07);color:#fff;font:800 1.15rem/1.3 var(--f-head,inherit);text-decoration:none;cursor:pointer;transition:transform .15s ease,background .15s ease}
.yt-go .ic{width:76px;height:76px;color:#ff4e45;filter:drop-shadow(0 6px 18px rgba(255,78,69,.45))}
