.yt-go:focus-visible{outline:3px solid #fff;outline-offset:3px}
.yt-wait{display:grid;justify-items:center;gap:10px;padding:16px;color:#fff;text-align:center}
.yt-wait small{font:700 1rem/1.4 var(--f-body);opacity:.85}
.mstage.yt .yt-wait .em.big{--s:clamp(64px,8vw,128px);filter:drop-shadow(0 14px 22px rgba(0,0,0,.45))}
.yt-row{display:flex;gap:8px;flex-wrap:wrap;justify-content:center}
#yt-dock{position:fixed;z-index:40;left:0;top:0;width:0;height:0;background:#000;border-radius:16px;overflow:hidden;box-shadow:0 14px 44px rgba(0,0,0,.5)}
#yt-dock iframe{display:block;width:100%;height:100%;border:0}
@media (prefers-reduced-motion:reduce){.yt-go{transition:none}.yt-go:hover{transform:none}}

.mstage.compact .player{gap:8px;padding:8px}
.mstage.compact .player > .em{--s:40px!important}
.mstage.compact .play-btn{width:74px;height:74px}
.mstage.compact .play-btn .ic{width:32px;height:32px}
.mstage.compact .eq{height:26px}
.mstage.compact .eq i{width:7px}
.mstage.light{background:radial-gradient(circle at 50% 45%,#fff,#efeaff 68%);box-shadow:inset 0 0 0 1px var(--line)}
.mstage .em.big{--s:min(62%,250px);filter:drop-shadow(0 18px 18px rgba(0,0,0,.28))}
.mstage .fl.big{--s:min(78%,320px);box-shadow:0 0 0 1px var(--line-2),0 22px 36px -16px rgba(0,0,0,.6)}
.fx-sil{filter:brightness(0) drop-shadow(0 0 0 #000)!important;opacity:.9}
.fx-zoom{animation:zoomout 18s cubic-bezier(.3,.05,.3,1) forwards;animation-delay:var(--ad,0s)}
@keyframes zoomout{from{transform:scale(var(--z,6)) translate(var(--zx,0),var(--zy,0))}to{transform:none}}
.fx-blur{animation:unblur 18s linear forwards;animation-delay:var(--ad,0s)}
@keyframes unblur{from{filter:blur(26px) saturate(.6)}to{filter:blur(0) saturate(1)}}
.done .fx-zoom,.done .fx-blur{animation:none;transform:none;filter:none}
.up-media.fx-old{filter:grayscale(1) contrast(1.25) brightness(.92) blur(5px)}
.rebus{display:flex;flex-wrap:wrap;gap:clamp(6px,2vw,16px);justify-content:center;align-items:center;padding:16px}
.rebus .em{--s:clamp(58px,14vw,110px);animation:popin .55s cubic-bezier(.2,1.5,.4,1) both;animation-delay:var(--ad,0s);filter:drop-shadow(0 10px 10px rgba(0,0,0,.25))}
.rebus .plus{font:800 1.6rem var(--f-display);color:var(--fg-3);animation:popin .4s both;animation-delay:var(--ad,0s)}
.player{display:flex;flex-direction:column;align-items:center;gap:16px;padding:12px}
.play-btn{width:118px;height:118px;border-radius:50%;border:0;cursor:pointer;display:grid;place-items:center;color:var(--on-c);
  background:radial-gradient(circle at 35% 30%,color-mix(in srgb,var(--c) 60%,#fff),var(--c) 60%,color-mix(in srgb,var(--c) 82%,#2a1260));box-shadow:0 6px 0 color-mix(in srgb,var(--c) 68%,#2a1260),0 20px 40px -14px var(--c)}
.play-btn .ic{width:48px;height:48px;stroke-width:2.4}
.play-btn:active{transform:translateY(3px)}
.eq{display:flex;gap:6px;align-items:flex-end;height:46px}
.eq i{width:9px;height:12px;border-radius:5px;background:var(--c);opacity:.5}
.playing .eq i{animation:eq .8s ease-in-out infinite alternate;opacity:1}
.eq i:nth-child(2){animation-delay:.15s}.eq i:nth-child(3){animation-delay:.3s}.eq i:nth-child(4){animation-delay:.08s}.eq i:nth-child(5){animation-delay:.22s}.eq i:nth-child(6){animation-delay:.36s}.eq i:nth-child(7){animation-delay:.11s}
@keyframes eq{from{height:10px}to{height:46px}}
.up-media{max-width:100%;max-height:min(56vh,420px);border-radius:20px;display:block;margin:0 auto;box-shadow:var(--shadow);background:#000}
.media-missing{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;width:100%;height:100%;min-height:180px;color:var(--fg-2);font-size:var(--fs-sm)}
