.acard{background:linear-gradient(180deg,color-mix(in srgb,var(--good) 85%,#fff),var(--good));color:var(--on-good);border-radius:24px;padding:16px 20px;text-align:center;display:flex;flex-direction:column;gap:2px;align-items:center;box-shadow:0 5px 0 color-mix(in srgb,var(--good) 68%,#0b3b25);animation:popin .45s cubic-bezier(.2,1.4,.4,1)}
