.award-title{text-align:center;font-family:var(--f-display);font-weight:800;font-size:var(--fs-xl)}
.tokens{display:flex;flex-wrap:wrap;gap:14px;justify-content:center}
.token{display:flex;flex-direction:column;align-items:center;gap:6px;background:none;border:0;cursor:pointer;color:var(--fg);width:126px;padding:6px;border-radius:20px;transition:transform .15s}
.token:hover{transform:translateY(-3px)}
.token:active{transform:scale(.96)}
.token .avatar{--s:48px}
.token b{font-family:var(--f-display);font-weight:800;font-size:1rem;line-height:1.2;text-align:center;overflow-wrap:anywhere}
.token small{font-size:.75rem;font-weight:700;padding:.2em .6em;border-radius:99px;background:var(--surface-2);color:var(--fg-2)}
.token.turn small{background:var(--c);color:var(--on-c)}
.token .gain{position:absolute;top:-6px;inset-inline-start:-8px;background:var(--saffron);color:var(--on-saffron);font:800 .78rem/1 var(--f-display);padding:.3em .5em;border-radius:99px}
.token .avatar{position:relative}
.nobody{display:block;margin:4px auto 0}
.pre{display:flex;flex-direction:column;gap:14px;align-items:stretch}
