.judge-out{font-weight:600}
.judge-out.correct{color:var(--good)} .judge-out.close{color:var(--saffron)} .judge-out.wrong{color:var(--bad)}

/* timer */
.tm{--p:1;position:relative;width:64px;height:64px;flex:none}
.tm svg{width:100%;height:100%;transform:rotate(-90deg)}
