/* end + ranks */
.win{--c:var(--saffron);--on-c:var(--on-saffron);position:relative;border-radius:var(--r-xl);padding:30px 20px 24px;text-align:center;display:flex;flex-direction:column;align-items:center;gap:6px;color:var(--on-c);overflow:hidden;isolation:isolate;
  background:radial-gradient(120% 90% at 50% 0%,color-mix(in srgb,var(--c) 65%,#fff),var(--c) 55%,color-mix(in srgb,var(--c) 82%,#2a1260));box-shadow:0 6px 0 color-mix(in srgb,var(--c) 68%,#2a1260),var(--shadow)}
