.handoff-name{font-size:var(--fs-hero);color:var(--c,var(--fg));overflow-wrap:anywhere}
.secret{width:min(430px,100%);border-radius:var(--r-xl);color:var(--on-c);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px;text-align:center;padding:30px 22px;min-height:320px;position:relative;overflow:hidden;margin:0 auto;
  background:radial-gradient(120% 90% at 50% 0%,color-mix(in srgb,var(--c) 62%,#fff),var(--c) 55%,color-mix(in srgb,var(--c) 82%,#2a1260));box-shadow:0 6px 0 color-mix(in srgb,var(--c) 68%,#2a1260),var(--shadow);animation:popin .45s cubic-bezier(.2,1.4,.4,1)}
.secret .em{--s:130px;filter:drop-shadow(0 12px 14px rgba(0,0,0,.28))}
.secret .fl{--s:200px}
.secret .s-label{font-weight:700;opacity:.85}
.secret .s-word{font:800 clamp(2.1rem,8vw,3.4rem)/1.2 var(--f-display);overflow-wrap:anywhere}
