.center-col{display:flex;flex-direction:column;align-items:center;gap:16px;text-align:center}
.center-col > .em.big{--s:110px}
.pick-grid{display:grid;gap:10px;grid-template-columns:repeat(auto-fill,minmax(min(100%,160px),1fr));width:100%}
.pick{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;min-height:62px;padding:10px 12px;border-radius:18px;border:0;background:var(--surface-2);color:var(--fg);font:700 1rem/1.25 var(--f-display);cursor:pointer;
  box-shadow:0 4px 0 var(--ink),inset 0 0 0 1.5px var(--line);background:var(--surface);text-align:center;overflow-wrap:anywhere;transition:transform .1s}
