.pick .em{--s:46px}
.pick .fl{--s:56px}
.pick[aria-pressed="true"]{background:var(--c,var(--saffron));color:var(--on-c,var(--on-saffron))}
.pick:disabled{opacity:.35;cursor:not-allowed;box-shadow:none}
.big-title{font-size:var(--fs-2xl);text-align:center}
.lead{font-size:var(--fs-lg);color:var(--fg-2);text-align:center;max-width:36em}
.order-list{display:flex;flex-wrap:wrap;gap:8px;justify-content:center;counter-reset:o}
