.letter{display:grid;place-items:center;width:clamp(150px,40vw,230px);aspect-ratio:1;border-radius:34px;font:800 clamp(5.5rem,22vw,9rem)/1 var(--f-display);color:var(--on-c);
  background:radial-gradient(circle at 35% 25%,color-mix(in srgb,var(--c) 55%,#fff),var(--c) 60%,color-mix(in srgb,var(--c) 82%,#2a1260));box-shadow:0 8px 0 color-mix(in srgb,var(--c) 66%,#2a1260),0 30px 50px -20px var(--c);transform:rotate(-4deg)}
