.role-item.dead{opacity:.45}
.role-item .grow{font-weight:700;font-family:var(--f-display);text-align:start}

/* letter badges for teams and players */
.avatar .av-l{display:block;font:800 calc(var(--s) * .92)/1 var(--f-display);color:var(--on-c);text-shadow:0 2px 0 rgba(0,0,0,.12);transform:translateY(.02em);pointer-events:none}
