  background:linear-gradient(180deg,color-mix(in srgb,var(--c) 15%,var(--surface)),var(--surface) 62%);border:2px solid color-mix(in srgb,var(--c) 45%,transparent);
  box-shadow:0 0 0 6px color-mix(in srgb,var(--c) 10%,transparent),var(--shadow);animation:turnin .45s cubic-bezier(.2,1.2,.4,1)}
