.pad-x{width:42px;height:42px;border:0;border-radius:14px;display:grid;place-items:center;background:var(--surface);color:var(--fg);cursor:pointer;box-shadow:0 3px 0 var(--line-2)}
.pad-x .ic{width:20px;height:20px}
.pad-main{flex:1;display:flex;flex-direction:column;gap:16px;padding:8px 16px max(20px,env(safe-area-inset-bottom))}
.pad-msg{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;text-align:center;padding:12px 4px}
.pad-msg .em{--s:96px}
.pad-msg > .ic.big{width:84px;height:84px;color:var(--c)}
.pad-msg h1{margin:0;font:800 1.75rem/1.2 var(--f-display)}
.pad-msg p{margin:0;font:500 1rem/1.6 var(--f-body);color:var(--fg-2);max-width:26em}
.pad-hosts{width:100%;display:flex;flex-direction:column;gap:10px}
.pad-host{display:flex;align-items:center;gap:12px;width:100%;padding:16px 18px;border:0;border-radius:20px;background:var(--grape);color:#fff;font:inherit;cursor:pointer;box-shadow:0 5px 0 color-mix(in srgb,var(--grape) 55%,#1a0b46)}
.pad-host span{font:800 1.9rem/1 var(--f-display);letter-spacing:.14em}
.pad-host small{margin-inline-end:auto;font:600 .95rem/1 var(--f-body);opacity:.9}
.pad-host .ic{width:22px;height:22px}
.pad-codein{width:100%;display:flex;gap:8px}
.pad-codein .inp{flex:1;text-align:center;font:800 1.5rem/1 var(--f-display);letter-spacing:.2em;text-transform:uppercase}
.pad-join{display:flex;flex-direction:column;gap:14px;padding-top:10px}
.pad-join h1,.pad-join h2{margin:0;font:800 1.5rem/1.2 var(--f-display)}
.pad-join h2{font-size:1.2rem;margin-top:6px}
.pad-join .inp.xl{font:700 1.3rem/1.2 var(--f-body);padding:16px 18px}
.pad-teams{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}
.pad-team{display:flex;flex-direction:column;align-items:center;gap:8px;padding:18px 10px;border:0;border-radius:22px;background:var(--c);color:var(--on-c);font:inherit;cursor:pointer;box-shadow:0 5px 0 color-mix(in srgb,var(--c) 55%,#1a0b46)}
.pad-team[aria-pressed="true"]{outline:4px solid var(--fg);outline-offset:3px}
.pad-team b{font:800 1.2rem/1.2 var(--f-display)}
.pad-team-av{width:52px;height:52px;border-radius:50%;display:grid;place-items:center;background:rgba(255,255,255,.95);color:color-mix(in srgb,var(--c) 75%,#1a0b46);font:800 1.5rem/1 var(--f-display)}
.pad-me{display:flex;align-items:center;gap:12px;padding:12px 14px;border-radius:22px;background:var(--c);color:var(--on-c);box-shadow:0 5px 0 color-mix(in srgb,var(--c) 55%,#1a0b46)}
.pad-me small{display:block;font:600 .85rem/1.2 var(--f-body);opacity:.9}
.pad-me b{font:800 1.3rem/1.2 var(--f-display)}
.pad-score{font:800 1.9rem/1 var(--f-display)}
.pad-me .pad-x{background:rgba(255,255,255,.9);color:#1a0b46;box-shadow:none}
.pad-pick h1{margin:4px 0 12px;font:800 1.6rem/1.2 var(--f-display);text-align:center}
.pad-cat{display:flex;align-items:center;gap:10px;padding:10px;border-radius:18px;background:var(--surface);margin-bottom:10px;box-shadow:0 3px 0 var(--line-2)}
.pad-cat > b{flex:1;min-width:0;font:800 1.02rem/1.3 var(--f-display)}
.pad-vals{display:flex;gap:8px}
.pad-val{min-width:64px;height:54px;border:0;border-radius:14px;background:var(--c);color:var(--on-c);font:800 1.25rem/1 var(--f-display);cursor:pointer;box-shadow:0 4px 0 color-mix(in srgb,var(--c) 55%,#1a0b46)}
.pad-val:active{transform:translateY(3px);box-shadow:none}
.pad-q{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;text-align:center}
.pad-q small{font:700 .95rem/1.3 var(--f-body);color:var(--fg-2)}
.pad-q p{margin:0;font:800 1.35rem/1.5 var(--f-display)}
.pad-q > b{font:800 1.3rem/1.3 var(--f-display);color:var(--c)}
.pad-opts{display:flex;flex-wrap:wrap;justify-content:center;gap:8px}
.pad-opts span{padding:8px 14px;border-radius:14px;background:var(--surface);font:700 1rem/1.3 var(--f-body);box-shadow:inset 0 0 0 2px var(--line-2)}
.pad-buzz{width:min(78vw,300px);aspect-ratio:1;border:0;border-radius:50%;background:radial-gradient(circle at 35% 30%,color-mix(in srgb,var(--pome) 60%,#fff),var(--pome) 60%,color-mix(in srgb,var(--pome) 70%,#2a0410));color:#fff;font:800 2rem/1.2 var(--f-display);cursor:pointer;box-shadow:0 12px 0 color-mix(in srgb,var(--pome) 50%,#2a0410),0 22px 40px -10px rgba(0,0,0,.4)}
.pad-buzz:active{transform:translateY(10px);box-shadow:0 2px 0 color-mix(in srgb,var(--pome) 50%,#2a0410)}
.pad-buzz[disabled]{filter:grayscale(.6);opacity:.6}
.pad-buzzed{margin:0;padding:8px 16px;border-radius:999px;background:var(--c);color:var(--on-c)!important;font:800 1.1rem/1.2 var(--f-display)!important}
.pad-secret{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:16px;text-align:center;padding:20px 14px;border-radius:28px;background:var(--surface);box-shadow:inset 0 0 0 4px var(--c)}
.pad-secret small{font:700 1rem/1.3 var(--f-body);color:var(--fg-2)}
.pad-secret > b{font:800 clamp(2.2rem,11vw,3.4rem)/1.15 var(--f-display);color:var(--fg)}
.pad-answer{font:800 1.6rem/1.3 var(--f-display)!important;color:var(--fg)!important}
.hud-btn.hud-room{display:flex;flex-direction:row;align-items:center;width:auto;gap:.45em;padding-inline:calc(var(--u)*1.2)}
.hud-btn.hud-room .ic{width:calc(var(--u)*2.2);height:calc(var(--u)*2.2);min-width:18px;min-height:18px}
.room-strip{display:flex;align-items:center;gap:calc(var(--u)*1.4);margin:calc(var(--u)*.4) 0 calc(var(--u)*1.6);padding:calc(var(--u)*1.2) calc(var(--u)*1.6);border-radius:calc(var(--u)*2.2);background:linear-gradient(110deg,color-mix(in srgb,var(--grape) 14%,var(--surface)),var(--surface) 70%);box-shadow:inset 0 0 0 calc(var(--u)*.2) color-mix(in srgb,var(--grape) 30%,var(--line-2)),0 calc(var(--u)*.4) 0 var(--line-2)}
.room-strip.on{background:linear-gradient(110deg,color-mix(in srgb,var(--mint) 18%,var(--surface)),var(--surface) 70%);box-shadow:inset 0 0 0 calc(var(--u)*.2) color-mix(in srgb,var(--mint) 45%,var(--line-2)),0 calc(var(--u)*.4) 0 var(--line-2)}
.room-strip.on .room-ic{background:var(--mint);color:var(--on-mint,#062b1d)}
.room-strip b{display:block;font:800 calc(var(--u)*1.9)/1.2 var(--f-display)}
.room-strip span{font:500 max(13px,calc(var(--u)*1.3))/1.45 var(--f-body);color:var(--fg-2)}
.room-strip i{font-style:normal;font-weight:800;color:var(--fg)}
.room-strip .room-ic{width:calc(var(--u)*5);height:calc(var(--u)*5)}
.room-strip .btn{flex:none}
@media (max-width:600px){.room-strip{flex-wrap:wrap}.room-strip .btn{width:100%}}
html[data-room="off"] .room-strip{display:none}
.room-modal{--u:clamp(7px,1vw,12px)}
.room-modal .room-card{background:none;box-shadow:none;padding:0;gap:calc(var(--u)*2.4)}
.room-modal .room-qr{width:calc(var(--u)*30)}
.room-modal .room-code{font-size:calc(var(--u)*6.4)!important}
.room-modal .room-steps{font-size:calc(var(--u)*1.6)}

/* ---------- v8: every party game on its own stage ---------- */
.pstage{--u:clamp(7px,0.95vw,10.5px);position:relative;isolation:isolate;min-height:100vh;min-height:100dvh;padding:clamp(12px,2.2vw,30px) 0 clamp(28px,4vw,56px);color:var(--fg);
  background:radial-gradient(90% 60% at 50% -14%,color-mix(in srgb,var(--c) 32%,transparent),transparent 72%),
    radial-gradient(50% 45% at -6% 104%,color-mix(in srgb,var(--sky) 18%,transparent),transparent 72%),
    radial-gradient(50% 45% at 106% 104%,color-mix(in srgb,var(--rose) 16%,transparent),transparent 72%),var(--stage-bg)}
.pstage .wrap{max-width:min(1160px,100%)}
.pstage .wrap.narrow{max-width:min(980px,100%)}
.pstage .setup-head,.pstage .play-top{position:sticky;top:10px;z-index:4;padding:10px 12px 10px 14px;border-radius:24px;background:color-mix(in srgb,var(--surface) 84%,transparent);-webkit-backdrop-filter:blur(14px);backdrop-filter:blur(14px);box-shadow:0 14px 34px -22px rgba(30,10,70,.45),inset 0 0 0 1px var(--line);margin-bottom:clamp(14px,2vw,24px)}
.pstage .setup-head h1,.pstage .play-top h1{font:800 clamp(1.25rem,2.3vw,1.85rem)/1.1 var(--f-display)}
.pstage .setup-head .em,.pstage .play-top h1 .em{--s:clamp(38px,4vw,54px)}
.pstage .play-top .chip{font-weight:800}
.pstage .center-col{gap:clamp(14px,2vw,22px);padding:clamp(20px,3.2vw,44px) clamp(16px,3vw,40px);border-radius:clamp(26px,3vw,38px);background:color-mix(in srgb,var(--surface) 90%,transparent);box-shadow:0 34px 70px -40px rgba(30,10,70,.5),inset 0 0 0 1px var(--line);animation:qcin .45s cubic-bezier(.2,1.2,.4,1) both}
.pstage .big-title{font-size:clamp(1.8rem,3.6vw,2.9rem);line-height:1.15}
.pstage .lead{font-size:clamp(1.05rem,1.6vw,1.35rem)}
.pstage .handoff{min-height:min(70vh,640px);padding:clamp(20px,3vw,40px);border-radius:clamp(26px,3vw,38px);background:color-mix(in srgb,var(--surface) 90%,transparent);box-shadow:0 34px 70px -40px rgba(30,10,70,.5),inset 0 0 0 1px var(--line)}
.pstage .handoff-name{font-size:clamp(2.4rem,6vw,4.4rem)}
.pstage .secret{width:min(520px,100%);min-height:clamp(320px,46vh,460px)}
.pstage .secret .s-word{font-size:clamp(2.2rem,5vw,3.6rem)}
.pstage .word-card{width:min(100%,560px);padding:clamp(20px,3vw,34px)}
.pstage .word-big{font-size:clamp(2.2rem,6vw,4.2rem)}
.pstage .btn.xl{min-height:clamp(56px,6vw,72px);font-size:clamp(1.1rem,1.6vw,1.35rem);padding-inline:clamp(22px,2.6vw,34px)}
.pstage .rank{width:min(100%,640px)}
@media (prefers-reduced-motion:reduce){.pstage .center-col{animation:none}}
/* the phone flow for the party games, on the TV */
.ph-seen{display:flex;flex-wrap:wrap;justify-content:center;gap:10px;max-width:760px}
.ph-p{display:inline-flex;align-items:center;gap:8px;padding:6px 12px 6px 8px;border-radius:999px;background:var(--surface-2);box-shadow:inset 0 0 0 2px var(--line-2);font:700 1rem/1 var(--f-body);color:var(--fg-2);transition:background .3s,color .3s}
.ph-p > .ic{width:18px;height:18px}
.ph-p.ok{background:var(--good);color:var(--on-good);box-shadow:none}
.ph-p b{font-weight:800}
.ph-note{display:inline-flex;align-items:center;gap:.4em;margin:0;padding:8px 14px;border-radius:999px;background:color-mix(in srgb,var(--c) 14%,var(--surface-2));font:700 1rem/1.4 var(--f-body)}
.ph-note .ic{width:1.2em;height:1.2em}
/* and on the phones */
.pad-two{display:grid;grid-template-columns:1fr 1fr;gap:10px;width:100%}
.pad-two .btn{width:100%}
.pad-link{display:inline-flex;align-items:center;gap:.4em;font:700 .95rem/1 var(--f-body);color:var(--fg-2);text-decoration:underline}
.pad-link .ic{width:1.1em;height:1.1em}
.pad-secret .em{--s:88px}
/* screen changes cross-fade */
::view-transition-old(root),::view-transition-new(root){animation-duration:.26s;animation-timing-function:cubic-bezier(.2,.8,.2,1)}

/* ---------- the phone mirrors the game: scores, the whole board, the question, the answer ---------- */
.pad-me{padding:10px 12px}
.pad-scores{display:grid;grid-template-columns:repeat(var(--n),minmax(0,1fr));gap:8px}
.pad-sc{position:relative;display:flex;align-items:center;gap:8px;min-width:0;padding:8px 10px;border-radius:16px;background:var(--surface);box-shadow:inset 0 0 0 2px color-mix(in srgb,var(--c) 30%,var(--line-2))}
.pad-sc i{flex:none;width:28px;height:28px;border-radius:50%;display:grid;place-items:center;background:var(--c);color:var(--on-c);font:800 .95rem/1 var(--f-display);font-style:normal}
.pad-sc b{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font:700 .9rem/1.2 var(--f-body)}
.pad-sc em{font:800 1.2rem/1 var(--f-display);font-style:normal;font-variant-numeric:tabular-nums}
.pad-sc.me{box-shadow:inset 0 0 0 3px var(--c)}
.pad-sc.turn{background:color-mix(in srgb,var(--c) 18%,var(--surface))}
.pad-sc.turn::after{content:"دورهم";position:absolute;inset-block-start:-9px;inset-inline-end:10px;padding:2px 8px;border-radius:999px;background:var(--c);color:var(--on-c);font:800 .68rem/1.3 var(--f-body)}
.pad-turn{display:flex;align-items:center;gap:12px;padding:12px 14px;border-radius:20px;background:color-mix(in srgb,var(--c) 16%,var(--surface));box-shadow:inset 0 0 0 2px color-mix(in srgb,var(--c) 45%,transparent)}
.pad-turn.me{background:var(--c);color:var(--on-c);box-shadow:0 5px 0 color-mix(in srgb,var(--c) 55%,#1a0b46);animation:padpulse 1.6s ease-in-out infinite}
.pad-turn .em{--s:40px}
.pad-turn .pad-team-av{width:40px;height:40px;font-size:1.1rem;background:var(--c);color:var(--on-c)}
.pad-turn b{display:block;font:800 1.2rem/1.25 var(--f-display)}
.pad-turn span:not(.pad-team-av){display:block;font:500 .88rem/1.4 var(--f-body);opacity:.85}
@keyframes padpulse{0%,100%{transform:none}50%{transform:scale(1.015)}}
.pad-res{display:flex;flex-wrap:wrap;align-items:center;gap:4px 8px;margin:0;padding:8px 12px;border-radius:14px;font:600 .88rem/1.4 var(--f-body);background:var(--surface)}
.pad-res .ic{width:18px;height:18px;flex:none}
.pad-res b{font-weight:800}
.pad-res.good{background:color-mix(in srgb,var(--mint) 22%,var(--surface))}
.pad-res.good .ic{color:color-mix(in srgb,var(--mint) 80%,var(--fg))}
.pad-res.bad .ic{color:color-mix(in srgb,var(--pome) 80%,var(--fg))}
.pad-board{display:flex;flex-direction:column;gap:10px}
.pad-bcat{padding:10px 10px 8px;border-radius:18px;background:var(--surface);box-shadow:0 3px 0 var(--line-2),inset 4px 0 0 var(--c)}
.pad-bcat h3{display:flex;align-items:center;gap:8px;margin:0 0 8px;font:800 1rem/1.3 var(--f-display)}
.pad-bcat h3 .em,.pad-bcat h3 .flag{--s:26px;width:26px;height:26px;flex:none}
.pad-brow{display:flex;align-items:center;gap:6px;padding:3px 0}
.pad-bav{flex:none;width:26px;height:26px;border-radius:50%;display:grid;place-items:center;background:var(--c);color:var(--on-c);font:800 .8rem/1 var(--f-display);font-style:normal}
.pad-cell{flex:1;min-width:0;height:44px;border:0;border-radius:12px;display:grid;place-items:center;font:800 1.08rem/1 var(--f-display);font-variant-numeric:tabular-nums;background:color-mix(in srgb,var(--c) 10%,var(--bg));color:color-mix(in srgb,var(--c) 70%,var(--fg));box-shadow:inset 0 0 0 2px color-mix(in srgb,var(--c) 28%,transparent)}
.pad-cell .ic{width:20px;height:20px}
.pad-cell.now{background:color-mix(in srgb,var(--c) 22%,var(--bg))}
.pad-cell.go{background:var(--c);color:var(--on-c);cursor:pointer;box-shadow:0 4px 0 color-mix(in srgb,var(--c) 55%,#1a0b46)}
.pad-cell.go:active{transform:translateY(3px);box-shadow:none}
.pad-cell.won{background:var(--c);color:var(--on-c);box-shadow:none}
.pad-cell.miss{background:var(--line);color:var(--fg-3,var(--fg-2));box-shadow:none;opacity:.7}
.pad-cell.none{opacity:.35;box-shadow:none}
.pad-brow:not(.now) .pad-cell.open{opacity:.75}
.pad-qh{display:flex;align-items:center;gap:10px;padding:10px 12px;border-radius:18px;background:var(--c);color:var(--on-c);box-shadow:0 4px 0 color-mix(in srgb,var(--c) 55%,#1a0b46)}
.pad-qcat{flex:1;min-width:0;display:flex;align-items:center;gap:8px}
.pad-qcat .em,.pad-qcat .flag{--s:30px;width:30px;height:30px;flex:none}
.pad-qcat b{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font:800 1.1rem/1.2 var(--f-display)}
.pad-qv{padding:4px 10px;border-radius:999px;background:rgba(255,255,255,.92);color:#1a0b46;font:800 1.1rem/1 var(--f-display)}
.pad-tm{min-width:44px;height:44px;border-radius:50%;display:grid;place-items:center;background:rgba(255,255,255,.92);color:#1a0b46;font:800 1.2rem/1 var(--f-display);font-variant-numeric:tabular-nums}
.pad-tm.low{background:var(--pome);color:#fff;animation:padpulse .6s ease-in-out infinite}
.pad-qwho{display:flex;flex-wrap:wrap;align-items:center;gap:6px 8px;margin:0}
.pad-qwho .pad-team-av{width:30px;height:30px;font-size:.9rem;background:var(--c);color:var(--on-c)}
.pad-qwho b{font:800 1.1rem/1.2 var(--f-display)}
.pad-note{display:inline-flex;align-items:center;gap:4px;padding:3px 9px;border-radius:999px;background:var(--surface);font:700 .78rem/1.3 var(--f-body);box-shadow:inset 0 0 0 2px var(--line-2)}
.pad-note .ic{width:14px;height:14px}
.pad-q{justify-content:flex-start;gap:12px}
.pad-media{width:100%}
.pad-media .mstage,.pad-media .mstage.compact{width:100%;max-width:none;min-height:0;height:min(40vh,280px);aspect-ratio:auto;margin:0;border-radius:22px}
.pad-media.up{display:flex;align-items:center;justify-content:center;gap:10px;padding:16px;border-radius:20px;background:var(--surface);font:700 1rem/1.4 var(--f-body);box-shadow:inset 0 0 0 2px var(--line-2)}
.pad-media.up .em{--s:40px}
.pad-q .pad-qtext{margin:0;font:800 1.4rem/1.5 var(--f-display)}
.pad-opts span.right{background:color-mix(in srgb,var(--mint) 35%,var(--surface));box-shadow:inset 0 0 0 3px color-mix(in srgb,var(--mint) 80%,var(--fg))}
.pad-opts span.dim{opacity:.45}
.pad-say{margin:0;padding:10px 16px;border-radius:999px;background:var(--surface);font:800 1.05rem/1.3 var(--f-display);color:var(--fg-2)}
.pad-say.me{background:var(--c);color:var(--on-c)}
.pad-say .em{--s:26px;vertical-align:middle}
.pad-ans{width:100%;display:flex;flex-direction:column;align-items:center;gap:4px;padding:14px 16px;border-radius:22px;background:color-mix(in srgb,var(--mint) 20%,var(--surface));box-shadow:inset 0 0 0 3px color-mix(in srgb,var(--mint) 70%,transparent)}
.pad-ans small{display:inline-flex;align-items:center;gap:6px;font:700 .9rem/1.2 var(--f-body);color:var(--fg-2)}
.pad-ans small .ic{width:16px;height:16px}
.pad-ans b{font:800 1.6rem/1.3 var(--f-display)}
.pad-ans span{font:500 .92rem/1.5 var(--f-body);color:var(--fg-2)}

/* ---------- the voice chat bar ---------- */
#voice-dock{position:fixed;z-index:60;inset-inline:auto 16px;inset-block-end:max(16px,env(safe-area-inset-bottom));font-family:var(--f-body)}
#voice-dock[hidden]{display:none}
.vd-join{display:inline-flex;align-items:center;gap:8px;padding:10px 16px;border:0;border-radius:999px;background:var(--surface);color:var(--fg);font:inherit;cursor:pointer;box-shadow:0 8px 24px -10px rgba(30,15,80,.45),inset 0 0 0 2px var(--line-2)}
.vd-join .ic{width:20px;height:20px;color:var(--grape)}
.vd-join b{font:800 .98rem/1 var(--f-display)}
.vd-n{padding:3px 8px;border-radius:999px;background:var(--mint);color:#06322a;font:800 .75rem/1.2 var(--f-body)}
.vd-bar{display:flex;align-items:center;gap:8px;padding:8px;border-radius:999px;background:color-mix(in srgb,var(--surface) 92%,transparent);backdrop-filter:blur(14px);box-shadow:0 10px 30px -12px rgba(30,15,80,.5),inset 0 0 0 2px var(--line-2);max-width:min(92vw,560px)}
.vd-mic,.vd-leave{flex:none;width:44px;height:44px;border:0;border-radius:50%;display:grid;place-items:center;cursor:pointer;color:#fff}
.vd-mic{background:var(--grape)}
.vd-mic.muted{background:var(--line-2);color:var(--fg)}
