/* ---------- the splash: the four friends fly in and gather around the star, then it lifts ---------- */
#splash{position:fixed;inset:0;z-index:9999;display:grid;place-items:center;overflow:hidden;color:#1a0b46;
  background:radial-gradient(60% 45% at 16% 10%,rgba(255,154,61,.30),transparent 70%),radial-gradient(55% 45% at 88% 18%,rgba(124,77,255,.22),transparent 70%),radial-gradient(70% 55% at 50% 104%,rgba(61,220,151,.22),transparent 70%),#fff6ea;
  transition:opacity .45s ease,visibility .45s;animation:sp-gone .4s ease 10s forwards}
#splash.out{opacity:0;visibility:hidden;pointer-events:none}
#splash .sp-in{display:flex;flex-direction:column;align-items:center;gap:8px;padding:24px;text-align:center;transition:transform .5s cubic-bezier(.2,.8,.2,1)}
#splash.out .sp-in{transform:scale(1.07)}
.sp-mark{width:clamp(112px,26vmin,168px);height:auto;overflow:visible;filter:drop-shadow(0 18px 28px rgba(124,77,255,.32))}
.sp-mark *{transform-box:fill-box;transform-origin:center}
.sp-tile{animation:sp-pop .7s cubic-bezier(.2,1.4,.4,1) both}
.sp-core{animation:sp-scale .45s cubic-bezier(.2,1.5,.4,1) .4s both}
.sp-d{animation:sp-fly .65s cubic-bezier(.2,1.25,.35,1) both}
.sp-d1{--x:-36px;--y:-36px;animation-delay:.2s}
.sp-d2{--x:36px;--y:-36px;animation-delay:.28s}
.sp-d3{--x:36px;--y:36px;animation-delay:.36s}
.sp-d4{--x:-36px;--y:36px;animation-delay:.44s}
.sp-star{animation:sp-spin .65s cubic-bezier(.2,1.4,.4,1) .62s both}
.sp-mark{animation:sp-float 2.6s ease-in-out 1.3s infinite alternate}
.sp-name{margin-top:8px;padding:0 .1em;font:800 clamp(3rem,12vmin,5.2rem)/1.05 "Baloo Bhaijaan 2","Rubik",system-ui,sans-serif;background:linear-gradient(120deg,#ff9a3d,#ff4d6d 45%,#7c4dff);-webkit-background-clip:text;background-clip:text;color:transparent;animation:sp-up .55s cubic-bezier(.2,1.2,.4,1) .55s both}
.sp-tag{font:600 clamp(1rem,3.4vmin,1.3rem)/1.4 "Rubik",system-ui,sans-serif;color:#4a3a7a;animation:sp-up .5s ease .75s both}
.sp-dots{display:flex;gap:8px;margin-top:16px;animation:sp-up .4s ease .95s both}
.sp-dots i{width:10px;height:10px;border-radius:50%;animation:sp-bounce 1s ease-in-out infinite}
.sp-dots i:nth-child(1){background:#ffd23f}
.sp-dots i:nth-child(2){background:#3ddc97;animation-delay:.12s}
.sp-dots i:nth-child(3){background:#4fc3ff;animation-delay:.24s}
.sp-dots i:nth-child(4){background:#ff8fab;animation-delay:.36s}
@keyframes sp-pop{0%{transform:scale(.3) rotate(-18deg);opacity:0}100%{transform:none;opacity:1}}
@keyframes sp-scale{0%{transform:scale(0)}100%{transform:none}}
@keyframes sp-fly{0%{transform:translate(var(--x),var(--y)) scale(.4);opacity:0}100%{transform:none;opacity:1}}
@keyframes sp-spin{0%{transform:rotate(-200deg) scale(0)}100%{transform:none}}
@keyframes sp-up{0%{transform:translateY(14px);opacity:0}100%{transform:none;opacity:1}}
@keyframes sp-float{0%{transform:translateY(0)}100%{transform:translateY(-6px)}}
@keyframes sp-bounce{0%,100%{transform:translateY(0);opacity:.55}50%{transform:translateY(-8px);opacity:1}}
@keyframes sp-gone{to{opacity:0;visibility:hidden;pointer-events:none}}
html[data-theme="dark"] #splash{color:#fff;background:radial-gradient(60% 45% at 16% 10%,rgba(255,154,61,.20),transparent 70%),radial-gradient(55% 45% at 88% 18%,rgba(124,77,255,.32),transparent 70%),radial-gradient(70% 55% at 50% 104%,rgba(61,220,151,.14),transparent 70%),#110a2e}
