.gn-num{display:inline-block;margin-bottom:6px;padding:.15em .8em;border-radius:99px;background:color-mix(in srgb,var(--c) 16%,transparent);color:color-mix(in srgb,var(--c) 70%,var(--fg));font:800 var(--fs-xs)/1.6 var(--f-display)}
.gn-ask{display:grid;grid-template-columns:auto minmax(0,1fr);gap:clamp(18px,3.4vw,40px);align-items:center;margin:clamp(8px,1.6vw,18px) 0 clamp(18px,2.6vw,30px)}
.gn-ask .gn-bubble::before{content:"";position:absolute;right:-13px;top:calc(50% - 12px);width:22px;height:22px;background:var(--surface);border:3px solid color-mix(in srgb,var(--c) 55%,transparent);border-left:0;border-bottom:0;transform:rotate(45deg)}
.gn-side{display:flex;flex-direction:column;align-items:center;gap:8px;width:clamp(120px,17vw,180px)}
.gn-meter{width:100%;height:12px;border-radius:99px;background:var(--surface-3);overflow:hidden;box-shadow:inset 0 0 0 1px var(--line)}
.gn-meter i{display:block;height:100%;border-radius:inherit;background:linear-gradient(90deg,var(--c),var(--grape));transition:width .6s cubic-bezier(.2,1,.3,1)}
.gn-mood{font-weight:700;color:var(--fg-2);font-size:var(--fs-sm);text-align:center;line-height:1.3}
.gn-answers{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:clamp(8px,1.3vw,14px)}
.gn-a{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;min-height:clamp(72px,9vw,100px);padding:8px;border:0;border-radius:22px;background:var(--surface);color:var(--fg);font:800 clamp(1.02rem,1.7vw,1.35rem)/1.2 var(--f-display);cursor:pointer;box-shadow:0 5px 0 var(--ink),var(--shadow);transition:transform .12s,box-shadow .12s}
.gn-a .ic{width:1.45em;height:1.45em}
.gn-a.strong{background:var(--c);color:var(--on-c);box-shadow:0 5px 0 color-mix(in srgb,var(--c) 55%,#000),var(--shadow)}
.gn-a:hover{transform:translateY(-2px)}
.gn-a:active{transform:translateY(4px);box-shadow:0 1px 0 var(--ink)}
.gn-tools{margin-top:clamp(14px,2vw,22px);gap:12px;align-items:center;flex-wrap:wrap}
.gn-chips{display:flex;flex-wrap:wrap;gap:8px;justify-content:center}
.gn-note{font-size:var(--fs-sm);max-width:34em}
.gn-card{display:flex;flex-direction:column;align-items:center;gap:6px;padding:clamp(18px,3vw,30px) clamp(24px,4vw,52px);border-radius:30px;background:var(--c);color:var(--on-c);box-shadow:0 8px 0 color-mix(in srgb,var(--c) 55%,#000),var(--shadow);max-width:100%}
.gn-card .em{--s:clamp(56px,7vw,84px)}
.gn-card h2{font-size:clamp(1.7rem,4.4vw,3.2rem);line-height:1.15;text-wrap:balance}
.gn-card p{font-weight:600;opacity:.92}
.gn-guess .row{width:100%}
.gn-guess .row .btn{min-width:min(220px,100%)}
.gn-inp{max-width:440px;text-align:center;font-size:1.2rem}
.gn-miss{display:flex;flex-direction:column;gap:8px;width:100%;max-width:38em;text-align:start}
.gn-miss li{display:flex;flex-direction:column;gap:2px;background:var(--surface-2);border-radius:16px;padding:10px 14px}
.gn-miss b{font-family:var(--f-display)}
.gn-miss span{color:var(--fg-2);font-size:var(--fs-sm)}
@media (max-width:640px){
  .gn-ask{grid-template-columns:1fr;justify-items:center}
  .gn-ask .gn-bubble{text-align:center}
  .gn-ask .gn-bubble::before{right:auto;left:calc(50% - 12px);top:-14px;border:3px solid color-mix(in srgb,var(--c) 55%,transparent);border-right:0;border-bottom:0}
  .gn-side{width:min(200px,60vw)}
  .gn-answers{grid-template-columns:repeat(2,minmax(0,1fr))}
  .gn-a{min-height:64px;flex-direction:row}
  .gn-a[data-a="y"]{order:1}.gn-a[data-a="n"]{order:2}.gn-a[data-a="py"]{order:3}.gn-a[data-a="pn"]{order:4}
  .gn-a[data-a="u"]{order:5;grid-column:1/-1}
}
.gn-say{margin:0;width:100%;justify-content:center;grid-template-columns:auto minmax(0,auto)}
.gn-say .gn-bubble{justify-self:start}
.gn-guess{gap:clamp(12px,1.8vw,18px)}
@media (max-width:640px){
  .gn-say{justify-items:stretch}
  .gn-say .gn-bubble{text-align:center}
  .gn-say .gn-bubble::before{left:auto;right:-13px;top:calc(50% - 12px);border:3px solid color-mix(in srgb,var(--c) 55%,transparent);border-left:0;border-bottom:0}
  .gn-say .gn-leila{--s:84px}
}

/* full screen: the button in every game's bar, or in the corner of a game screen that has no bar */
.fs-btn svg{width:20px;height:20px}
.fs-btn[aria-pressed="true"]{color:var(--c,var(--grape))}
.fs-dock{position:fixed;z-index:30;top:max(12px,env(safe-area-inset-top,0px));inset-inline-end:max(12px,env(safe-area-inset-left,0px));box-shadow:0 10px 22px -12px rgba(30,10,70,.55);animation:popin .3s both}
html[data-fs] .fs-dock{opacity:.8}
@media (prefers-reduced-motion:reduce){.fs-dock{animation:none}}

/* ============================== table games: setup, search, table, XO, snakes & ladders ============================== */
.small{font-size:var(--fs-sm)}
.bg-setup{display:flex;flex-direction:column;gap:18px;margin-top:14px}
.bg-hero{display:flex;align-items:center;gap:clamp(12px,2.4vw,22px);padding:clamp(16px,2.6vw,26px);border-radius:var(--r-xl);color:#fff;background:radial-gradient(130% 120% at 100% 0%,rgba(255,255,255,.24),transparent 55%),linear-gradient(135deg,color-mix(in srgb,var(--c) 88%,#fff),color-mix(in srgb,var(--c) 72%,#1d1446));box-shadow:0 24px 48px -28px color-mix(in srgb,var(--c) 75%,#000);overflow:hidden}
.bg-hero h2{font-size:clamp(1.6rem,3.2vw,2.3rem);color:#fff;text-shadow:0 2px 0 rgba(0,0,0,.12)}
.bg-hero p{opacity:.94;max-width:40em;font-weight:500}
.bg-hero .bg-art{flex:none;width:clamp(96px,16vw,150px);aspect-ratio:1;filter:drop-shadow(0 12px 14px rgba(0,0,0,.25))}
.bg-modes{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}
.bg-mode{display:flex;flex-direction:column;align-items:flex-start;gap:6px;padding:16px;border-radius:var(--r-lg);border:2px solid var(--line-2);background:var(--surface);color:var(--fg);cursor:pointer;text-align:start;font:inherit;transition:transform .15s,border-color .15s,box-shadow .15s,background .15s}
.bg-mode b{font:800 1.12rem/1.2 var(--f-display)}
.bg-mode small{color:var(--fg-2);font-size:var(--fs-sm);line-height:1.45}
.bg-mode:hover{transform:translateY(-2px);border-color:color-mix(in srgb,var(--c) 50%,var(--line-2))}
.bg-mode[aria-pressed="true"]{border-color:var(--c);background:color-mix(in srgb,var(--c) 9%,var(--surface));box-shadow:0 0 0 4px color-mix(in srgb,var(--c) 22%,transparent),0 14px 26px -18px var(--c)}
@media (max-width:520px){.bg-mode{padding:12px}.bg-mode b{font-size:1rem}.bg-mode small{font-size:var(--fs-xs)}}
.bg-join{display:flex;gap:8px;flex-wrap:wrap;align-items:center}
.bg-join .inp{flex:1;min-width:9em;text-transform:uppercase;letter-spacing:.2em;text-align:center;font:800 1.2rem/1 var(--f-display)}

/* searching, inviting */
.bg-search{display:flex;flex-direction:column;align-items:center;gap:14px;text-align:center;padding-top:clamp(24px,8vh,90px)}
.bg-search h2{font-size:clamp(1.5rem,3vw,2.1rem)}
.radar{position:relative;display:grid;place-items:center;width:clamp(170px,40vw,230px);aspect-ratio:1}
.radar>i{position:absolute;inset:0;border-radius:50%;border:3px solid var(--c);opacity:0;animation:bg-radar 2.4s ease-out infinite}
.radar>i:nth-of-type(2){animation-delay:.8s}.radar>i:nth-of-type(3){animation-delay:1.6s}
.radar .avatar{z-index:1;box-shadow:0 10px 30px -10px var(--c)}
@keyframes bg-radar{0%{transform:scale(.35);opacity:.9}100%{transform:scale(1);opacity:0}}
.bg-found{display:flex;flex-wrap:wrap;gap:8px;justify-content:center;list-style:none;padding:0;margin:0}
.bg-found li{display:flex;align-items:center;gap:8px;padding:6px 14px 6px 8px;border-radius:999px;background:var(--surface);box-shadow:var(--shadow);font-weight:700;animation:popin .35s both}
.bg-found li em{font-style:normal;color:var(--fg-2);font-weight:500;font-size:var(--fs-sm)}
.bg-found li.bg-free{color:var(--fg-2);border:2px dashed var(--line-2);box-shadow:none;background:transparent;font-weight:600;padding:8px 14px}
.bg-found li.bg-free svg{width:18px;height:18px;opacity:.7}
.dot-live{width:9px;height:9px;border-radius:50%;background:var(--mint);box-shadow:0 0 0 3px color-mix(in srgb,var(--mint) 30%,transparent)}
.bg-invite{display:flex;flex-direction:column;gap:16px;margin-top:14px}
.center-panel{align-items:center;text-align:center}
.bg-code{font:800 clamp(2.6rem,10vw,4.6rem)/1 var(--f-display);letter-spacing:.2em;color:var(--c);padding-inline-start:.2em}
.bg-qr{width:min(230px,62vw);padding:12px;border-radius:20px;background:#fff;box-shadow:0 10px 30px -18px rgba(0,0,0,.5)}
.bg-qr svg{width:100%;height:auto;display:block}

/* the table */
.bg-top{position:sticky;top:8px;z-index:6;display:flex;flex-direction:column;gap:8px;padding:10px 12px;margin:0 auto 14px;width:min(1160px,calc(100% - 24px));border-radius:24px;background:color-mix(in srgb,var(--surface) 86%,transparent);-webkit-backdrop-filter:blur(14px);backdrop-filter:blur(14px);box-shadow:var(--shadow)}
.bg-bar{display:flex;align-items:center;gap:10px}
.bg-bar h1{font:800 clamp(1.1rem,2.2vw,1.55rem)/1.1 var(--f-display);margin-inline-end:auto;display:flex;align-items:center;gap:8px;min-width:0}
.bg-bar h1 .em{--s:34px}
.bg-bar .chip{font-weight:800}
@media (max-width:430px){.bg-bar>.chip{display:none}.bg-bar h1{font-size:1.05rem}}
.bg-net{display:inline-grid;place-items:center;width:32px;height:32px;border-radius:50%;background:var(--surface-2)}
.bg-net svg{width:18px;height:18px}.bg-net.on{color:var(--mint)}.bg-net.off{color:var(--pome)}
.bg-seats{display:flex;gap:8px;flex-wrap:wrap;list-style:none;margin:0;padding:0}
.bg-seat{display:flex;align-items:center;gap:8px;padding:4px 10px 4px 5px;border-radius:999px;background:var(--surface-2);border:2px solid transparent;transition:background .2s,border-color .2s,box-shadow .2s;min-width:0}
.bg-seat.on{border-color:var(--c);background:color-mix(in srgb,var(--c) 14%,var(--surface));box-shadow:0 0 0 4px color-mix(in srgb,var(--c) 16%,transparent)}
.bg-seat.gone{opacity:.75}
.bg-sn{display:flex;align-items:center;gap:5px;font-size:var(--fs-sm);min-width:0}
.bg-sn b{font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:9em}
.bg-sn em{font-style:normal;font-size:var(--fs-xs);color:var(--fg-2)}
.bg-tag{display:inline-grid;place-items:center;width:20px;height:20px;border-radius:50%;background:var(--surface-3);color:var(--fg-2);flex:none}
.bg-tag svg{width:13px;height:13px}.bg-tag.net{color:var(--sky)}
.bg-sc{font:800 1.02rem/1 var(--f-display);min-width:1.6em;text-align:center;padding:4px 8px;border-radius:999px;background:var(--surface);font-variant-numeric:tabular-nums}
.bg-turn{display:flex;align-items:center;gap:6px;font:700 var(--fs-sm)/1.3 var(--f-display);color:var(--fg-2);margin:0}
.bg-turn svg{width:16px;height:16px}
.bg-turn.me{color:var(--c);font-size:1.06rem;animation:popin .3s both}
.bg-turn.me .em{--s:1.3em}
.bg-dots{display:inline-flex;gap:3px;margin-inline-start:4px;vertical-align:middle}
.bg-dots b{width:5px;height:5px;border-radius:50%;background:currentColor;opacity:.25;animation:bg-dot 1.1s infinite}
.bg-dots b:nth-child(2){animation-delay:.18s}.bg-dots b:nth-child(3){animation-delay:.36s}
@keyframes bg-dot{0%,60%,100%{opacity:.25;transform:none}30%{opacity:1;transform:translateY(-3px)}}
@media (prefers-reduced-motion:reduce){.bg-dots b{animation:none;opacity:.6}}
.bg-body{padding-inline:12px;padding-bottom:24px}
.avatar .av-l svg{display:block;width:calc(var(--s) * .74);height:calc(var(--s) * .74);stroke-width:2.4}
.sl-tok b svg{display:block;width:1.15em;height:1.15em;stroke-width:2.8}

/* the result: a card over the table once the last move has landed; it can step aside to show the final board */
.bg-ov{position:fixed;inset:0;z-index:45;display:grid;place-items:center;padding:16px;background:rgba(22,10,58,.36);-webkit-backdrop-filter:blur(4px);backdrop-filter:blur(4px);animation:bg-ov-in .35s .7s both}
@keyframes bg-ov-in{from{opacity:0}to{opacity:1}}
.bg-over{position:relative;overflow:hidden;width:min(430px,100%);max-height:calc(100dvh - 32px);overflow-y:auto;padding:26px 22px 14px;border-radius:30px;background:var(--surface);box-shadow:0 40px 80px -30px rgba(20,8,60,.7),inset 0 0 0 1px var(--line);display:flex;flex-direction:column;align-items:center;gap:10px;text-align:center;animation:bg-rise .55s .75s cubic-bezier(.2,1.3,.4,1) both}
@keyframes bg-rise{from{transform:translateY(46px) scale(.88);opacity:0}to{transform:none;opacity:1}}
.bg-ov.seen,.bg-ov.seen .bg-over{animation:none}
.bg-over>*:not(.bg-rays){position:relative;z-index:1}
.bg-over.won{background:linear-gradient(175deg,color-mix(in srgb,var(--saffron) 30%,var(--surface)),var(--surface) 58%)}
.bg-rays{position:absolute;left:50%;top:-170px;width:560px;height:560px;margin-left:-280px;border-radius:50%;background:repeating-conic-gradient(from 0deg,color-mix(in srgb,var(--saffron) 42%,transparent) 0deg 9deg,transparent 9deg 22.5deg);-webkit-mask:radial-gradient(closest-side,#000 18%,transparent 72%);mask:radial-gradient(closest-side,#000 18%,transparent 72%);opacity:0;pointer-events:none;z-index:0}
.bg-over.won .bg-rays{opacity:1;animation:bg-spin 26s linear infinite}
@keyframes bg-spin{to{transform:rotate(1turn)}}
.bg-win{display:flex;justify-content:center;gap:14px;padding-top:18px;min-height:96px;align-items:center}
.bg-crowned{position:relative;display:inline-grid;place-items:center}
.bg-crowned .avatar{--s:52px;box-shadow:0 0 0 5px var(--surface),0 0 0 10px color-mix(in srgb,var(--saffron) 75%,#fff),0 22px 34px -14px rgba(20,8,60,.6)}
.bg-crowned .crown{position:absolute;top:-34px;left:50%;margin-left:-19px;z-index:2;transform-origin:50% 100%;animation:bg-crown 1.8s ease-in-out infinite alternate}
@keyframes bg-crown{from{transform:rotate(-10deg) translateY(0)}to{transform:rotate(8deg) translateY(-4px)}}
.bg-over h2{font-size:clamp(1.7rem,6vw,2.3rem);line-height:1.15}
.bg-sub{margin:-4px 0 2px;color:var(--fg-2);font-weight:700}
.bg-board{list-style:none;margin:4px 0 2px;padding:0;display:flex;flex-direction:column;gap:6px;width:100%}
.bg-board li{display:flex;align-items:center;gap:10px;padding:7px 12px 7px 14px;border-radius:14px;background:var(--surface-2);font-weight:700;text-align:start}
.bg-board li.h{background:none;padding-block:0;font:700 var(--fs-xs) var(--f-display);color:var(--fg-2)}
.bg-board li.h b{font-weight:700}
.bg-board li.w{background:color-mix(in srgb,var(--saffron) 26%,var(--surface));box-shadow:inset 0 0 0 2px color-mix(in srgb,var(--saffron) 65%,transparent)}
.bg-board li b{flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.bg-board li b em{font-style:normal;font-weight:500;color:var(--fg-2);font-size:var(--fs-sm)}
.bg-board li span{font:800 1.08rem/1 var(--f-display);font-variant-numeric:tabular-nums}
.bg-board .avatar{--s:19px;box-shadow:none;cursor:default}
.bg-board .avatar .av-l{font-size:15px;text-shadow:none}
.bg-over .row{margin-top:6px}
.bg-peek{display:inline-flex;align-items:center;gap:6px;border:0;background:none;color:var(--fg-2);font:700 var(--fs-sm) var(--f-display);padding:8px 12px;border-radius:999px;cursor:pointer}
.bg-peek:hover{background:var(--surface-2);color:var(--fg)}
.bg-peek svg{width:17px;height:17px}
.bg-mini{display:none}
.bg-ov.peek{background:none;-webkit-backdrop-filter:none;backdrop-filter:none;pointer-events:none;place-items:end center}
.bg-ov.peek .bg-over{display:none}
.bg-ov.peek .bg-mini{display:inline-flex;align-items:center;gap:10px;pointer-events:auto;margin-bottom:max(4px,env(safe-area-inset-bottom));max-width:100%;padding:8px 8px 8px 16px;border:0;border-radius:999px;background:var(--surface);color:var(--fg);box-shadow:0 18px 44px -14px rgba(20,8,60,.6),inset 0 0 0 1px var(--line);font:inherit;cursor:pointer;animation:popin .35s both}
.bg-mini .em{--s:26px}
.bg-mini b{font:800 1.02rem var(--f-display);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0}
.bg-mini span{display:inline-flex;align-items:center;gap:4px;flex:none;padding:8px 14px;border-radius:999px;background:var(--c);color:var(--on-c,#fff);font:800 var(--fs-sm) var(--f-display)}
.bg-mini span svg{width:16px;height:16px}
@media (prefers-reduced-motion:reduce){.bg-ov,.bg-over,.bg-rays,.bg-crowned .crown{animation:none!important}}
@media (max-width:560px){
  .bg-top{padding:8px 10px;gap:6px}
  .bg-seats{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px}
  .bg-seat{padding:3px 8px 3px 4px;gap:6px}
  .bg-seat .avatar{--s:24px}
  .bg-sn{flex:1;gap:4px}
  .bg-sn b{max-width:none}
  .bg-sn em,.bg-tag{display:none}
  .bg-sc{padding:3px 7px;font-size:.95rem}
  /* XO's X/O sits on the avatar's corner, so the name keeps its room */
  .bg-seat{position:relative}
  .bg-seat .xo-sym{position:absolute;inset-inline-start:22px;bottom:-3px;width:18px;height:18px;font-size:.68rem;border-radius:6px;box-shadow:0 0 0 2px var(--surface)}
}
.bg-wait{display:grid;place-items:center;min-height:40vh}

/* إكس أو */
.xo-wrap{display:flex;flex-direction:column;align-items:center;gap:12px;padding-top:6px}
.xo-round{font:700 var(--fs-sm) var(--f-display);color:var(--fg-2);margin:0}
.xo-board{--pad:clamp(10px,2vw,16px);position:relative;display:grid;grid-template-columns:repeat(3,1fr);grid-template-rows:repeat(3,1fr);gap:clamp(8px,1.6vw,14px);width:min(92vw,60vh,520px);aspect-ratio:1;padding:var(--pad);border-radius:34px;background:linear-gradient(160deg,color-mix(in srgb,var(--c) 24%,var(--surface)),color-mix(in srgb,var(--c) 6%,var(--surface)));box-shadow:0 34px 64px -36px color-mix(in srgb,var(--c) 70%,#000),inset 0 0 0 1px var(--line)}
.xo-c{position:relative;display:grid;place-items:center;border-radius:24px;background:var(--surface);box-shadow:inset 0 -6px 0 rgba(30,10,80,.08),0 8px 16px -12px rgba(30,10,80,.45);border:0;padding:0;color:inherit}
.xo-c.open{cursor:pointer;transition:transform .12s,background .15s}
.xo-board.live .xo-c.open:hover{transform:translateY(-3px);background:color-mix(in srgb,var(--c) 7%,var(--surface))}
.xo-c.open:active{transform:scale(.95)}
.xo-ghost{display:grid;place-items:center;width:100%;height:100%;opacity:0;transition:opacity .15s}
.xo-ghost .xo-m{opacity:.22}
.xo-c.open:hover .xo-ghost,.xo-c.open:focus-visible .xo-ghost{opacity:1}
.xo-m{width:74%;height:74%;fill:none;stroke-linecap:round;stroke-width:13;overflow:visible}
.xo-m.x{stroke:var(--pome)}.xo-m.o{stroke:var(--sky)}
.xo-m.draw path,.xo-m.draw circle{stroke-dasharray:190;stroke-dashoffset:190;animation:xo-draw .3s ease-out forwards}
.xo-m.draw path:nth-child(2){animation-delay:.15s}
@keyframes xo-draw{to{stroke-dashoffset:0}}
.xo-c.hot{background:color-mix(in srgb,var(--saffron) 30%,var(--surface));animation:xo-hot .5s .25s both}
@keyframes xo-hot{0%{transform:scale(1)}50%{transform:scale(1.07)}100%{transform:scale(1)}}
.xo-line{position:absolute;inset:var(--pad);width:calc(100% - var(--pad) * 2);height:calc(100% - var(--pad) * 2);pointer-events:none;overflow:visible}
.xo-line line{stroke-width:11;stroke-linecap:round;opacity:.9}
.xo-line.x line{stroke:var(--pome)}.xo-line.o line{stroke:var(--sky)}
.xo-line.draw line{stroke-dasharray:440;stroke-dashoffset:440;animation:xo-draw .5s .25s ease-out forwards}
.xo-sym{font:800 .9rem/1 var(--f-display);width:24px;height:24px;display:grid;place-items:center;border-radius:8px;color:#fff;flex:none}
.xo-sym.x{background:var(--pome)}.xo-sym.o{background:var(--sky)}

/* السلّم والحيّة */
.sl-wrap{display:grid;grid-template-columns:minmax(0,1fr) minmax(220px,270px);gap:18px;align-items:start;max-width:1120px;margin:0 auto}
.sl-board{position:relative;width:min(100%,76vh);aspect-ratio:1;margin-inline:auto;border-radius:20px;overflow:hidden;background:#fff3dd;box-shadow:0 30px 60px -34px rgba(30,10,80,.65),0 0 0 7px color-mix(in srgb,var(--c) 40%,#fff)}
.sl-cells{position:absolute;inset:0;display:grid;grid-template-columns:repeat(10,1fr);grid-template-rows:repeat(10,1fr)}
.sl-c{position:relative;display:flex;align-items:flex-start;justify-content:flex-start;padding:4px 5px;font:800 clamp(8px,1.25vw,13px)/1 var(--f-display);color:rgba(60,35,110,.5)}
.sl-c.a{background:#fff5e2}.sl-c.b{background:#ffe6c7}
.sl-c.up{background:#dcf7e6}.sl-c.down{background:#ffe0e7}
.sl-c.goal{background:linear-gradient(135deg,#ffd166,#ffb703);color:#5a3a00}
.sl-c.goal .em{position:absolute;inset:0;margin:auto;--s:62%;filter:drop-shadow(0 3px 3px rgba(120,60,0,.35))}
.sl-art{position:absolute;inset:0;width:100%;height:100%;pointer-events:none;filter:drop-shadow(0 .6px .6px rgba(40,20,60,.45))}
.sl-lad line{stroke-linecap:round}
.sl-lad .rail-o line{stroke:#5a3012;stroke-width:1.95}
.sl-lad .rail line{stroke:#b8763a;stroke-width:1.15}
.sl-lad .rung-o line{stroke:#5a3012;stroke-width:1.45}
.sl-lad .rung line{stroke:#e8b273;stroke-width:.7}
.sl-snake line{stroke-linecap:round}
.sl-snake .tongue{stroke:#e11d48;stroke-width:.42;fill:none;stroke-linecap:round}
.sl-toks{position:absolute;inset:0}
.sl-tok{position:absolute;width:6.6%;aspect-ratio:1;transform:translate(-50%,-50%);border-radius:50%;background:radial-gradient(circle at 34% 30%,color-mix(in srgb,var(--c) 35%,#fff),var(--c) 62%);border:2px solid #fff;box-shadow:0 5px 9px rgba(20,10,40,.4);display:grid;place-items:center;z-index:2;transition:left .25s,top .25s}
.sl-tok b{font:800 clamp(9px,1.4vw,15px)/1 var(--f-display);color:#fff;text-shadow:0 1px 2px rgba(0,0,0,.45)}
.sl-tok.turn{z-index:3;animation:sl-bob .9s ease-in-out infinite alternate}
@keyframes sl-bob{from{transform:translate(-50%,-50%)}to{transform:translate(-50%,-66%)}}
.sl-side{display:flex;flex-direction:column;align-items:center;gap:14px;padding:18px;border-radius:var(--r-xl);background:var(--surface);box-shadow:var(--shadow);position:sticky;top:132px}
.sl-msg{text-align:center;color:var(--fg-2);font-weight:600;min-height:3.2em;margin:0}
.sl-wait{display:flex;align-items:center;gap:6px;font:700 1rem var(--f-display);color:var(--fg-2);margin:0}
.sl-roll{width:100%}
.die{display:grid;grid-template-columns:repeat(3,1fr);grid-template-rows:repeat(3,1fr);gap:4px;width:84px;height:84px;padding:12px;border-radius:22px;background:linear-gradient(145deg,#fff,#efe8ff);box-shadow:inset 0 -6px 0 rgba(60,30,140,.13),0 14px 22px -12px rgba(40,20,90,.55)}
.die i{border-radius:50%}
.die i.on{background:radial-gradient(circle at 35% 35%,#6a59b3,#1d1446)}
.die.big{width:112px;height:112px;padding:17px;gap:6px}
.die.blank{position:relative}
.die.blank::after{content:'؟';position:absolute;inset:0;display:grid;place-items:center;font:800 2.6rem/1 var(--f-display);color:color-mix(in srgb,#1d1446 22%,transparent)}
.die.roll{animation:die-roll .65s cubic-bezier(.3,1.35,.5,1)}
@keyframes die-roll{0%{transform:rotate(0) scale(.55)}45%{transform:rotate(210deg) scale(1.15)}75%{transform:rotate(330deg) scale(.96)}100%{transform:rotate(360deg) scale(1)}}
@media (max-width:820px){.sl-wrap{grid-template-columns:1fr}.sl-side{position:static;flex-direction:row;flex-wrap:wrap;justify-content:center}.sl-side .die.big{width:84px;height:84px;padding:12px;gap:4px}.sl-roll{width:auto;flex:1}.sl-msg{flex-basis:100%;min-height:0}}
@media (prefers-reduced-motion:reduce){.radar>i,.sl-tok.turn{animation:none}}

/* ---------------- the table, live: quick chat, a lost connection, a game to pick up again ---------------- */
.spinner{width:34px;height:34px;margin:18px auto;border-radius:50%;border:3.5px solid color-mix(in srgb,var(--grape) 22%,transparent);border-top-color:var(--grape);animation:spin .8s linear infinite}
.spinner.sm{display:inline-block;width:15px;height:15px;margin:0;border-width:2.5px;vertical-align:-2px;border-color:currentColor;border-top-color:transparent;opacity:.85}
.bg-say svg{width:21px;height:21px}
.bg-say{color:var(--grape)}
.say-pop{position:fixed;z-index:70;top:72px;left:0;right:0;margin:0 auto;width:min(430px,calc(100% - 20px));max-height:calc(100dvh - 90px);overflow:auto;display:flex;flex-direction:column;gap:10px;padding:12px;border-radius:22px;background:var(--surface);border:1px solid var(--line-2);box-shadow:0 24px 48px -18px rgba(30,10,80,.55);animation:rise .2s both}
.say-row{display:grid;grid-template-columns:repeat(8,minmax(0,1fr));gap:4px}
.say-e{display:grid;place-items:center;aspect-ratio:1;border:0;border-radius:14px;background:var(--surface-2);cursor:pointer;transition:transform .12s,background .15s;-webkit-tap-highlight-color:transparent}
.say-e:hover{background:var(--surface-3)}
.say-e:active{transform:scale(.88)}
.say-e .em{--s:min(30px,8vw)}
.say-lines{display:flex;flex-wrap:wrap;gap:6px}
.say-t{display:inline-flex;align-items:center;gap:6px;padding:.42em .85em .42em .7em;min-height:38px;border-radius:999px;border:1.5px solid var(--line-2);background:var(--surface);color:var(--fg);font:700 var(--fs-sm)/1.2 var(--f-display);cursor:pointer;-webkit-tap-highlight-color:transparent;transition:transform .12s,background .15s,border-color .15s}
.say-t:hover{background:var(--surface-2);border-color:var(--grape)}
.say-t:active{transform:scale(.95)}
.say-mute{display:flex;align-items:center;gap:8px;font-size:var(--fs-xs);color:var(--fg-3);padding:2px 4px 0;cursor:pointer}
.say-mute input{width:17px;height:17px;accent-color:var(--grape)}
.say-bub{position:fixed;z-index:65;pointer-events:none;display:flex;flex-direction:column;align-items:center;gap:2px;max-width:min(240px,70vw);padding:7px 13px 9px;border-radius:18px;background:var(--surface);color:var(--fg);border:2px solid var(--c,var(--grape));box-shadow:0 14px 30px -12px rgba(20,8,60,.55);animation:say-in .32s cubic-bezier(.2,1.4,.4,1) both;text-align:center}
.say-bub b{font:700 var(--fs-xs)/1.2 var(--f-body);color:var(--c,var(--grape));white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:100%}
.say-bub span{display:flex;align-items:center;gap:5px;font:800 1.02rem/1.25 var(--f-display)}
.say-bub.big{padding:5px 10px 6px;border-radius:22px}
.say-bub.big .em{animation:say-wob .9s ease-in-out .15s both}
.say-bub.out{opacity:0;transform:translateY(-8px) scale(.94);transition:opacity .45s,transform .45s}
@keyframes say-in{from{opacity:0;transform:translateY(8px) scale(.6)}to{opacity:1;transform:none}}
@keyframes say-wob{0%,100%{transform:none}30%{transform:rotate(-12deg) scale(1.15)}60%{transform:rotate(9deg)}}
.bg-lost{display:flex;align-items:center;justify-content:center;gap:8px;margin:0;padding:7px 12px;border-radius:14px;background:color-mix(in srgb,var(--orange) 16%,var(--surface));color:color-mix(in srgb,var(--orange) 70%,var(--fg));font:700 var(--fs-sm)/1.3 var(--f-display)}
.bg-resume{flex-direction:row;align-items:center;flex-wrap:wrap;gap:12px 14px;border:2px dashed var(--saffron);box-shadow:none;animation:popin .3s both}
.bg-resume>div:first-of-type{flex:1 1 160px;display:flex;flex-direction:column;gap:2px;min-width:0}
.bg-resume b{font:800 var(--fs-md)/1.3 var(--f-display)}
.bg-resume .row{display:flex;gap:8px;flex-wrap:wrap;align-items:center}
@media (prefers-reduced-motion:reduce){.say-pop,.say-bub,.say-bub.big .em,.bg-resume{animation:none}.spinner{animation-duration:2s}}

/* ============================== playing cards and the card table (طرنيب، تركس، هاند) ============================== */
.card{--w:70px;position:relative;display:inline-block;flex:none;width:var(--w);height:calc(var(--w) * 1.4);border-radius:calc(var(--w) * .13);background:linear-gradient(165deg,#fff 0%,#fbf7ee 100%);color:#21174d;box-shadow:inset 0 0 0 1px rgba(33,23,77,.14),0 1px 1px rgba(33,23,77,.08),0 8px 16px -10px rgba(20,12,60,.65);font-family:var(--f-display);direction:ltr;-webkit-user-select:none;user-select:none;overflow:hidden;vertical-align:top;transition:transform .16s,box-shadow .16s,filter .16s}
.card.red{color:#df2350}
.pip{display:block;fill:currentColor}
.card .ci{position:absolute;left:7%;top:5%;display:flex;flex-direction:column;align-items:center;gap:calc(var(--w) * .015);font-weight:800;font-size:calc(var(--w) * .25);line-height:.92;letter-spacing:-.03em}
.card .ci .pip{width:calc(var(--w) * .17);height:calc(var(--w) * .17)}
.card .ci2{left:auto;top:auto;right:7%;bottom:5%;transform:rotate(180deg)}
.card .cn,.card .ca{position:absolute;inset:0;display:grid;place-items:center}
.card .cn .pip{width:44%;height:auto;filter:drop-shadow(0 2px 0 rgba(0,0,0,.07))}
.card .ca .pip{width:56%;height:auto}
.card .ca::before{content:'';position:absolute;width:76%;aspect-ratio:1;border-radius:50%;border:calc(var(--w) * .025) solid currentColor;opacity:.16}
.card .cf{position:absolute;inset:17% 16%;border-radius:calc(var(--w) * .08);display:grid;place-items:center;background:linear-gradient(160deg,color-mix(in srgb,currentColor 15%,#fff),color-mix(in srgb,currentColor 5%,#fff));box-shadow:inset 0 0 0 calc(var(--w) * .02) color-mix(in srgb,currentColor 32%,transparent)}
.card .cf .cfe{--s:calc(var(--w) * .42);margin-top:-12%}
.card .cf b{position:absolute;bottom:5%;font-size:calc(var(--w) * .19);font-weight:800;opacity:.9}
.card.joker{background:linear-gradient(160deg,#fff6d8,#ffe2f1)}
.card.joker .cj{--s:calc(var(--w) * .6);position:absolute;inset:0;margin:auto}
.card.joker .ci{color:#7c3aed;font-size:calc(var(--w) * .22)}
.card.back{background:#fff;box-shadow:0 1px 1px rgba(33,23,77,.1),0 8px 16px -10px rgba(20,12,60,.7)}
.card.back i{position:absolute;inset:calc(var(--w) * .06);border-radius:calc(var(--w) * .08);background:repeating-linear-gradient(45deg,rgba(255,255,255,.12) 0 2px,transparent 2px 8px),repeating-linear-gradient(-45deg,rgba(255,255,255,.12) 0 2px,transparent 2px 8px),linear-gradient(160deg,#6b45ff,#2a0f8a)}
.card.back i::after{content:'ل';position:absolute;inset:0;margin:auto;width:42%;height:30%;display:grid;place-items:center;border-radius:999px;background:#2a0f8a;color:#ffd23f;font:800 calc(var(--w) * .2)/1 var(--f-display);box-shadow:0 0 0 calc(var(--w) * .02) #ffd23f}

/* a hand of cards: each slot shrinks so the fan fits; the last card always shows whole */
.ch{--cw:clamp(56px,16vw,88px);display:flex;justify-content:center;align-items:flex-end;width:100%;max-width:100%;padding:22px 2px 4px;direction:ltr;min-height:calc(var(--cw) * 1.4 + 26px)}
.ch-slot{position:relative;flex:0 1 var(--cw);min-width:0;height:calc(var(--cw) * 1.4);border:0;background:none;padding:0;margin:0;font:inherit;color:inherit}
.ch-slot:last-child{flex-shrink:0}
.ch-slot>.card{--w:var(--cw);position:absolute;left:0;top:0}
button.ch-slot{cursor:pointer}
button.ch-slot:hover>.card,button.ch-slot:focus-visible>.card{transform:translateY(-10px);box-shadow:inset 0 0 0 1px rgba(33,23,77,.14),0 14px 22px -10px rgba(20,12,60,.7)}
button.ch-slot:focus-visible{outline:none}
button.ch-slot:focus-visible>.card{box-shadow:0 0 0 3px var(--c),0 14px 22px -10px rgba(20,12,60,.7)}
.ch-slot.sel>.card{transform:translateY(-20px);box-shadow:0 0 0 3px #ffd23f,0 16px 24px -10px rgba(20,12,60,.7)}
.ch-slot>.card.dim{filter:brightness(.78) saturate(.7)}
.ch.deal .ch-slot>.card{animation:ch-deal .5s cubic-bezier(.2,1,.4,1) both;animation-delay:calc(var(--i) * 45ms)}
@keyframes ch-deal{from{transform:translateY(-140px) rotate(-14deg) scale(.55);opacity:0}}
.ch.live button.ch-slot>.card{box-shadow:inset 0 0 0 1px rgba(33,23,77,.14),0 0 0 2px color-mix(in srgb,#ffd23f 75%,transparent),0 8px 16px -10px rgba(20,12,60,.65)}

/* the felt */
.ctab{position:relative;direction:ltr;max-width:980px;margin:4px auto 0;border-radius:30px;padding:10px 8px;background:radial-gradient(120% 95% at 50% 40%,#22985f 0%,#147048 55%,#0c5034 100%);box-shadow:inset 0 0 0 6px #6b3e1d,inset 0 0 0 9px #9a6634,inset 0 12px 40px rgba(0,0,0,.34),0 26px 50px -28px rgba(8,40,24,.85);display:grid;grid-template-columns:minmax(70px,1fr) minmax(0,2.4fr) minmax(70px,1fr);grid-template-rows:auto minmax(260px,1fr);grid-template-areas:". t ." "l m r";gap:4px 6px;color:#fff;overflow:hidden}
.ctab::before{content:'';position:absolute;inset:9px;border-radius:22px;background:radial-gradient(circle at 50% 46%,rgba(255,255,255,.07),transparent 62%);pointer-events:none}
.ctab.n2{grid-template-areas:". t ." ". m ."}
.cmid{grid-area:m;position:relative;display:grid;place-items:center;min-height:260px;direction:rtl}

/* a player's spot */
.cseat{position:relative;z-index:1;display:flex;flex-direction:column;align-items:center;gap:4px;text-align:center;min-width:0;padding:6px 2px;direction:rtl}
.cseat.p-t{grid-area:t;flex-direction:row;gap:8px;justify-self:center;padding-top:8px}
.cseat.p-l{grid-area:l;align-self:center}
.cseat.p-r{grid-area:r;align-self:center}
.cseat.p-t .cs-tx{flex-direction:column;align-items:flex-start}
.cs-av{position:relative;flex:none}
.cs-av .avatar{--s:28px;cursor:default;box-shadow:0 0 0 3px rgba(255,255,255,.9),0 8px 16px -6px rgba(0,0,0,.6)}
.cseat.on .cs-av .avatar{box-shadow:0 0 0 3px #ffd23f,0 8px 16px -6px rgba(0,0,0,.6)}
.cs-ring{position:absolute;inset:-8px;border-radius:50%;border:3px solid #ffd23f;animation:cs-pulse 1.3s ease-in-out infinite;pointer-events:none}
@keyframes cs-pulse{0%,100%{transform:scale(.96);opacity:1}50%{transform:scale(1.1);opacity:.35}}
.cs-tx{display:flex;flex-wrap:wrap;align-items:center;justify-content:center;gap:3px;font:700 var(--fs-sm)/1.2 var(--f-display);max-width:100%;text-shadow:0 1px 2px rgba(0,0,0,.4)}
.cs-tx b{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:7.5em}
.cs-tx .bg-tag{width:18px;height:18px;background:rgba(255,255,255,.18);color:#fff}
.cs-sub{display:block;width:100%;font-size:var(--fs-xs);font-weight:600;opacity:.88}
.cs-bd{display:flex;gap:4px;flex-wrap:wrap;justify-content:center}
.cbadge{display:inline-flex;align-items:center;gap:3px;padding:2px 8px;border-radius:999px;background:rgba(255,255,255,.16);font:800 .76rem/1.4 var(--f-display);color:#fff;white-space:nowrap}
.cbadge .pip{width:12px;height:12px}
.cbadge.gold{background:#ffd23f;color:#3a2600}
.cbadge.red .pip{color:#ff5a7e}
.cbadge.gold.red .pip{color:#c3123f}
.cbadge.dark{background:rgba(0,0,0,.28)}
.cbadge .card{--w:16px;border-radius:3px;box-shadow:none}
.cbacks{position:relative;display:inline-block;height:28px;width:calc(20px + (var(--k) - 1) * 5px)}
.cbacks i{position:absolute;top:0;width:20px;height:28px;border-radius:4px;background:repeating-linear-gradient(45deg,rgba(255,255,255,.14) 0 1.5px,transparent 1.5px 5px),linear-gradient(160deg,#6b45ff,#2a0f8a);box-shadow:0 0 0 1.5px #fff,0 2px 5px rgba(0,0,0,.4)}
.cbacks b{position:absolute;bottom:-6px;right:-10px;min-width:20px;height:20px;padding:0 5px;border-radius:999px;background:#fff;color:#21174d;font:800 .72rem/20px var(--f-display);box-shadow:0 2px 6px rgba(0,0,0,.35)}
.cs-corner{position:absolute;bottom:-4px;left:-8px;display:grid;place-items:center;min-width:20px;height:20px;padding:0 4px;border-radius:999px;background:#ffd23f;color:#3a2600;font:800 .7rem/1 var(--f-display);box-shadow:0 2px 6px rgba(0,0,0,.35)}

/* the trick in the middle */
.ctrick{--tw:clamp(50px,14.5vw,80px);position:relative;width:min(100%,330px);height:calc(var(--tw) * 2.9)}
.ct-c{position:absolute;left:50%;top:50%;z-index:calc(1 + var(--k))}
.ct-c .card{--w:var(--tw)}
.ct-c.at-b{transform:translate(-50%,-14%) rotate(3deg)}
.ct-c.at-t{transform:translate(-50%,-88%) rotate(-4deg)}
.ct-c.at-l{transform:translate(-128%,-52%) rotate(-8deg)}
.ct-c.at-r{transform:translate(28%,-48%) rotate(7deg)}
.ct-c.new.at-b{animation:ct-in-b .3s cubic-bezier(.2,1,.4,1)}
.ct-c.new.at-t{animation:ct-in-t .3s cubic-bezier(.2,1,.4,1)}
.ct-c.new.at-l{animation:ct-in-l .3s cubic-bezier(.2,1,.4,1)}
.ct-c.new.at-r{animation:ct-in-r .3s cubic-bezier(.2,1,.4,1)}
@keyframes ct-in-b{from{transform:translate(-50%,100%) rotate(3deg);opacity:0}}
@keyframes ct-in-t{from{transform:translate(-50%,-200%) rotate(-4deg);opacity:0}}
@keyframes ct-in-l{from{transform:translate(-250%,-52%) rotate(-8deg);opacity:0}}
@keyframes ct-in-r{from{transform:translate(150%,-48%) rotate(7deg);opacity:0}}
.ct-c.top .card{box-shadow:0 0 0 3px #ffd23f,0 0 24px rgba(255,210,63,.75),0 8px 16px -10px rgba(20,12,60,.65)}
.ctrick.won .ct-c{animation:ct-out .42s .55s cubic-bezier(.5,0,.8,.4) forwards}
.ctrick.won.to-b{--tx:-50%;--ty:180%}.ctrick.won.to-t{--tx:-50%;--ty:-280%}.ctrick.won.to-l{--tx:-300%;--ty:-50%}.ctrick.won.to-r{--tx:200%;--ty:-50%}
@keyframes ct-out{to{transform:translate(var(--tx),var(--ty)) scale(.45);opacity:0}}

/* panels on the felt: bidding, trump, contracts, results between deals */
.cpanel,.csum{position:relative;z-index:4;width:min(100%,330px);background:rgba(255,255,255,.97);color:var(--fg);border-radius:22px;padding:14px;box-shadow:0 22px 44px -18px rgba(0,0,0,.7);text-align:center;direction:rtl}
.cpanel h3,.csum h3{font:800 1.08rem/1.3 var(--f-display);margin:0 0 10px}
.cpanel p{margin:0 0 10px;color:var(--fg-2);font-size:var(--fs-sm)}
.cgrid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:7px}
.cgrid.c2{grid-template-columns:repeat(2,minmax(0,1fr))}
.cgrid.c3{grid-template-columns:repeat(3,minmax(0,1fr))}
.cbtn{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;min-height:48px;padding:6px 4px;border-radius:14px;border:0;background:var(--surface-2);color:var(--fg);font:800 1.15rem/1.1 var(--f-display);cursor:pointer;box-shadow:inset 0 -3px 0 rgba(30,10,80,.1);transition:transform .12s,background .12s}
.cbtn:hover:not(:disabled){transform:translateY(-2px);background:color-mix(in srgb,var(--c) 14%,var(--surface))}
.cbtn:active:not(:disabled){transform:scale(.96)}
.cbtn:disabled{opacity:.35;cursor:not-allowed}
.cbtn small{font:600 var(--fs-xs)/1.2 var(--f-body,inherit);color:var(--fg-2)}
.cbtn .pip{width:30px;height:30px}
.cbtn.red{color:#df2350}
.cbtn.wide{grid-column:1/-1;min-height:44px;font-size:1rem;flex-direction:row;gap:8px}
.cbtn.pri{background:var(--c);color:var(--on-c,#fff);box-shadow:inset 0 -3px 0 rgba(0,0,0,.16)}
.cbtn.used{text-decoration:line-through}
.cmsg{position:relative;z-index:3;max-width:min(100%,320px);padding:8px 14px;border-radius:999px;background:rgba(0,0,0,.28);font:700 var(--fs-sm)/1.4 var(--f-display);text-align:center;direction:rtl}
.csum table{width:100%;border-collapse:collapse;margin:4px 0 10px;font-variant-numeric:tabular-nums}
.csum td,.csum th{padding:6px 6px;border-bottom:1px solid var(--line);font-size:var(--fs-sm)}
.csum th{font:700 var(--fs-xs) var(--f-display);color:var(--fg-2)}
.csum td:first-child{text-align:start;font-weight:700}
/* numbers keep their sign in front (−4, not 4−) inside the right-to-left tables */
.csum td:not(:first-child){text-align:center;unicode-bidi:plaintext}
.ct3-note td{unicode-bidi:plaintext}
.csum .pos{color:var(--mint);font-weight:800}.csum .neg{color:var(--pome);font-weight:800}
.csum .big{font:800 1.5rem/1.2 var(--f-display);margin:4px 0 8px}
.csum .bar{height:6px;border-radius:99px;background:var(--surface-2);overflow:hidden;margin-top:2px}
.csum .bar i{display:block;height:100%;border-radius:99px;background:var(--c)}

/* you: your spot and your hand under the felt */
.cme{max-width:980px;margin:6px auto 0;display:flex;flex-direction:column;align-items:center;gap:2px}
.cme-bar{display:flex;align-items:center;justify-content:center;gap:8px;flex-wrap:wrap;min-height:34px;padding:0 10px}
.cme-bar .cseat{flex-direction:row;padding:0;color:var(--fg)}
.cme-bar .cseat .cs-tx{text-shadow:none}
.cme-bar .cbadge{background:var(--surface-2);color:var(--fg)}
.cme-bar .cbadge.gold{background:#ffd23f;color:#3a2600}
.cme-bar .cs-tx .bg-tag{background:var(--surface-3);color:var(--fg-2)}
.cme-hint{font:700 var(--fs-sm) var(--f-display);color:var(--c);display:flex;align-items:center;gap:6px}
.cme-acts{display:flex;gap:8px;flex-wrap:wrap;justify-content:center;padding:4px 10px}
.cme-acts .btn{min-height:42px}

/* the top bar of a card game: team or player scores instead of the seat chips */
.cscore{display:flex;gap:8px;flex-wrap:wrap;align-items:center}
.cscore span{display:inline-flex;align-items:center;gap:6px;padding:5px 12px 5px 6px;border-radius:999px;background:var(--surface-2);font:700 var(--fs-sm) var(--f-display)}
.cscore span b{font:800 1.05rem/1 var(--f-display);font-variant-numeric:tabular-nums;padding:3px 8px;border-radius:999px;background:var(--surface);min-width:1.8em;text-align:center}
.cscore span.us{background:color-mix(in srgb,var(--c) 16%,var(--surface));box-shadow:inset 0 0 0 2px color-mix(in srgb,var(--c) 45%,transparent)}
.cscore .dot{width:10px;height:10px;border-radius:50%;background:var(--c)}
.cscore .to{color:var(--fg-2);font-size:var(--fs-xs);background:none;padding:0}

@media (max-width:620px){
  .ctab{grid-template-columns:62px minmax(0,1fr) 62px;border-radius:24px;padding:8px 4px;grid-template-rows:auto minmax(250px,1fr)}
  .cmid{min-height:250px}
  .tx-score{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:5px}
  .tx-score span{padding:3px 6px 3px 4px;font-size:.74rem;gap:4px;min-width:0}
  .tx-score span b{font-size:.9rem;padding:2px 6px}
  .tx-score .to{grid-column:1/-1}
  .cseat.p-t{padding-top:6px}
  .cs-tx{font-size:.72rem}
  .cs-tx b{max-width:5.6em}
  .cseat.p-l .cs-tx b,.cseat.p-r .cs-tx b{max-width:4.6em}
  .cbadge{font-size:.68rem;padding:1px 6px}
  .ctrick{--tw:clamp(48px,14.5vw,62px)}
  .cpanel,.csum{padding:12px 10px;border-radius:18px}
  .cbtn{min-height:44px;font-size:1.05rem}
}
@media (min-width:900px){
  .ctrick{width:min(100%,420px)}
  .ct-c.at-b{transform:translate(-50%,-4%) rotate(3deg)}
  .ct-c.at-t{transform:translate(-50%,-98%) rotate(-4deg)}
  .ct-c.at-l{transform:translate(-158%,-52%) rotate(-8deg)}
  .ct-c.at-r{transform:translate(58%,-48%) rotate(7deg)}
}
@media (prefers-reduced-motion:reduce){.cs-ring,.ct-c.new,.ctrick.won .ct-c,.ch.deal .ch-slot>.card{animation:none!important}}

/* طرنيب and تركس: the corner badge (trump, contract) */
.tn-corner{position:absolute;top:4px;left:6px;z-index:3;display:flex;align-items:center;gap:6px;padding:3px 10px 3px 4px;border-radius:999px;background:rgba(0,0,0,.26);font:800 .9rem/1 var(--f-display);direction:rtl;max-width:calc(100% - 12px)}
.tn-corner .em{--s:22px}
.tn-corner span{white-space:nowrap}
.tn-pip{display:inline-grid;place-items:center;color:#21174d;vertical-align:middle}
.tn-pip.red{color:#df2350}
.tn-pip .pip{width:18px;height:18px}
.tn-pip.big{width:26px;height:26px;border-radius:50%;background:#fff}
.tn-pip.big .pip{width:17px;height:17px}
.csum .tn-pip{width:20px;height:20px;border-radius:50%;background:var(--surface-2)}
.csum .tn-pip .pip{width:13px;height:13px}
.tx-pick .cbtn{min-height:78px;font-size:.95rem;gap:3px;padding:8px 6px}
.tx-pick .cbtn .em{--s:30px}
.tx-pick .cbtn span{font-weight:800}
.tx-pick .cbtn small{font-size:.64rem;line-height:1.35}
.tx-pick .cbtn:last-child{grid-column:1/-1;min-height:64px}
.tx-dbl{display:flex;gap:12px;justify-content:center;margin:2px 0 12px}
.tx-dc{display:flex;flex-direction:column;align-items:center;gap:6px;border:0;background:none;cursor:pointer;font:700 var(--fs-sm) var(--f-display);color:var(--fg-2);padding:4px}
.tx-dc .card{--w:54px}
.tx-dc.on .card{box-shadow:0 0 0 3px #ffd23f,0 12px 20px -10px rgba(20,12,60,.7);transform:translateY(-4px)}
.tx-dc.on span{color:var(--c)}
.tx-lay{position:relative;z-index:2;display:flex;flex-direction:column;gap:5px;width:100%;max-width:440px;direction:ltr;padding-top:26px}
.tx-row{display:flex;align-items:center;gap:6px;min-height:clamp(40px,10vw,58px)}
.tx-s{flex:none;width:24px;height:24px;border-radius:50%;background:#fff;display:grid;place-items:center;color:#21174d;box-shadow:0 2px 6px rgba(0,0,0,.3)}
.tx-row.red .tx-s{color:#df2350}
.tx-s .pip{width:15px;height:15px}
.tx-cards{display:flex;min-width:0;flex:1;align-items:center}
.tx-cards .card{--w:clamp(28px,7.6vw,42px);margin-right:calc(var(--w) * -.52)}
.tx-cards .card:last-child{margin-right:0}
.tx-cards .card.just{box-shadow:0 0 0 2px #ffd23f,0 0 14px rgba(255,210,63,.8)}
.tx-empty{font-size:var(--fs-xs);opacity:.75;font-style:normal;direction:rtl}
.tx-pass{position:relative;z-index:3;margin-top:8px;direction:rtl}
.tx-score span{padding-inline-end:10px}

/* هاند */
.ctab.hd-tab{display:flex;flex-direction:column;gap:10px;padding:12px 10px}
.hd-ops{position:relative;z-index:1;display:flex;gap:8px;flex-wrap:wrap;justify-content:center;direction:rtl}
.hd-op{position:relative;display:flex;align-items:center;gap:8px;padding:6px 12px 6px 8px;border-radius:16px;background:rgba(0,0,0,.2);transition:box-shadow .2s}
.hd-op.on{box-shadow:0 0 0 2px #ffd23f,0 0 18px rgba(255,210,63,.45)}
.hd-op .cs-ring{display:none}
.hd-op .avatar{--s:24px;cursor:default;box-shadow:0 0 0 2px #fff}
.hd-op-t{display:flex;flex-direction:column;font:700 .8rem/1.25 var(--f-display);min-width:0}
.hd-op-t b{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:7em}
.hd-op-t span{display:flex;align-items:center;gap:3px;font-size:.68rem;opacity:.85}
.hd-op-t span svg{width:12px;height:12px}
.hd-op .cbacks{margin-inline-start:4px}
.hd-tab .cmid{min-height:0}
.hd-center{position:relative;z-index:1;display:flex;flex-direction:column;align-items:center;gap:12px;width:100%}
.hd-piles{display:flex;gap:22px;align-items:center;justify-content:center;direction:ltr}
.hd-stock,.hd-pile{position:relative;display:inline-grid;place-items:center;border:0;background:none;padding:0;font:inherit;color:inherit}
.hd-stock .card,.hd-pile .card{--w:clamp(50px,13vw,70px)}
.hd-stock b{position:absolute;bottom:-8px;right:-10px;min-width:24px;height:22px;padding:0 6px;border-radius:999px;background:#fff;color:#21174d;font:800 .75rem/22px var(--f-display);box-shadow:0 2px 6px rgba(0,0,0,.35)}
.hd-stock.can,.hd-pile.can{cursor:pointer}
.hd-stock.can .card,.hd-pile.can .card{box-shadow:0 0 0 3px #ffd23f,0 10px 20px -8px rgba(0,0,0,.6);animation:hd-glow 1.5s ease-in-out infinite}
.hd-stock.can:hover .card,.hd-pile.can:hover .card{transform:translateY(-4px)}
@keyframes hd-glow{0%,100%{filter:brightness(1)}50%{filter:brightness(1.08)}}
.hd-empty{display:grid;place-items:center;width:clamp(50px,13vw,70px);aspect-ratio:5/7;border:2px dashed rgba(255,255,255,.45);border-radius:10px;font-size:.72rem;opacity:.8}
.hd-melds{display:flex;flex-wrap:wrap;gap:8px;justify-content:center;max-width:100%}
.hd-m{display:inline-flex;padding:5px 6px;border-radius:12px;background:rgba(255,255,255,.13);box-shadow:inset 0 0 0 2px color-mix(in srgb,var(--c) 75%,transparent);border:0;direction:ltr;font:inherit;color:inherit}
.hd-m.can{cursor:pointer;background:rgba(255,210,63,.28);box-shadow:inset 0 0 0 2px #ffd23f,0 0 16px rgba(255,210,63,.5);animation:hd-glow 1.4s ease-in-out infinite}
.hd-m.can:hover{transform:translateY(-2px)}
.hd-m-cards{display:flex}
.card.mini{--w:clamp(24px,6.6vw,34px);margin-right:calc(var(--w) * -.48)}
.card.mini:last-child{margin-right:0}
.hd-none{margin:0;opacity:.75;font-size:var(--fs-sm)}
.hd-stage{width:min(100%,440px);padding:10px;border-radius:16px;background:rgba(255,255,255,.96);color:var(--fg);direction:rtl;box-shadow:0 16px 30px -16px rgba(0,0,0,.6)}
.hd-stage-h{display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;font:700 var(--fs-sm) var(--f-display)}
.hd-stage-h b{display:flex;align-items:center;gap:5px}
.hd-stage-h svg{width:16px;height:16px}
.hd-stage-h span{color:var(--pome);font-weight:800}
.hd-stage-h span.ok{color:var(--mint)}
.hd-stage .hd-m{background:var(--surface-2)}
.hd-stage .row{margin-top:8px}
.ch.hd-hand{--cw:clamp(50px,14vw,80px)}
.cme-acts .btn.sm{min-height:34px}

/* ============================== the card table in perspective (طرنيب، تركس، هاند) ==============================
   A sitting room: patterned wallpaper, a wooden floor, a low table under a warm lamp with a red rug on it. The table
   is tilted back in 3D, so the cards played on the rug lie in perspective; the others sit round it as characters
   holding their cards up over their heads, with their names on ribbons; there's tea, and a paper with the score.
   Your hand curves along the bottom. The panels (bids, choices, results) float flat over the table, and the room
   grows to fit them. */
.ct3{--tilt:46deg;--sh:clamp(340px,56vh,500px);--back:linear-gradient(160deg,#6b45ff,#2a0f8a);position:relative;max-width:1060px;margin:0 auto;border-radius:30px;overflow:hidden;isolation:isolate;box-shadow:0 30px 60px -34px rgba(20,10,0,.8),0 0 0 1px rgba(0,0,0,.08);color:#fff;direction:rtl}
.ct3-stage{position:relative;display:grid;min-height:var(--sh)}
/* the room */
.ct3-room{position:absolute;inset:0;z-index:-1;background:
  linear-gradient(180deg,transparent 0 47%,#6e4122 47% 48.4%,#3b200c 48.4% 49%,transparent 49%),
  radial-gradient(130% 70% at 50% 100%,rgba(0,0,0,.5),transparent 70%),
  linear-gradient(180deg,transparent 0 49%,#8f5a33 49%,#62391b 100%),
  radial-gradient(circle at 14px 14px,rgba(255,222,150,.16) 0 2.2px,transparent 3px) 0 0/28px 28px,
  radial-gradient(circle at 0 0,rgba(255,222,150,.08) 0 5px,transparent 6px) 0 0/28px 28px,
  linear-gradient(180deg,#2a5d55,#1f4842 47%)}
.ct3-room::after{content:'';position:absolute;inset:49% 0 0;background:repeating-linear-gradient(90deg,rgba(0,0,0,.16) 0 2px,transparent 2px 92px),repeating-linear-gradient(180deg,rgba(255,255,255,.035) 0 1px,transparent 1px 18px)}
.ct3-lamp{position:absolute;inset:0;background:radial-gradient(60% 52% at 50% 26%,rgba(255,206,120,.42),transparent 72%)}
/* a framed picture on the wall: a view of Wadi Rum */
.ct3-frame{position:absolute;top:7%;left:50%;width:min(15%,120px);aspect-ratio:4/3;transform:translateX(-50%);border-radius:4px;background:radial-gradient(circle at 74% 30%,#fff3c4 0 7%,transparent 8%),linear-gradient(180deg,transparent 52%,#c7653a 52% 60%,#a54a28 60% 70%,#e7a76b 70%),radial-gradient(60% 80% at 22% 70%,#b4532c 0 50%,transparent 51%),linear-gradient(180deg,#ffb36b,#ff8f6b 60%);box-shadow:0 0 0 5px #b5823e,0 0 0 7px #6b4317,0 12px 20px -6px rgba(0,0,0,.5)}
/* the table, tilted back: wood, a rug on it, and a front edge you look at */
.ct3-tablewrap{grid-area:1/1;align-self:end;position:relative;margin:0 7% calc(var(--sh) * .085);perspective:1100px;perspective-origin:50% -20%}
/* the front edge of the table: a flat strip under its near side, outside the tilted plane (a face rotated inside a
   preserve-3d plane made phones lose the cards lying on the rug) */
.ct3-tablewrap::after{content:'';position:absolute;left:1.2%;right:1.2%;top:100%;height:calc(var(--sh) * .05);border-radius:0 0 40px 40px/0 0 26px 26px;background:linear-gradient(180deg,#6b3d1d,#3c210c);box-shadow:0 26px 34px -6px rgba(0,0,0,.55)}
.ct3-table{position:relative;display:flex;min-height:calc(var(--sh) * .72);transform:rotateX(var(--tilt));transform-origin:50% 100%;border-radius:38px;background:radial-gradient(120% 90% at 50% 40%,#b07444,#7b4723 70%,#5e3519);box-shadow:inset 0 0 0 4px #c48a55,inset 0 0 0 7px #5b331a,inset 0 2px 30px rgba(0,0,0,.3)}
.ct3-cloth{position:relative;flex:1;margin:4.2% 4.5%;border-radius:24px;display:grid;place-items:center;padding:10px;background:
  radial-gradient(ellipse at 50% 50%,rgba(255,214,140,.2) 0 14%,transparent 14.5%),
  radial-gradient(ellipse at 50% 50%,transparent 0 21%,rgba(255,214,140,.16) 21.5% 22.5%,transparent 23%),
  repeating-linear-gradient(45deg,rgba(255,214,140,.08) 0 2px,transparent 2px 26px),
  repeating-linear-gradient(-45deg,rgba(255,214,140,.08) 0 2px,transparent 2px 26px),
  radial-gradient(110% 100% at 50% 45%,#b53a33,#86231f 70%,#6a1a17);
  box-shadow:inset 0 0 0 6px #d9a441,inset 0 0 0 9px #86231f,inset 0 0 0 11px #ecc46c,inset 0 0 50px rgba(0,0,0,.4)}
.ct3-cloth::before{content:'';position:absolute;inset:16px;border-radius:16px;border:2px dashed rgba(255,214,140,.32);pointer-events:none}
/* the cards on the rug */
.ct3 .ctrick{--tw:clamp(56px,13vw,90px);width:min(100%,460px)}
.ct3-cloth .card{box-shadow:0 1px 0 rgba(0,0,0,.25),0 12px 16px -6px rgba(0,0,0,.6)}
.ct3 .ct-c.at-b{transform:translate(-50%,-2%) rotate(3deg)}
.ct3 .ct-c.at-t{transform:translate(-50%,-98%) rotate(-4deg)}
.ct3 .ct-c.at-l{transform:translate(-150%,-50%) rotate(-8deg)}
.ct3 .ct-c.at-r{transform:translate(50%,-50%) rotate(7deg)}
/* tea */
.ct3-pot{position:absolute;z-index:3;--s:clamp(46px,8.5vw,70px);right:3.5%;bottom:5%;filter:drop-shadow(0 10px 8px rgba(0,0,0,.5))}
.ct3-cup{position:absolute;z-index:3;--s:clamp(28px,5vw,42px);filter:drop-shadow(0 8px 6px rgba(0,0,0,.5))}
.ct3-cup.c1{right:12%;bottom:3.5%}
.ct3-cup.c2{left:21%;bottom:37%;--s:clamp(20px,3.4vw,30px)}
/* the others */
.ct3-seat{position:absolute;z-index:4;display:flex;flex-direction:column;align-items:center;text-align:center;pointer-events:none;width:clamp(96px,17vw,170px)}
.ct3-seat.at-t{left:50%;top:1.5%;transform:translateX(-50%)}
.ct3-seat.at-l{left:.5%;top:30%}
.ct3-seat.at-r{right:.5%;top:30%}
.ct3-seat.gone{opacity:.5;filter:grayscale(.8)}
.ct3-who{position:relative;display:grid;place-items:center;width:var(--fs);height:var(--fs);--fs:clamp(56px,11vw,96px)}
/* a body in the seat's colour under the face */
.ct3-who::before{content:'';position:absolute;z-index:-1;left:50%;bottom:-34%;width:118%;height:62%;transform:translateX(-50%);border-radius:48% 48% 18% 18%/70% 70% 18% 18%;background:radial-gradient(90% 70% at 50% 15%,color-mix(in srgb,var(--c) 65%,#fff),var(--c) 60%,color-mix(in srgb,var(--c) 70%,#000));box-shadow:0 10px 14px -6px rgba(0,0,0,.5)}
.ct3-face{--s:100%;position:relative;filter:drop-shadow(0 8px 8px rgba(0,0,0,.4))}
.ct3-ini{position:absolute;z-index:2;bottom:-4%;inset-inline-end:-12%;display:grid;place-items:center;width:clamp(20px,3.6vw,28px);height:clamp(20px,3.6vw,28px);border-radius:50%;background:var(--c);color:var(--on-c);font:800 clamp(.68rem,1.4vw,.9rem)/1 var(--f-display);box-shadow:0 0 0 2.5px #fff,0 4px 8px rgba(0,0,0,.4)}
.ct3-ini svg{width:62%;height:62%}
.ct3-glow{position:absolute;inset:-22%;z-index:-2;border-radius:50%;background:radial-gradient(circle,rgba(255,214,90,.85),rgba(255,214,90,0) 68%);animation:ct3-glow 1.3s ease-in-out infinite}
@keyframes ct3-glow{0%,100%{transform:scale(.88);opacity:.7}50%{transform:scale(1.1);opacity:1}}
/* the name on a ribbon */
.ct3-rib{position:relative;z-index:2;display:flex;align-items:center;justify-content:center;gap:4px;margin-top:2px;padding:3px 12px 4px;border-radius:6px;max-width:100%;background:linear-gradient(180deg,color-mix(in srgb,var(--c) 72%,#fff),var(--c) 55%);color:var(--on-c);box-shadow:0 3px 0 color-mix(in srgb,var(--c) 55%,#000),0 8px 14px -4px rgba(0,0,0,.55);font:800 clamp(.72rem,1.5vw,.92rem)/1.25 var(--f-display);white-space:nowrap}
.ct3-rib::before,.ct3-rib::after{content:'';position:absolute;z-index:-1;top:6px;width:12px;height:calc(100% - 2px);background:color-mix(in srgb,var(--c) 62%,#000)}
.ct3-rib::before{left:-8px;clip-path:polygon(0 0,100% 0,100% 100%,0 100%,45% 50%)}
.ct3-rib::after{right:-8px;clip-path:polygon(0 0,100% 0,55% 50%,100% 100%,0 100%)}
.ct3-rib b{overflow:hidden;text-overflow:ellipsis;min-width:0}
.ct3-rib .bg-tag{width:16px;height:16px;flex:none;background:rgba(255,255,255,.3);color:inherit}
.ct3-seat.on .ct3-rib,.ct3-mine.on .ct3-rib{background:linear-gradient(180deg,#ffe27a,#ffbf2e 60%);color:#3d2500;box-shadow:0 3px 0 #b07400,0 0 0 2px #fff6cf,0 0 22px rgba(255,210,63,.85)}
.ct3-seat.on .ct3-rib::before,.ct3-seat.on .ct3-rib::after,.ct3-mine.on .ct3-rib::before,.ct3-mine.on .ct3-rib::after{background:#c98a00}
.ct3-bd{display:flex;gap:3px;flex-wrap:wrap;justify-content:center;margin-top:5px;max-width:100%}
.ct3-bd .cbadge{background:rgba(20,8,0,.6);box-shadow:0 2px 6px rgba(0,0,0,.35);-webkit-backdrop-filter:blur(2px);backdrop-filter:blur(2px)}
.ct3-bd .cbadge.gold{background:#ffd23f;color:#3a2600}
.ct3-bd .cbadge.dark{background:rgba(20,8,0,.42)}
/* their cards, held up over their heads */
.ct3-fan{--cwf:clamp(20px,3.4vw,30px);position:relative;display:block;width:calc(var(--cwf) + var(--k) * 6px);height:calc(var(--cwf) * 1.4 + 6px);margin-bottom:calc(var(--cwf) * -.5)}
.ct3-fan i{position:absolute;left:50%;bottom:0;width:var(--cwf);aspect-ratio:5/7;margin-left:calc(var(--cwf) / -2);border-radius:4px;background:repeating-linear-gradient(45deg,rgba(255,255,255,.14) 0 1.5px,transparent 1.5px 5px),var(--back);box-shadow:0 0 0 1.5px #fff,0 3px 6px rgba(0,0,0,.4);transform-origin:50% 135%;transform:rotate(calc((var(--j) - (var(--k) - 1) / 2) * 10deg))}
.ct3-fan b{position:absolute;z-index:2;top:-4px;right:-8px;min-width:20px;height:20px;padding:0 5px;border-radius:999px;background:#fff;color:#21174d;font:800 .72rem/20px var(--f-display);box-shadow:0 2px 6px rgba(0,0,0,.35)}
/* the score paper, taped to the corner */
.ct3-note{position:absolute;z-index:5;top:3%;left:14.5%;min-width:124px;max-width:min(36%,210px);padding:9px 11px 9px;border-radius:3px;background:linear-gradient(180deg,#fffdf5,#f6edd6);color:#3b2a14;box-shadow:0 12px 20px -8px rgba(0,0,0,.6);transform:rotate(-3deg);font:700 .78rem/1.35 var(--f-display);direction:rtl}
.ct3-note::before{content:'';position:absolute;top:-8px;left:50%;width:48px;height:16px;margin-left:-24px;background:rgba(255,236,170,.78);transform:rotate(3deg);box-shadow:0 1px 2px rgba(0,0,0,.12)}
.ct3-note h4{display:flex;align-items:center;justify-content:center;gap:4px;margin:0 0 4px;padding-bottom:3px;border-bottom:1.5px dashed #c9a46a;font:800 .8rem/1.25 var(--f-display);color:#8a3d10;text-align:center}
.ct3-note h4 .ic{width:14px;height:14px}
.ct3-note h4 .em{--s:16px}
.ct3-note table{width:100%;border-collapse:collapse}
