.ct3-hint .em{--s:20px}
.ct3-me .ch{--cw:clamp(60px,9.2vw,98px);--dy:.55px;padding-top:calc(var(--m) * var(--dy) + 24px);min-height:calc(var(--cw) * 1.4 + var(--m) * var(--dy) + 28px);max-width:min(100%,860px)}
.ct3-me .ch-slot{transform-origin:50% 160%;transform:translateY(calc((var(--d) * var(--d) - var(--m)) * var(--dy))) rotate(calc(var(--d) * var(--da) * var(--dk,1)))}
.ct3-me .ch:empty{min-height:0;padding:0}
