.ct3-me .ch.live button.ch-slot>.card{box-shadow:inset 0 0 0 1px rgba(33,23,77,.14),0 0 0 2px rgba(255,210,63,.9),0 10px 18px -8px rgba(0,0,0,.75)}
.ct3-me .ch-slot>.card.dim{filter:brightness(.62) saturate(.6)}
.ct3-me .cme-acts .btn.ghost{background:rgba(255,255,255,.9);color:#2a1a08}
