@media (prefers-reduced-motion:reduce){.ct3-glow{animation:none}}
/* arranging your hand: the card you hold follows your finger, its place waits faded in the hand */
.ch[data-hand]>.ch-slot{touch-action:none}
.ch-slot.ghosted>.card{opacity:.22;filter:grayscale(.4)}
.ch.dragging .ch-slot>.card{transition:none}
.card.ch-ghost{position:fixed;left:0;top:0;z-index:9999;margin:0;pointer-events:none;transition:none;transform:translate(var(--x),var(--y)) rotate(-4deg) scale(1.08);box-shadow:inset 0 0 0 1px rgba(33,23,77,.14),0 22px 34px -10px rgba(0,0,0,.65)}
.card.ch-ghost.lift{transform:translate(var(--x),var(--y)) rotate(0deg) scale(1.16)}
.card.ch-ghost.up{box-shadow:0 0 0 4px #ffd23f,0 0 34px rgba(255,210,63,.85),0 22px 34px -10px rgba(0,0,0,.65)}
