/* the turn clock: a ring round whoever's turn it is that empties, gold turning red at the end, and a bar over your hand */
.ct3-clock{position:absolute;z-index:3;left:-14%;top:-14%;width:128%;height:128%;transform:rotate(-90deg);pointer-events:none;overflow:visible}
.ct3-clock circle{fill:none;stroke:#ffd23f;stroke-width:7;stroke-linecap:round;stroke-dasharray:100;stroke-dashoffset:0;filter:drop-shadow(0 0 4px rgba(255,210,63,.75));animation:ct3-clock var(--dur) linear var(--del) forwards,ct3-clock-c var(--dur) linear var(--del) forwards}
@keyframes ct3-clock{to{stroke-dashoffset:100}}
@keyframes ct3-clock-c{0%,72%{stroke:#ffd23f}86%,100%{stroke:#ff3b5c}}
.ct3-tbar{position:absolute;z-index:8;left:0;right:0;top:0;height:5px;background:#ffd23f;transform-origin:right center;animation:ct3-tbar var(--dur) linear var(--del) forwards,ct3-tbar-c var(--dur) linear var(--del) forwards}
@keyframes ct3-tbar{to{transform:scaleX(0)}}
@keyframes ct3-tbar-c{0%,72%{background:#ffd23f}86%,100%{background:#ff3b5c}}
