/* ============================== وحدة! ==============================
   Its own cards: a colour with a soft shine and fine stripes, a white disc in the middle with the number or the
   symbol, and the small mark in two corners; the wilds are dark with a four-colour wheel. */
:root{--un-r:#e8283f;--un-y:#f2ab00;--un-g:#0fa564;--un-b:#1a72dc;--un-w:#2a1d4d}
.uc-r{--k:var(--un-r)}.uc-y{--k:var(--un-y)}.uc-g{--k:var(--un-g)}.uc-b{--k:var(--un-b)}.uc-w{--k:var(--un-w)}
.card.uc{background:radial-gradient(120% 90% at 30% 12%,color-mix(in srgb,var(--k) 68%,#fff),var(--k) 52%,color-mix(in srgb,var(--k) 74%,#000));color:#fff;box-shadow:inset 0 0 0 calc(var(--w) * .05) #fff,inset 0 0 0 calc(var(--w) * .066) rgba(0,0,0,.14),0 1px 1px rgba(33,23,77,.1),0 8px 16px -10px rgba(20,12,60,.7)}
.card.uc::before{content:'';position:absolute;inset:0;border-radius:inherit;background:repeating-linear-gradient(135deg,rgba(255,255,255,.09) 0 calc(var(--w) * .035),transparent calc(var(--w) * .035) calc(var(--w) * .11));pointer-events:none}
.card.uc .ui{position:absolute;z-index:1;left:10%;top:6%;font:800 calc(var(--w) * .23)/1 var(--f-display);letter-spacing:-.04em;text-shadow:0 1px 0 rgba(0,0,0,.28)}
.card.uc .ui svg{display:block;width:calc(var(--w) * .22);height:calc(var(--w) * .22)}
.card.uc .ui2{left:auto;top:auto;right:10%;bottom:6%;transform:rotate(180deg)}
.card.uc .um{position:absolute;inset:0;display:grid;place-items:center}
.card.uc .um>b{display:grid;place-items:center;width:60%;aspect-ratio:1;border-radius:50%;background:#fff;color:var(--k);font:800 calc(var(--w) * .46)/1 var(--f-display);letter-spacing:-.04em;box-shadow:0 calc(var(--w) * .03) 0 rgba(0,0,0,.2),inset 0 calc(var(--w) * -.035) 0 rgba(0,0,0,.08)}
.card.uc .um>b.two{font-size:calc(var(--w) * .32)}
.card.uc .um>b.ico svg{width:64%;height:64%}
.card.uc-w .upw{display:grid;grid-template-columns:1fr 1fr;width:62%;aspect-ratio:1;border-radius:50%;overflow:hidden;transform:rotate(45deg);box-shadow:0 0 0 calc(var(--w) * .04) #fff,0 4px 10px rgba(0,0,0,.4)}
.card.uc-w .upw i{background:var(--k)}
.card.uc-w .u4{position:absolute;font:800 calc(var(--w) * .3)/1 var(--f-display);color:#fff;text-shadow:0 2px 0 rgba(0,0,0,.45),0 0 6px rgba(0,0,0,.6)}
.card.uc.dim{filter:brightness(.6) saturate(.55)}
/* the middle of the rug: the stock, the pile glowing in the colour asked for, the direction of play */
.ct3.un{--uw:clamp(58px,8.4vw,86px)}
.un-mid{position:relative;display:flex;align-items:center;justify-content:center;gap:clamp(26px,6vw,70px);padding:clamp(14px,2.4vw,26px) clamp(26px,5vw,60px)}
.un-dir{position:absolute;inset:-4% 0;border-radius:50%;border:3px dashed color-mix(in srgb,var(--uc) 55%,#fff);opacity:.7;animation:un-spin 10s linear infinite;pointer-events:none}
.un-dir.ccw{animation-direction:reverse}
.un-dir::before,.un-dir::after{content:'';position:absolute;left:50%;width:0;height:0;margin-left:-9px;border:9px solid transparent}
.un-dir::before{top:-11px;border-left:14px solid color-mix(in srgb,var(--uc) 55%,#fff);border-right:0}
.un-dir::after{bottom:-11px;border-right:14px solid color-mix(in srgb,var(--uc) 55%,#fff);border-left:0}
.un-dir.ccw::before{border-left:0;border-right:14px solid color-mix(in srgb,var(--uc) 55%,#fff)}
.un-dir.ccw::after{border-right:0;border-left:14px solid color-mix(in srgb,var(--uc) 55%,#fff)}
@keyframes un-spin{to{transform:rotate(360deg)}}
.un-deck{position:relative;z-index:1;display:inline-grid;place-items:center;border:0;background:none;padding:0;font:inherit;color:inherit}
.un-stack{position:relative;display:block;width:var(--uw);height:calc(var(--uw) * 1.4)}
.un-stack .card{--w:var(--uw);position:absolute;left:0;top:0}
.un-stack .card:nth-child(1){transform:translate(5px,5px)}
.un-stack .card:nth-child(2){transform:translate(2.5px,2.5px)}
.un-deck>b{position:absolute;bottom:-9px;right:-12px;min-width:26px;height:24px;padding:0 6px;border-radius:999px;background:#fff;color:#21174d;font:800 .78rem/24px var(--f-display);box-shadow:0 2px 6px rgba(0,0,0,.35)}
button.un-deck{cursor:pointer}
button.un-deck .un-stack .card:last-child{box-shadow:0 0 0 3px #ffd23f,0 10px 20px -8px rgba(0,0,0,.6)}
button.un-deck.hot .un-stack .card:last-child{animation:hd-glow 1.4s ease-in-out infinite}
button.un-deck:hover .un-stack .card:last-child{transform:translateY(-5px)}
.un-pile{position:relative;z-index:1;width:var(--uw);height:calc(var(--uw) * 1.4)}
.un-pile::before{content:'';position:absolute;inset:-14px;border-radius:22px;box-shadow:0 0 0 4px var(--uc),0 0 34px 8px var(--uc);opacity:.7;transition:box-shadow .3s}
.un-pile .card{--w:var(--uw);position:absolute;left:0;top:0;transform:rotate(var(--r))}
.un-pile .card.under{filter:brightness(.9)}
.un-pile .card.top{box-shadow:inset 0 0 0 calc(var(--w) * .05) #fff,0 14px 20px -8px rgba(0,0,0,.65)}
.un-pile .card.top.in.from-b{animation:un-in-b .38s cubic-bezier(.2,1,.4,1)}
.un-pile .card.top.in.from-t{animation:un-in-t .38s cubic-bezier(.2,1,.4,1)}
.un-pile .card.top.in.from-l{animation:un-in-l .38s cubic-bezier(.2,1,.4,1)}
.un-pile .card.top.in.from-r{animation:un-in-r .38s cubic-bezier(.2,1,.4,1)}
@keyframes un-in-b{from{transform:translate(-40%,170%) scale(1.25);opacity:0}}
@keyframes un-in-t{from{transform:translate(30%,-190%) scale(.8);opacity:0}}
@keyframes un-in-l{from{transform:translate(-280%,-30%) rotate(-40deg);opacity:0}}
@keyframes un-in-r{from{transform:translate(280%,-30%) rotate(40deg);opacity:0}}
.un-pen{--glow2:0 0 0 3px #fff,0 0 22px rgba(255,45,85,.9);position:absolute;z-index:2;top:6%;right:6%;padding:3px 12px;border-radius:999px;background:#ff2d55;color:#fff;font:800 1.25rem/1.3 var(--f-display);box-shadow:0 0 0 3px #fff,0 8px 16px -6px rgba(0,0,0,.6);animation:un-pulse 1s ease-in-out infinite}
/* colours */
.un-sw{display:inline-block;width:36px;height:36px;border-radius:50%;background:var(--k);box-shadow:inset 0 -3px 0 rgba(0,0,0,.2),0 0 0 3px #fff,0 4px 10px rgba(0,0,0,.25)}
.ct3-note .ic.un-ccw,.ct3-note .ic.un-cw{width:14px;height:14px;vertical-align:-2px}
.ic.un-cw{transform:scaleX(-1)}
.un-sw.sm{width:12px;height:12px;vertical-align:-1px;box-shadow:0 0 0 1.5px #fff,0 1px 3px rgba(0,0,0,.3)}
.un-pickc .cgrid{margin-bottom:10px}
.un-pickc .cbtn{min-height:78px;gap:6px}
/* the shout, and catching someone who forgot it */
.btn.un-uno{--glow2:0 4px 0 #b07400,0 0 0 3px #fff,0 0 36px rgba(255,200,40,1);background:linear-gradient(180deg,#ffe066,#ffb703);color:#3d2500;font:800 1.08rem var(--f-display);border:0;box-shadow:0 4px 0 #b07400,0 0 0 3px #fff,0 0 24px rgba(255,200,40,.85);animation:un-pulse 1s ease-in-out infinite}
.btn.un-catch{--glow2:0 4px 0 #9c1426,0 0 0 3px #fff,0 0 34px rgba(232,40,63,1);background:linear-gradient(180deg,#ff6b81,#e8283f);color:#fff;border:0;box-shadow:0 4px 0 #9c1426,0 0 0 3px #fff,0 0 22px rgba(232,40,63,.7);animation:un-pulse .8s ease-in-out infinite}
@keyframes un-pulse{50%{filter:brightness(1.12) saturate(1.15);box-shadow:var(--glow2,0 0 0 3px #fff,0 0 34px rgba(255,200,40,1))}}
.cbadge.un-forgot{--glow2:0 0 16px rgba(232,40,63,.95);background:#e8283f;color:#fff;animation:un-pulse .8s ease-in-out infinite}
.cmsg.un-hot{background:rgba(150,10,40,.78)}
.ct3.un .ct3-me .ch{--cw:clamp(58px,8.6vw,92px)}
@media (max-width:620px){
  .ct3.un{--uw:clamp(46px,13.5vw,58px)}
  .un-mid{gap:28px;padding:12px 26px}
  .un-pen{font-size:1rem;padding:2px 9px}
