@media (prefers-reduced-motion:reduce){.un-dir,.un-pen,.btn.un-uno,.btn.un-catch,.cbadge.un-forgot,.un-pile .card.top.in{animation:none!important}}
/* messages over the table sit low on the rug and never block the stock or the pile */
.ct3.un .ct3-over:has(> .cmsg:only-child){place-self:end center;margin:0 0 calc(var(--sh) * .05)}

/* ============================== دومينو، طاولة الزهر، أربعمية ============================== */

/* ---------------- domino tiles ---------------- */
.dm-t{--u:clamp(15px,4.3vw,34px);--ivory:#fffaf0;display:inline-flex;flex:none;position:relative;border-radius:calc(var(--u) * .22);background:linear-gradient(160deg,#fff,var(--ivory) 55%,#efe2c8);box-shadow:inset 0 0 0 1px rgba(80,50,20,.25),inset 0 -2px 0 rgba(120,80,30,.25),0 3px 5px -1px rgba(0,0,0,.45);vertical-align:middle}
.dm-t.v{flex-direction:column}
.dm-h{display:grid;grid-template:repeat(3,1fr)/repeat(3,1fr);place-items:center;width:var(--u);height:var(--u);padding:calc(var(--u) * .14);box-sizing:border-box}
.dm-t:not(.v) .dm-h+.dm-h{box-shadow:inset 1px 0 0 rgba(80,50,20,.35)}
.dm-t.v .dm-h+.dm-h{box-shadow:inset 0 1px 0 rgba(80,50,20,.35)}
.dm-h b{width:calc(var(--u) * .2);height:calc(var(--u) * .2);border-radius:50%;background:radial-gradient(circle at 35% 30%,#5b4a8a,#1a1238 70%)}
.dm-t.mini{--u:10px;border-radius:2px;box-shadow:inset 0 0 0 1px rgba(80,50,20,.3)}
.dm-t.mini .dm-h{padding:1px}
.dm-t.mini .dm-h b{width:2.6px;height:2.6px}
.dm-t.back{background:repeating-linear-gradient(45deg,rgba(255,255,255,.14) 0 2px,transparent 2px 6px),linear-gradient(160deg,#6b45ff,#2a0f8a)}
.dm-t.back .dm-h b{display:none}
.dm-t.back .dm-h+.dm-h{box-shadow:inset 0 1px 0 rgba(255,255,255,.3)}
.cbadge .dm-t{vertical-align:-2px}
/* the line on the rug */
.dm-line{display:flex;flex-direction:column;align-items:stretch;gap:4px;width:min(100%,calc(12 * clamp(15px,4.3vw,34px) + 24px));margin:0 auto}
.dm-row{display:flex;align-items:center;gap:1px;min-height:calc(2 * clamp(15px,4.3vw,34px))}
.dm-row.rev{flex-direction:row-reverse}
.dm-line .dm-t.end{box-shadow:inset 0 0 0 1px rgba(80,50,20,.25),0 0 0 2px #ffd23f,0 0 14px rgba(255,210,63,.75)}
.dm-gh{display:grid;place-items:center;flex:none;width:calc(2 * clamp(15px,4.3vw,34px));height:clamp(15px,4.3vw,34px);padding:0;border-radius:6px;border:2px dashed #ffe9a8;background:rgba(255,233,168,.22);color:#fff3cf;font:800 .72rem/1 var(--f-display);cursor:pointer;animation:dm-gh 1s ease-in-out infinite}
@keyframes dm-gh{50%{background:rgba(255,233,168,.45)}}
.dm-none{margin:0;padding:8px 14px;border-radius:999px;background:rgba(0,0,0,.28);font:700 var(--fs-sm)/1.5 var(--f-display);direction:rtl}
.dm-bone{position:absolute;top:10px;left:12px;display:flex;align-items:center;gap:4px;padding:4px 8px 4px 6px;border-radius:12px;background:rgba(20,8,0,.45);font:800 .8rem/1 var(--f-display);direction:ltr}
.dm-bone .dm-t{--u:12px}
/* your tiles */
.dm-hand{display:flex;justify-content:center;flex-wrap:wrap;gap:6px;padding:8px 6px 4px;max-width:100%}
.dm-hb{display:inline-grid;place-items:center;padding:0;border:0;background:none;border-radius:9px;transition:transform .15s,filter .15s,opacity .15s}
.dm-hb .dm-t{--u:clamp(20px,6vw,34px)}
.dm-hand.live .dm-hb.off{opacity:.6;filter:saturate(.5) brightness(.92)}
.dm-hb.can{cursor:pointer}
.dm-hb.can .dm-t{box-shadow:inset 0 0 0 1px rgba(80,50,20,.25),0 0 0 2px #ffd23f,0 8px 14px -4px rgba(0,0,0,.55)}
.dm-hb.can:hover{transform:translateY(-6px)}
.dm-hb.sel{transform:translateY(-12px)}
.dm-hb.sel .dm-t{box-shadow:0 0 0 3px #fff,0 0 0 6px #ffb703,0 12px 18px -4px rgba(0,0,0,.6)}
.ct3.dm .ct3-cloth{padding:22px 10px 14px}
.bg-hero .dm-art{display:flex;gap:10px;transform:rotate(-10deg)}
.bg-hero .dm-art .dm-t{--u:40px}
.bg-hero .dm-art .dm-t+.dm-t{transform:translateY(18px) rotate(14deg)}
@media (prefers-reduced-motion:reduce){.dm-gh{animation:none}}

/* ---------------- backgammon ---------------- */
.tw-wrap{--pw:clamp(22px,min(6.2vw,calc((100dvh - 300px) / 11.6)),52px);display:flex;flex-direction:column;align-items:center;gap:10px;padding:0 8px 18px;max-width:900px;margin:0 auto}
.tw-side{display:flex;align-items:center;justify-content:space-between;gap:10px;width:min(100%,calc(12 * var(--pw) + 100px))}
.tw-who{display:flex;align-items:center;gap:8px;padding:5px 12px 5px 6px;border-radius:999px;background:var(--surface);box-shadow:var(--shadow);font:700 var(--fs-sm)/1.2 var(--f-display);border:2px solid transparent;min-width:0}
.tw-who.on{border-color:var(--c);box-shadow:0 0 0 3px color-mix(in srgb,var(--c) 30%,transparent),var(--shadow)}
.tw-who b{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.tw-who em{font-style:normal;color:var(--fg-3);font-weight:600}
.tw-who span{color:var(--fg-3);font:600 var(--fs-xs)/1.2 var(--f-body);white-space:nowrap}
.tw-who .tw-ck{width:22px;flex:none}
.tw-board{position:relative;display:grid;grid-template-columns:auto calc(var(--pw) * .9) auto calc(var(--pw) * 1.05);gap:0;padding:8px;border-radius:18px;background:linear-gradient(160deg,#7a4524,#4d2810);box-shadow:inset 0 0 0 2px #a8683b,0 24px 40px -22px rgba(30,10,0,.8);isolation:isolate}
.tw-half{display:grid;grid-template-rows:auto 1fr auto;width:calc(6 * var(--pw));background:radial-gradient(120% 90% at 50% 50%,#2f7a5e,#1d5a44 70%,#174a38);box-shadow:inset 0 0 0 2px rgba(0,0,0,.25),inset 0 0 26px rgba(0,0,0,.35)}
.tw-half:first-child{border-radius:10px 0 0 10px}
.tw-half:nth-child(3){border-radius:0 10px 10px 0}
.tw-row{display:grid;grid-template-columns:repeat(6,var(--pw))}
.tw-mid{display:flex;align-items:center;justify-content:center;gap:8px;min-height:calc(var(--pw) * 1.5);padding:4px}
.tw-pt{position:relative;isolation:isolate;display:flex;flex-direction:column;align-items:center;height:calc(var(--pw) * 5.3);padding:3px 0;border:0;background:none;margin:0;font:inherit;color:inherit}
.tw-pt.bot{flex-direction:column-reverse}
.tw-pt::before{content:'';position:absolute;z-index:-1;left:6%;right:6%;top:0;bottom:8%;clip-path:polygon(0 0,100% 0,50% 100%);background:linear-gradient(180deg,var(--tri),color-mix(in srgb,var(--tri) 75%,#000))}
.tw-pt.bot::before{top:8%;bottom:0;clip-path:polygon(50% 0,100% 100%,0 100%);background:linear-gradient(0deg,var(--tri),color-mix(in srgb,var(--tri) 75%,#000))}
.tw-pt.a{--tri:#f1dcb4}
.tw-pt.b{--tri:#c2492f}
.tw-n{position:absolute;left:50%;transform:translateX(-50%);font:700 .56rem/1 var(--f-body);color:rgba(255,255,255,.45);pointer-events:none}
.tw-pt.top .tw-n{bottom:-1px}
.tw-pt.bot .tw-n{top:-1px}
button.tw-pt{cursor:pointer}
.tw-pt.src::after,.tw-pt.dst::after{content:'';position:absolute;inset:0 4%;border-radius:8px;pointer-events:none}
.tw-pt.src::after{box-shadow:inset 0 0 0 2px rgba(255,210,63,.85);background:rgba(255,210,63,.08)}
.tw-pt.on::after{content:'';position:absolute;inset:0 4%;border-radius:8px;box-shadow:inset 0 0 0 3px #fff,0 0 16px rgba(255,255,255,.6)}
.tw-pt.dst::after{background:linear-gradient(var(--dd,180deg),rgba(255,233,120,.5),rgba(255,233,120,0) 70%);box-shadow:inset 0 0 0 2px rgba(255,233,120,.9);animation:tw-dst 1s ease-in-out infinite}
.tw-pt.bot.dst::after{--dd:0deg}
@keyframes tw-dst{50%{opacity:.55}}
.tw-ck{position:relative;display:grid;place-items:center;flex:none;width:calc(var(--pw) * .9);aspect-ratio:1;margin:-1px 0;border-radius:50%;font-style:normal}
.tw-ck.w{background:radial-gradient(circle at 38% 32%,#fff,#efe6d6 55%,#cdbfa6);box-shadow:inset 0 0 0 2px #fff,inset 0 0 0 calc(var(--pw) * .1) #e3d6bd,0 2px 3px rgba(0,0,0,.45)}
.tw-ck.k{background:radial-gradient(circle at 38% 32%,#6a4a3a,#3a2318 55%,#1f120b);box-shadow:inset 0 0 0 2px #7d5847,inset 0 0 0 calc(var(--pw) * .1) #2b1a12,0 2px 3px rgba(0,0,0,.5)}
.tw-ck b{font:800 calc(var(--pw) * .38)/1 var(--f-display)}
.tw-ck.w b{color:#3a2318}
.tw-ck.k b{color:#f6ead6}
.tw-ck.new{animation:tw-land .35s cubic-bezier(.2,1.5,.4,1)}
@keyframes tw-land{from{transform:scale(1.35)}}
.tw-bar{display:flex;flex-direction:column;justify-content:space-between;align-items:center;padding:6px 0;background:linear-gradient(90deg,#4d2810,#6b3a1a,#4d2810);box-shadow:inset 0 0 6px rgba(0,0,0,.5)}
.tw-bar-them,.tw-bar-me{display:flex;flex-direction:column;align-items:center;gap:0;min-height:calc(var(--pw) * 2);padding:2px;border:0;border-radius:10px;background:none}
.tw-bar-me{flex-direction:column-reverse}
.tw-bar .tw-ck{width:calc(var(--pw) * .8)}
button.tw-bar-me{cursor:pointer}
.tw-bar-me.src{box-shadow:inset 0 0 0 2px rgba(255,210,63,.9)}
.tw-bar-me.on{box-shadow:inset 0 0 0 3px #fff}
.tw-trays{display:flex;flex-direction:column;justify-content:space-between;gap:8px;padding:0 0 0 6px}
.tw-tray{position:relative;display:flex;flex-direction:column-reverse;align-items:center;gap:1px;height:calc(var(--pw) * 5.3);padding:4px 3px;border:0;border-radius:8px;background:linear-gradient(90deg,#3a1e0b,#5a3216);box-shadow:inset 0 0 8px rgba(0,0,0,.6)}
.tw-trays .tw-tray:first-child{flex-direction:column}
.tw-off{display:block;width:100%;height:calc(var(--pw) * .2);border-radius:3px;flex:none}
.tw-off.w{background:linear-gradient(180deg,#fff,#d8cbb2)}
.tw-off.k{background:linear-gradient(180deg,#6a4a3a,#24150d)}
.tw-tray b{position:absolute;left:50%;transform:translateX(-50%);bottom:-2px;font:800 .7rem/1 var(--f-display);color:#ffe7b8;text-shadow:0 1px 2px #000}
.tw-trays .tw-tray:first-child b{bottom:auto;top:-2px}
button.tw-tray{cursor:pointer}
.tw-tray.dst{box-shadow:inset 0 0 0 3px #ffe978,0 0 18px rgba(255,233,120,.6);animation:tw-dst 1s ease-in-out infinite}
.tw-dice{display:flex;align-items:center;gap:8px}
.tw-dice .die{width:calc(var(--pw) * 1.15);height:calc(var(--pw) * 1.15);padding:calc(var(--pw) * .17);gap:2px;border-radius:calc(var(--pw) * .28)}
.tw-dice .die.used{opacity:.32;filter:grayscale(1)}
.tw-dbl{font:800 var(--fs-sm)/1 var(--f-display);color:#ffe7b8}
.tw-roll{white-space:nowrap}
.tw-msg{margin:0;padding:6px 12px;border-radius:999px;background:rgba(0,0,0,.35);color:#fff;font:700 var(--fs-xs)/1.4 var(--f-display);text-align:center;direction:rtl}
.tw-undo{flex:none}
.tw-hint{margin:0;font:700 var(--fs-sm)/1.4 var(--f-display);color:var(--fg-2);text-align:center}
.tw-sum{position:absolute;inset:50% auto auto 50%;z-index:5;transform:translate(-50%,-50%);width:min(88%,340px);padding:16px;border-radius:20px;background:rgba(255,255,255,.97);color:var(--fg);text-align:center;direction:rtl;box-shadow:0 24px 50px -16px rgba(0,0,0,.75)}
.tw-sum h3{margin:0 0 6px;font:800 1.25rem/1.3 var(--f-display)}
.tw-sum p{margin:0 0 12px;color:var(--fg-2);font-size:var(--fs-sm)}
@media (max-width:520px){.tw-mid .tw-roll{padding:.5em .8em;font-size:.88rem}.tw-who{padding:4px 10px 4px 5px}.tw-wrap{padding:0 4px 14px}.tw-board{padding:5px}}
@media (prefers-reduced-motion:reduce){.tw-pt.dst::after,.tw-tray.dst,.tw-ck.new{animation:none}}

/* ---------------- مين المجرم؟ ---------------- */
.my-wrap{display:flex;flex-direction:column;gap:12px;max-width:1100px;margin:0 auto;padding:0 12px 24px}
.my-case{display:flex;flex-direction:column;gap:8px;padding:14px 16px;border-radius:var(--r-lg);color:#fff;background:radial-gradient(120% 140% at 100% 0%,rgba(255,255,255,.16),transparent 55%),linear-gradient(135deg,#3b1d8f,#1d0f4f);box-shadow:var(--shadow)}
.my-case-h{display:flex;align-items:center;gap:12px}
.my-case-h .eyebrow{margin:0;color:rgba(255,255,255,.72);font-size:var(--fs-xs)}
.my-case h2{margin:0;font:800 1.25rem/1.25 var(--f-display);color:#fff}
.my-case>p{margin:0;font-size:var(--fs-sm);line-height:1.6;color:rgba(255,255,255,.92)}
.my3-host{position:relative;height:clamp(300px,52vh,540px);border-radius:var(--r-lg);overflow:hidden;background:linear-gradient(180deg,#d9ccff,#fff1e3);box-shadow:var(--shadow)}
.my-room{position:relative;height:clamp(220px,40vh,360px);border-radius:var(--r-lg);overflow:hidden;box-shadow:var(--shadow);background:linear-gradient(180deg,#f6e3c3 0 46%,#8a4b23 46% 47.5%,#e1c49b 47.5%);}
.my-room.my-wedding{background:linear-gradient(180deg,#fbeef6 0 46%,#b0577f 46% 47.5%,#ead6ea 47.5%)}
.my-room.my-school{background:linear-gradient(180deg,#eaf0dc 0 46%,#5d6b45 46% 47.5%,#c6d1ba 47.5%)}
.my-room.my-office{background:linear-gradient(180deg,#eef1f7 0 46%,#4b5873 46% 47.5%,#c6cedd 47.5%)}
.my-room.my-grandpa{background:linear-gradient(180deg,#f3e6d0 0 46%,#6b3e1e 46% 47.5%,#be8f60 47.5%)}
.my-pin{position:absolute;left:var(--x);top:var(--y);transform:translate(-50%,-50%);display:grid;place-items:center;width:58px;height:58px;padding:0;border-radius:50%;border:4px solid #ffb703;background:#fff;box-shadow:0 8px 16px -6px rgba(0,0,0,.45);font:inherit}
.my-pin b{position:absolute;top:-8px;right:-8px;display:grid;place-items:center;min-width:24px;height:24px;border-radius:12px;background:#ffb703;color:#3a2500;font:800 .8rem/1 var(--f-display)}
.my-pin.can{cursor:pointer;animation:my-pin 1.2s ease-in-out infinite}
.my-pin.seen{border-color:#12b76a}
.my-pin.seen b{background:#12b76a;color:#fff}
@keyframes my-pin{50%{transform:translate(-50%,-50%) scale(1.1)}}
.my-turn{margin:0;text-align:center;font:700 var(--fs-md)/1.4 var(--f-display);color:var(--fg-2)}
.my-turn.me{color:var(--grape);font-size:1.08rem}
.my-scores{display:flex;flex-wrap:wrap;justify-content:center;gap:6px}
.my-scores span{display:inline-flex;align-items:center;gap:6px;padding:4px 12px;border-radius:999px;background:var(--surface);box-shadow:var(--shadow);font:700 var(--fs-sm)/1.2 var(--f-display);border:2px solid transparent}
.my-scores span.on{border-color:var(--c)}
.my-scores span.out{opacity:.5;text-decoration:line-through}
.my-scores b{color:var(--c)}
.my-cols{display:grid;gap:12px;grid-template-columns:minmax(0,1fr)}
@media (min-width:900px){.my-cols{grid-template-columns:minmax(0,1fr) minmax(0,1.15fr)}}
.my-panel{gap:10px;padding:14px}
.my-clues,.my-suss{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:8px}
.my-clue{display:grid;grid-template-columns:auto auto minmax(0,1fr) auto;align-items:center;gap:10px;padding:10px 12px;border-radius:16px;background:var(--surface-2);border:2px solid transparent;transition:border-color .2s,background .2s}
.my-clue.seen{background:color-mix(in srgb,var(--mint) 12%,var(--surface));border-color:color-mix(in srgb,var(--mint) 40%,transparent)}
.my-clue.herring{opacity:.7}
.my-clue b{font:800 var(--fs-sm)/1.3 var(--f-display)}
.my-clue p{margin:2px 0 0;font-size:var(--fs-sm);line-height:1.55}
.my-num{display:grid;place-items:center;width:26px;height:26px;border-radius:50%;background:#ffb703;color:#3a2500;font:800 .8rem/1 var(--f-display)}
.my-clue.seen .my-num{background:var(--mint);color:#fff}
.my-lock{color:var(--fg-3)}
.my-lock svg{width:18px;height:18px}
.my-tag{display:inline-block;margin-top:4px;padding:1px 8px;border-radius:999px;background:var(--surface-3);font:700 var(--fs-xs)/1.5 var(--f-display);color:var(--fg-2)}
.my-tag.bad{background:color-mix(in srgb,var(--bad) 16%,var(--surface));color:var(--bad)}
.flash{animation:my-flash 1.2s ease}
@keyframes my-flash{0%,60%{box-shadow:0 0 0 4px #ffb703,0 0 24px rgba(255,183,3,.6)}100%{box-shadow:none}}
.my-sus{display:grid;grid-template-columns:auto minmax(0,1fr) auto;align-items:center;gap:10px;padding:10px;border-radius:16px;background:var(--surface-2);border:2px solid transparent;border-inline-start:6px solid var(--c);transition:opacity .2s,filter .2s}
.my-sus.off{opacity:.5;filter:grayscale(.7)}
.my-sus.clear{opacity:.55}
.my-sus.culprit{background:color-mix(in srgb,var(--bad) 12%,var(--surface));border-color:var(--bad);box-shadow:0 0 0 3px color-mix(in srgb,var(--bad) 25%,transparent)}
.my-sus-face{position:relative;display:grid;place-items:center;width:56px;height:56px;padding:0;border:0;border-radius:50%;background:var(--surface);box-shadow:inset 0 0 0 3px var(--c);cursor:pointer}
.my-x{position:absolute;inset:0;display:grid;place-items:center;border-radius:50%;background:rgba(240,56,79,.55);color:#fff}
.my-x svg{width:34px;height:34px}
.my-crown{position:absolute;top:-10px;right:-8px}
.my-sus-b{display:flex;flex-direction:column;gap:2px;min-width:0}
.my-sus-b>b{font:800 var(--fs-md)/1.2 var(--f-display)}
.my-attrs{display:flex;flex-wrap:wrap;gap:4px;margin-top:4px}
.my-attrs span{display:inline-flex;align-items:center;gap:4px;padding:1px 8px;border-radius:999px;background:var(--surface);font:600 var(--fs-xs)/1.6 var(--f-body);white-space:nowrap}
.my-dot{display:inline-block;width:10px;height:10px;border-radius:50%;box-shadow:inset 0 0 0 1px rgba(0,0,0,.2)}
.my-acc{white-space:nowrap}
.my-end{scroll-margin-top:130px;display:flex;flex-direction:column;gap:8px;padding:16px;border-radius:var(--r-lg);background:var(--surface);border:3px solid var(--bad);box-shadow:var(--shadow)}
.my-end h3{margin:0;font:800 1.3rem/1.3 var(--f-display);color:var(--bad)}
.my-end h4{display:flex;align-items:center;gap:6px;margin:6px 0 0;font:800 var(--fs-md)/1.3 var(--f-display)}
.my-end h4 svg{width:18px;height:18px}
.my-end>p{margin:0}
.my-pts{font:800 var(--fs-md)/1.4 var(--f-display);color:var(--grape)}
.my-chain{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:6px}
.my-chain li{display:flex;align-items:center;gap:8px;font-size:var(--fs-sm)}
.my-out{color:var(--bad)}
.bg-sc svg{width:13px;height:13px;vertical-align:-2px}
@media (max-width:520px){.my-sus{grid-template-columns:auto minmax(0,1fr);}.my-acc{grid-column:1/-1}.my-pin{width:48px;height:48px}}
@media (prefers-reduced-motion:reduce){.my-pin.can,.flash{animation:none}}

/* ============================== عقارات الأردن ============================== */
.es-wrap{padding:2px 8px 22px}
.es-board{position:relative;width:min(100%,calc(100vh - 225px),860px);min-width:min(100%,320px);aspect-ratio:1;margin:0 auto;display:grid;grid-template-columns:1.35fr repeat(7,minmax(0,1fr)) 1.35fr;grid-template-rows:1.35fr repeat(7,minmax(0,1fr)) 1.35fr;gap:2px;padding:2px;border-radius:18px;background:#cdb789;box-shadow:0 0 0 5px #fff8e8,0 0 0 7px #d7c193,0 34px 64px -34px rgba(60,30,0,.7);direction:ltr}
.es-c{position:relative;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1px;min-width:0;min-height:0;overflow:hidden;padding:2px 2px;border:0;border-radius:3px;background:#fffaf0;color:#3b2a14;font:700 clamp(6px,1.02vw,11px)/1.15 var(--f-display);cursor:pointer;text-align:center}
.es-c:hover,.es-c:focus-visible{background:#fff;z-index:1;box-shadow:0 0 0 2px #f59e0b}
.es-c.k-go{background:linear-gradient(135deg,#dcffe9,#9eefc2)}
.es-c.k-jail{background:linear-gradient(135deg,#ffe6e6,#ffc2c2)}
.es-c.k-rest{background:linear-gradient(135deg,#fff5d4,#ffe08d)}
.es-c.k-gojail{background:linear-gradient(135deg,#e6ebff,#bac6ff)}
.es-c.k-chance{background:#effbe9}.es-c.k-chest{background:#fdf1e4}.es-c.k-tax{background:#f5eefb}
.es-c.k-rail,.es-c.k-util{background:#f7f4ee}
.es-c:first-child,.es-c.s-corner{border-radius:12px}
.es-band{position:absolute}
.es-c.s-b .es-band{top:0;left:0;right:0;height:20%}
.es-c.s-t .es-band{bottom:0;left:0;right:0;height:20%}
.es-c.s-l .es-band{top:0;bottom:0;right:0;width:20%}
.es-c.s-r .es-band{top:0;bottom:0;left:0;width:20%}
.es-c.s-b{padding-top:22%}.es-c.s-t{padding-bottom:22%}.es-c.s-l{padding-right:22%}.es-c.s-r{padding-left:22%}
.es-e{--s:clamp(14px,3.3vw,34px);filter:drop-shadow(0 2px 2px rgba(60,30,0,.25))}
.es-c.s-corner .es-e{--s:clamp(20px,4.6vw,46px)}
.es-n{max-width:100%;overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;word-break:break-word}
.es-p{font:800 clamp(6px,.92vw,10px)/1 var(--f-display);color:#8a6430}
.es-own{display:inline-grid;place-items:center;width:clamp(11px,2.1vw,20px);height:clamp(11px,2.1vw,20px);border-radius:50%;background:var(--c);color:#fff;font:800 clamp(6px,1vw,10px)/1 var(--f-display);box-shadow:0 0 0 1.5px #fff,0 1px 3px rgba(0,0,0,.3)}
.es-own svg{width:70%;height:70%}
.es-own.mort{opacity:.45;filter:grayscale(.7)}
.es-hs{position:absolute;display:flex;gap:1px;z-index:1}
.es-c.s-b .es-hs{top:3%;left:50%;transform:translateX(-50%)}
.es-c.s-t .es-hs{bottom:3%;left:50%;transform:translateX(-50%)}
.es-c.s-l .es-hs{right:4%;top:50%;transform:translateY(-50%);flex-direction:column}
.es-c.s-r .es-hs{left:4%;top:50%;transform:translateY(-50%);flex-direction:column}
.es-hs i{width:clamp(3px,.75vw,7px);aspect-ratio:1;background:#1fa658;border-radius:1.5px;box-shadow:0 0 0 1px #fff}
.es-hs.hotel .em{--s:clamp(9px,1.9vw,18px)}
.es-c.flash{animation:es-flash 1.1s ease-out}
@keyframes es-flash{0%{box-shadow:0 0 0 0 rgba(255,193,7,.9);background:#fff3c4}100%{box-shadow:0 0 0 10px rgba(255,193,7,0)}}
.es-center{grid-row:2/9;grid-column:2/9;position:relative;display:grid;place-items:center;background:radial-gradient(circle at 50% 38%,#fffdf6,#f1e4c6);border-radius:8px;overflow:hidden}
.es-center::before{content:'';position:absolute;inset:10%;border-radius:50%;background:repeating-conic-gradient(from 0deg,rgba(214,174,92,.12) 0 10deg,transparent 10deg 20deg);pointer-events:none}
.es-mid{position:relative;display:flex;flex-direction:column;align-items:center;gap:clamp(4px,1.1vw,12px);width:90%;direction:rtl;text-align:center}
.es-brand{display:flex;align-items:center;gap:6px;font:800 clamp(12px,2.4vw,26px)/1 var(--f-display);color:#8a3d10}
.es-brand .em{--s:clamp(16px,3vw,32px)}
.es-brand .fl{--s:clamp(20px,3.4vw,34px);border-radius:4px}
.es-dice{display:flex;gap:clamp(6px,1.4vw,14px)}
.es-dice .die{width:clamp(30px,7.6vw,64px);height:clamp(30px,7.6vw,64px);padding:clamp(5px,1.1vw,10px);gap:clamp(2px,.45vw,4px);border-radius:clamp(8px,1.8vw,16px)}
.es-dice .die.blank::after{font-size:clamp(14px,3vw,28px)}
.es-draw{display:flex;flex-direction:column;align-items:center;gap:2px;max-width:100%;padding:clamp(6px,1.2vw,12px) clamp(8px,1.6vw,16px);border-radius:14px;background:#fff;box-shadow:0 10px 24px -14px rgba(60,30,0,.6),inset 0 0 0 2px #7bd38e;animation:popin .4s cubic-bezier(.2,1.4,.4,1) both}
.es-draw.chest{box-shadow:0 10px 24px -14px rgba(60,30,0,.6),inset 0 0 0 2px #f2a65a}
.es-draw .em{--s:clamp(18px,3.4vw,30px)}
.es-draw b{font:800 clamp(10px,1.6vw,14px) var(--f-display);color:#3b2a14}
.es-draw span{font:600 clamp(10px,1.5vw,14px)/1.4 var(--f-body,inherit);color:#5b4a30}
.es-act{display:flex;flex-direction:column;align-items:center;gap:6px}
.es-act .btn{min-height:clamp(34px,6vw,46px);font-size:clamp(.78rem,1.6vw,1rem);padding-inline:clamp(10px,2vw,18px)}
.es-roll{font-size:clamp(.9rem,2vw,1.15rem)!important}
.es-q{margin:0;display:flex;align-items:center;justify-content:center;gap:5px;flex-wrap:wrap;font:700 clamp(11px,1.8vw,16px)/1.4 var(--f-display);color:#3b2a14}
.es-q .em{--s:clamp(16px,2.6vw,24px)}
.es-log{list-style:none;margin:0;padding:0;font:600 clamp(9px,1.35vw,13px)/1.45 var(--f-display);color:#7b6a4c;display:flex;flex-direction:column;gap:1px;max-width:100%}
.es-log li{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.es-log li.new{color:#3b2a14;font-weight:800}
.es-mine{font-size:clamp(.72rem,1.4vw,.9rem)!important;min-height:30px!important}
.es-toks{position:absolute;inset:0;pointer-events:none}
.es-tok{position:absolute;width:clamp(14px,3.5vw,30px);aspect-ratio:1;transform:translate(-50%,-50%);border-radius:50%;background:radial-gradient(circle at 34% 30%,color-mix(in srgb,var(--c) 35%,#fff),var(--c) 62%);border:2px solid #fff;box-shadow:0 4px 8px rgba(20,10,40,.45);display:grid;place-items:center;z-index:2;transition:left .25s,top .25s}
.es-tok b{display:grid;place-items:center;font:800 clamp(7px,1.35vw,13px)/1 var(--f-display);color:#fff;text-shadow:0 1px 2px rgba(0,0,0,.45)}
.es-tok b svg{width:1.2em;height:1.2em}
.es-tok.turn{z-index:3;animation:sl-bob .9s ease-in-out infinite alternate}
.es-tok.jailed{box-shadow:0 0 0 2px #e11d48,0 4px 8px rgba(20,10,40,.45)}
.es-over{position:absolute;inset:13.9%;display:grid;place-items:center;z-index:5;pointer-events:none}
.es-over>*{pointer-events:auto}
.es-card{width:min(100%,300px);max-height:100%;overflow:auto;border-radius:16px;background:#fff;box-shadow:0 22px 44px -16px rgba(0,0,0,.55);padding:0 0 10px;text-align:center;direction:rtl;display:flex;flex-direction:column;gap:6px;align-items:center}
.es-ch{width:100%;padding:12px 10px;color:#fff;display:flex;flex-direction:column;align-items:center;gap:2px;font:800 1.08rem/1.2 var(--f-display);text-shadow:0 1px 2px rgba(0,0,0,.25)}
.es-ch span{font-size:.72rem;opacity:.92}
.es-ch.plain{color:var(--fg);background:var(--surface-2);text-shadow:none}
.es-ch.plain b{display:flex;align-items:center;gap:6px}
.es-card table{width:88%;border-collapse:collapse;font-size:var(--fs-sm)}
.es-card td{padding:3px 6px;border-bottom:1px solid var(--line)}
.es-card td:last-child{text-align:end;font-weight:800;font-variant-numeric:tabular-nums}
.es-card tr.on td{background:#fff3c4}
.es-note{margin:0 12px;font-size:var(--fs-xs);color:var(--fg-2)}
.es-cf{display:flex;justify-content:space-between;align-items:center;gap:8px;width:88%;font:700 var(--fs-sm) var(--f-display)}
.es-cf span{display:inline-flex;align-items:center;gap:5px}
.es-cf .dot{width:9px;height:9px;border-radius:50%;background:var(--c)}
.es-panel{width:min(100%,380px)}
.es-list{list-style:none;padding:0 10px;margin:0;display:flex;flex-direction:column;gap:6px;width:100%}
.es-list li{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:6px 8px;border-radius:12px;background:var(--surface-2);border-inline-start:5px solid var(--g)}
.es-li-n{display:flex;align-items:center;gap:6px;min-width:0;text-align:start}
.es-li-n .em{--s:22px}
.es-li-n b{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-size:var(--fs-sm)}
.es-li-n small{color:var(--fg-2);white-space:nowrap}
.es-li-b{display:flex;gap:4px;flex-wrap:wrap;justify-content:flex-end}
.es-li-b .btn{min-height:30px;padding:4px 10px;font-size:.78rem}
.es-cash.out{opacity:.55;text-decoration:line-through}
@media (max-width:620px){
  .es-wrap{padding:2px 4px 18px}
  .es-board{gap:1px;padding:1px;border-radius:12px}
  .es-n{display:none}
  .es-brand{display:none}
  .es-log li:nth-child(n+3){display:none}
  .es-card{width:min(100%,280px)}
  .es-over{inset:6%}
}

/* ============================== 3D boards ============================== */
.bg-body.g3-body{padding-inline:0}
.g3-host{position:relative;width:100%;overflow:hidden;border-radius:26px;background:linear-gradient(180deg,#8fcbf0,#f3e4c4);box-shadow:0 30px 60px -36px rgba(20,30,60,.65),inset 0 0 0 1px rgba(255,255,255,.4)}
.g3-canvas{display:block;width:100%;height:100%;touch-action:manipulation;cursor:pointer;-webkit-tap-highlight-color:transparent}
.g3-wait{position:absolute;inset:0;display:grid;place-items:center}
.g3-host.ready .g3-wait{display:none}
.es3{position:relative;max-width:1240px;margin:0 auto;padding:0 10px 18px;display:grid;gap:12px;align-items:start}
.es3-host{height:clamp(380px,calc(100vh - 215px),860px)}
.es3-panel{position:relative;z-index:2;display:flex;flex-direction:column;align-items:center;gap:10px;padding:14px;border-radius:24px;background:var(--surface);box-shadow:var(--shadow);text-align:center;min-width:0}
.es3-panel .es-q{font-size:1rem;color:var(--fg)}
.es3-panel .es-act .btn{min-height:46px;font-size:1rem}
.es3-panel .es-roll{font-size:1.15rem!important;min-height:58px!important;padding-inline:28px!important}
.es3-panel .es-log{font-size:.82rem;color:var(--fg-2);gap:3px}
.es3-panel .es-log li{white-space:normal}
.es3-panel .es-log li.new{color:var(--fg)}
.es3-panel .es-draw span{font-size:.92rem}
.es3-panel .es-draw b{font-size:.95rem}
.es3-panel .es-draw .em{--s:30px}
.es3-panel .es-mine{font-size:.88rem!important;min-height:36px!important}
.es3-over{position:absolute;z-index:6;top:14px;left:50%;transform:translateX(-50%);width:min(calc(100% - 28px),390px);max-height:calc(100% - 28px);display:grid}
.es3-over .es-card{width:100%;max-height:min(70vh,560px)}
@media (min-width:900px){
  .es3{grid-template-columns:minmax(0,1fr) 300px}
  .es3-panel{position:sticky;top:150px}
  .es3-over{left:auto;right:auto;transform:none;inset-inline-start:24px}
}
@media (max-width:899px){
  .es3-host{height:min(122vw,calc(100vh - 250px));min-height:360px}
}
/* the 3D switch in the game's top bar */
.bg-3d b{font:800 .78rem/1 var(--f-display);letter-spacing:-.02em}
.bg-3d.on{background:var(--c);color:var(--on-c);box-shadow:0 6px 14px -8px var(--c)}
/* إكس أو */
.xo3{position:relative;display:flex;flex-direction:column;align-items:center;gap:10px;max-width:900px;margin:0 auto;padding:0 10px 16px}
.xo3-host{width:min(100%,760px);aspect-ratio:1;max-height:calc(100vh - 230px);min-height:320px;background:linear-gradient(180deg,#b7a6ff,#ffeede)}
.xo3-keys{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
.xo3-keys:focus-within{position:static;width:auto;height:auto;clip-path:none;display:grid;grid-template-columns:repeat(3,44px);gap:6px}
.xo-k{display:grid;place-items:center;height:44px;border-radius:12px;border:0;background:var(--surface-2);font:800 1rem var(--f-display);color:var(--fg)}
button.xo-k{background:var(--surface);box-shadow:inset 0 0 0 2px var(--c);cursor:pointer}
/* السلّم والحيّة */
.sl3{position:relative;max-width:1240px;margin:0 auto;padding:0 10px 18px;display:grid;gap:12px;align-items:start}
.sl3-host{height:clamp(380px,calc(100vh - 215px),860px);background:linear-gradient(180deg,#6cc1f2,#9dd27a)}
.sl3-panel{position:relative;z-index:2;display:flex;flex-direction:column;align-items:center;gap:12px;padding:16px;border-radius:24px;background:var(--surface);box-shadow:var(--shadow);text-align:center;min-width:0}
.sl3-panel .sl-roll{width:100%;min-height:58px;font-size:1.15rem}
.sl3-pos{list-style:none;margin:0;padding:0;width:100%;display:flex;flex-direction:column;gap:6px}
.sl3-pos li{display:flex;align-items:center;gap:8px;padding:6px 12px;border-radius:14px;background:var(--surface-2);font:700 var(--fs-sm) var(--f-display)}
.sl3-pos li.on{background:color-mix(in srgb,var(--c) 16%,var(--surface));box-shadow:inset 0 0 0 2px color-mix(in srgb,var(--c) 55%,transparent)}
.sl3-pos .dot{width:12px;height:12px;border-radius:50%;background:var(--c);flex:none}
.sl3-pos b{flex:1;text-align:start;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.sl3-pos span{font:800 1rem var(--f-display);font-variant-numeric:tabular-nums}
@media (min-width:900px){
  .sl3{grid-template-columns:minmax(0,1fr) 280px}
  .sl3-panel{position:sticky;top:150px}
}
@media (max-width:899px){
  .sl3-host{height:min(118vw,calc(100vh - 290px));min-height:340px}
  .sl3-pos{flex-direction:row;flex-wrap:wrap;justify-content:center}
  .sl3-pos li{padding:4px 10px}
  .sl3-pos b{max-width:6em}
}
/* the view buttons over a board: from above or at an angle, zoom in and out */
.g3-ctl{position:absolute;z-index:3;left:10px;bottom:10px;display:flex;gap:6px;direction:rtl}
.g3-b{display:inline-flex;align-items:center;justify-content:center;gap:5px;min-width:44px;height:44px;padding:0 10px;border:0;border-radius:14px;background:rgba(255,255,255,.92);color:#2a1a5e;font:800 .85rem/1 var(--f-display);box-shadow:0 6px 16px -6px rgba(20,10,60,.45),inset 0 0 0 1px rgba(40,20,90,.08);cursor:pointer;-webkit-tap-highlight-color:transparent;-webkit-backdrop-filter:blur(4px);backdrop-filter:blur(4px)}
.g3-b .ic{width:20px;height:20px}
.g3-b:disabled{opacity:.45;cursor:default}
.g3-b:not(:disabled):active{transform:scale(.94)}
.g3-view[aria-pressed="true"]{background:#2a1a5e;color:#fff}
@media (max-width:620px){.g3-ctl{left:8px;bottom:8px}.g3-b{height:40px;min-width:40px;border-radius:12px}}

/* ============================== تحدّي لمّات على الطاولة (g_quiz.js) ============================== */
.qz{--u:6px;width:100%;max-width:760px;margin:0 auto;padding:4px 0 24px;display:flex;flex-direction:column;gap:14px}
.qz-pick{display:flex;flex-direction:column;gap:12px}
.qz-head{margin:0;display:flex;align-items:center;justify-content:center;gap:8px;font:800 1.2rem/1.3 var(--f-display);text-align:center}
.qz-head .em{--s:26px}
.qz-whose{margin:0;display:flex;align-items:center;justify-content:center;gap:8px;font:700 var(--fs-sm)/1.3 var(--f-body);color:var(--fg)}
.qz-whose .muted{font-weight:600}
.qz-board{display:grid;grid-template-columns:repeat(var(--k),minmax(0,1fr));gap:10px}
.qz-col{display:flex;flex-direction:column;gap:9px;min-width:0;animation:qzin .4s cubic-bezier(.2,1.3,.4,1) var(--d,0s) both}
.qz-cat{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px;min-height:92px;padding:10px 6px;border-radius:18px;text-align:center;
  background:color-mix(in srgb,var(--c) 20%,var(--surface));box-shadow:inset 0 0 0 2px color-mix(in srgb,var(--c) 45%,transparent)}
.qz-cat .em,.qz-cat .fl{--s:34px;width:34px;height:34px}
.qz-cat b{font:800 .92rem/1.25 var(--f-display);display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;overflow-wrap:anywhere}
.qz-cell{position:relative;display:grid;place-items:center;min-height:62px;border-radius:18px;border:0;font:800 1.45rem/1 var(--f-display);color:var(--on-c);background:var(--c);
  box-shadow:0 5px 0 color-mix(in srgb,var(--c) 62%,#000),inset 0 2px 0 rgba(255,255,255,.35);cursor:default;padding:0}
button.qz-cell{cursor:pointer;transition:transform .12s,box-shadow .12s,filter .12s}
button.qz-cell:hover{transform:translateY(-2px);filter:brightness(1.06)}
button.qz-cell:active{transform:translateY(3px);box-shadow:0 2px 0 color-mix(in srgb,var(--c) 62%,#000)}
.my-turn button.qz-cell{animation:qzglow 1.6s ease-in-out infinite}
.qz-cell.done{background:var(--surface-2);color:var(--fg-3);box-shadow:inset 0 0 0 2px var(--line-2)}
.qz-cell.done b{font-size:1.05rem;text-decoration:line-through;opacity:.7}
.qz-cell.done i{position:absolute;inset-block-start:-7px;inset-inline-end:-7px;width:28px;height:28px;border-radius:50%;display:grid;place-items:center;font:800 .8rem/1 var(--f-display);font-style:normal;
  background:var(--fg-3);color:var(--surface);box-shadow:0 2px 6px rgba(20,10,60,.25)}
.qz-cell.done i .ic{width:16px;height:16px}
.qz-cell.s1{background:color-mix(in srgb,var(--good) 18%,var(--surface));box-shadow:inset 0 0 0 2px color-mix(in srgb,var(--good) 60%,transparent);color:var(--fg)}
.qz-cell.s1 b{text-decoration:none;opacity:1}
.qz-cell.s1 i{background:var(--good);color:var(--on-good)}
.qz-cell.s2 i{background:var(--bad);color:var(--on-bad)}
.qz-cell.s3{background:color-mix(in srgb,var(--c) 22%,var(--surface));box-shadow:inset 0 0 0 2px color-mix(in srgb,var(--c) 60%,transparent);color:var(--fg)}
.qz-cell.s3 i{background:var(--c);color:var(--on-c)}

.qz-q{position:relative;display:flex;flex-direction:column;align-items:stretch;gap:12px;padding:16px 16px 18px;border-radius:26px;background:var(--surface);overflow:hidden;
  box-shadow:0 0 0 2px color-mix(in srgb,var(--c) 40%,var(--line-2)),0 18px 40px -26px rgba(20,10,60,.55);animation:qzin .35s cubic-bezier(.2,1.2,.4,1) both}
.qz-q.steal{box-shadow:0 0 0 3px var(--pome),0 18px 40px -26px rgba(20,10,60,.55)}
.qz-qh{display:flex;align-items:center;justify-content:space-between;gap:10px}
.qz-qcat{display:inline-flex;align-items:center;gap:8px;min-width:0;padding:6px 12px 6px 8px;border-radius:999px;background:color-mix(in srgb,var(--c) 18%,var(--surface-2))}
.qz-qcat .em,.qz-qcat .fl{--s:24px;width:24px;height:24px;flex:none}
.qz-qcat b{font:800 .95rem/1.2 var(--f-display);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.qz-val{flex:none;padding:5px 14px;border-radius:999px;background:var(--c);color:var(--on-c);font:800 1.15rem/1.2 var(--f-display);box-shadow:0 3px 0 color-mix(in srgb,var(--c) 62%,#000)}
.qz-tbar{position:absolute;inset-block-start:0;inset-inline:0;height:6px;background:var(--c);transform-origin:left;animation:qztb var(--dur) linear var(--del) forwards}
.qz-line{margin:0;display:flex;flex-wrap:wrap;align-items:center;justify-content:center;gap:6px;font:700 1rem/1.4 var(--f-body);text-align:center;color:var(--fg-2)}
.qz-line .em{--s:22px}
.qz-line small{font-weight:600;color:var(--fg-3)}
.qz-line.good{color:color-mix(in srgb,var(--good) 75%,var(--fg));font:800 1.25rem/1.3 var(--f-display);animation:qzpop .45s cubic-bezier(.2,1.5,.4,1)}
.qz-line.bad{color:var(--fg-2);font:800 1.15rem/1.3 var(--f-display)}
.qz-gain{display:inline-block;padding:2px 10px;border-radius:999px;background:var(--good);color:var(--on-good);font:800 1.05rem/1.3 var(--f-display)}
.qz-media{display:flex;justify-content:center}
.qz-media .mstage,.qz-media .mstage.compact{height:min(30vh,230px)}
.qz-text{margin:0;font:800 1.32rem/1.5 var(--f-display);text-align:center;overflow-wrap:anywhere}
.qz-opts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}
.qz-o{display:flex;align-items:center;gap:10px;min-height:58px;padding:10px 12px;border-radius:16px;border:2px solid var(--line-2);background:var(--surface-2);color:var(--fg);
  font:700 1.05rem/1.35 var(--f-body);text-align:start;overflow-wrap:anywhere;animation:qzin .32s cubic-bezier(.2,1.2,.4,1) var(--d,0s) both}
.qz-o span{min-width:0}
button.qz-o{cursor:pointer;transition:transform .12s,border-color .12s,background .12s}
button.qz-o:hover{transform:translateY(-2px);border-color:color-mix(in srgb,var(--c) 70%,var(--line-2));background:color-mix(in srgb,var(--c) 10%,var(--surface-2))}
button.qz-o:active{transform:translateY(2px)}
.qz-l{flex:none;width:30px;height:30px;border-radius:50%;display:grid;place-items:center;background:color-mix(in srgb,var(--c) 85%,#fff);color:var(--on-c);font:800 .95rem/1 var(--f-display);font-style:normal}
.qz-opts.two .qz-o{justify-content:center;text-align:center;min-height:72px;font:800 1.15rem/1.35 var(--f-display)}
.qz-o.right{background:var(--good);border-color:var(--good);color:var(--on-good);animation:qzpop .45s cubic-bezier(.2,1.5,.4,1) both}
.qz-o.right .qz-l{background:var(--on-good);color:var(--good)}
.qz-o.bad{background:color-mix(in srgb,var(--bad) 16%,var(--surface));border-color:var(--bad);animation:qzshake .4s ease both}
.qz-o.bad .qz-l{background:var(--bad);color:var(--on-bad)}
.qz-o.dim{opacity:.45}
.qz-o.out{opacity:.35;text-decoration:line-through;border-style:dashed}
.qz-x{margin:0;display:flex;align-items:flex-start;justify-content:center;gap:6px;font:600 var(--fs-sm)/1.5 var(--f-body);color:var(--fg-2);text-align:center}
.qz-x .ic{flex:none;width:18px;height:18px;margin-top:2px;color:var(--good)}
.qz-x b{color:var(--fg)}
@keyframes qzin{from{opacity:0;transform:translateY(10px) scale(.96)}to{opacity:1;transform:none}}
@keyframes qzpop{0%{transform:scale(.9)}55%{transform:scale(1.05)}100%{transform:none}}
@keyframes qzshake{0%,100%{transform:none}20%{transform:translateX(-6px)}40%{transform:translateX(6px)}60%{transform:translateX(-4px)}80%{transform:translateX(3px)}}
@keyframes qztb{from{transform:scaleX(1)}to{transform:scaleX(0)}}
@keyframes qzglow{0%,100%{box-shadow:0 5px 0 color-mix(in srgb,var(--c) 62%,#000),inset 0 2px 0 rgba(255,255,255,.35)}50%{box-shadow:0 5px 0 color-mix(in srgb,var(--c) 62%,#000),inset 0 2px 0 rgba(255,255,255,.35),0 0 0 4px color-mix(in srgb,var(--c) 35%,transparent)}}
@media (max-width:460px){
  .qz-board{gap:7px}
  .qz-cat{min-height:84px;padding:8px 4px;border-radius:15px}
  .qz-cat b{font-size:.8rem}
  .qz-cell{min-height:56px;font-size:1.25rem;border-radius:15px}
  .qz-text{font-size:1.18rem}
  .qz-o{min-height:54px;font-size:.98rem;padding:9px 10px;gap:8px}
}
@media (max-width:360px){.qz-opts{grid-template-columns:1fr}.qz-opts.two{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media (prefers-reduced-motion:reduce){.qz-col,.qz-q,.qz-o,.qz-line.good{animation:none}.my-turn button.qz-cell{animation:none}.qz-tbar{animation-duration:0s}}
/* the trivia setup's «كيف بدك تلعبوا؟» */
.su-ways .bg-modes{grid-template-columns:repeat(4,minmax(0,1fr))}
.su-ways .bg-mode[aria-pressed="true"]{border-color:var(--tc,var(--saffron));background:color-mix(in srgb,var(--tc,var(--saffron)) 12%,var(--surface))}
@media (max-width:760px){.su-ways .bg-modes{grid-template-columns:repeat(2,minmax(0,1fr))}}

